quests[26861] = { id = 26861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blockiert die Tore", description = "Wenn wir eine Chance gegen Abyssion haben wollen, müssen wir sicherstellen, dass ihn keine Verstärkung zur Unterstützung erreicht.\n\nIn seinem Hort gen Osten werdet Ihr zwei Tore vorfinden. Benutzt diesen Sturmstein, um ihre Funktion zu unterbinden.\n\nWenn alles so läuft wie geplant, werden wir Abyssion angreifen können, ohne dass er viel Unterstützung bekommt.", sourceObjective = "Benutzt den Sturmstein am Zwielichttor und Elementartor in Abyssions Hort.", progress = "Ihr seid zurück, {name}. Sind die Tore geschlossen?", completion = "Ausgezeichnet. Wenn wir gegen Abyssion ziehen, sollten wir keine Gefahr durch seine Verstärkung zu fürchten haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26862] = { id = 26862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verpfuschte Elementare", description = "Die Hexenmeister der Sengenden Klinge haben die Geister der Elementare in Flammenschlund versklavt, {name}. Solange mein Zauber sie im Zaum hält, stellen sie keine Bedrohung für die Stadt dar, aber ich kann ihn nicht mehr lange aufrecht halten.\n\nBringt mir sechs der sengenden Bindungen, mit denen sie unter Kontrolle gehalten werden und ich werde ihre Geister im Flammenschlund wieder freisetzen.", sourceObjective = "Beschafft 6 sengende Bindungen.", progress = "Habt Ihr die Bindungen?", completion = "Ich danke Euch, {class}. Die Geister der geschmolzenen Elementare haben endlich ihre Ruhe gefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26863] = { id = 26863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmutzige Pfoten", description = "Die Silberbachmine im Osten hat sich schon vor langer Zeit erschöpft. Sie wurde vom Bund der Bergarbeiter in ein Lagerhaus umgewandelt, aber jetzt sind dort Kobolde eingezogen und befingern mit ihren schmutzigen Pfoten gute zwergische Werkzeuge!\n\nWir werden dieses Ungeziefer noch früh genug ausmerzen, aber der Bund wünscht, dass jemand ihre Gerätschaften aus der Mine schafft, bevor wir Krieger da reinstürmen und was kaputtmachen. Das wird ein harter Abstieg – Ihr solltet vielleicht Unterstützung mitnehmen.\n\nDie Ausstattung wird in Kisten des Bergarbeiterbunds über die Mine verteilt aufbewahrt. Viel Glück.", sourceObjective = "Sucht in der Silberbachmine 6 Sätze Minenarbeiterausstattung zusammen.", progress = "Habt Ihr die Minenarbeiterausstattung, {name}?", completion = "Habt Ihr da drin viele Kobolde gesehen? Der Gedanke daran, wie ihre schmutzigen Hände in unserer Mine herumkratzen, verursacht mir Bauchschmerzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26864] = { id = 26864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopflos", description = "Ihr müsst das hier zu Gebirgsjäger Kadrell bringen. Zeigt es ihm und sagt ihm, dass die fiesen Plagegeister hier möglicherweise eine Art Versammlung abhalten werden.", sourceObjective = "Bringt den Kopf von Vorarbeiter Scharfspott zu Gebirgsjäger Kadrell.", progress = "Gibt es Neuigkeiten von der Station Algaz?", completion = "Gnolle, Kobolde und Troggs? Au weia.\n\nIch würde glatt lachen, wenn ich nicht noch eine andere unerwartete Wendung der Geschichte für Euch hätte.", sourceObjectiveStatus = "unverified-source-field" }
quests[26865] = { id = 26865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind tief unten", description = "Unter dieser Stadt, befinden sich Feinde der Horde, {class}.\n\nDie Angehörigen der Sengenden Klinge planen, Orgrimmar für sich zu übernehmen und sie haben bereits den Flammenschlund überrannt! Wir müssen gegen ihre Truppen anstürmen und zurückerobern, was uns gehört!\n\nGeht und sprecht mit Steinwächter Kurjack im Flammenschlund. Er hat weitere Instruktionen für Euch.", sourceObjective = "Sprecht mit Steinwächter Kurjack.", completion = "Ich habe Eure Ankunft erwartet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26866] = { id = 26866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind tief unten", description = "Der Flammenschlund in Orgrimmar wurde von der Sengenden Klinge übernommen. {name}, wir können das nicht ungestraft durchgehen lassen, sonst richten sie ihren Blick als Nächstes auf Donnerfels.\n\nGeht und sprecht mit Steinwächter Kurjack im Flammenschlund. Helft ihm auf jede erdenkliche Art und Weise, da unsere Schicksale miteinander verknüpft sind.", sourceObjective = "Sprecht mit Steinwächter Kurjack.", sourceObjectiveStatus = "unverified-source-field" }
quests[26867] = { id = 26867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind tief unten", description = "Kriegshäuptling Garrosh hat unter Aufbietung all seines wohlbekannten Liebreizes freundlich um Eure Anwesenheit im Flammenschlund gebeten, damit Ihr ihm helfen könnt, diesen von der Sengenden Klinge zurückzuerobern. Offensichtlich ist seine verstärkte Stadt nicht so uneinnehmbar, wie er dachte.\n\nGeht und sprecht mit Steinwächter Kurjack im Flammenschlund. Ich bin sicher, dass er über fähige Hilfe sehr froh sein wird.", sourceObjective = "Sprecht mit Steinwächter Kurjack.", sourceObjectiveStatus = "unverified-source-field" }
quests[26868] = { id = 26868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Achse des Grässlichen", description = "So, also nun haltet mal die Klappe und lasst mich reden. Der Plan sieht so aus...\n\nDiese Gnolle und Murlocs werden sich wahrscheinlich hier draußen irgendwo treffen. Also nehmt Ihr dieses clevere Pflanzenverkleidungsset von mir, zieht es an und seht wie eine Pflanze aus. Dann schleicht Ihr Euch an sie heran und werft die Geruchspheromone, die ihr gesammelt habt, über die Moosfelle, die bei den Murlocs stehen.\n\nDann brennen bei den Murlocs die Sicherungen durch und die Moosfelle werden es sich zweimal überlegen, ehe sie wieder mit diesen verrückten kleinen Nervensägen zusammenarbeiten.", sourceObjective = "Benutzt das clevere Pflanzenverkleidungsset, um Euch an den Repräsentanten der Moosfelle heranzuschleichen. Dann bestäubt ihn mit den starken Murlocpheromonen.", completion = "Hat doch wunderbar geklappt, oder nicht? Vielleicht fällt Kadress mir jetzt endlich nicht mehr auf die Nerven, nachdem ich die Stadt gerettet hab' und so.\n\nIhr habt Euch wohl auch ein paar anständige Sachen verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[26869] = { id = 26869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefe der Tiefen", description = "<Der Boden unter Euren Füßen erzittert leicht und die tiefe, bekannte Stimme von Diamant scheint aus dem Stein selbst zu sprechen.>\n\nGut gemacht, {race}.\n\nIn den unterirdischen Tunneln werdet Ihr den Stein, den Ihr sucht, finden. Painit.\n\nDie Gefahren, die vor Euch liegen sind mannigfaltig...\n\nGefahren, die sogar die Steinlords selbst fürchten.\n\nBleibt ruhig.\n\nBleibt stark.\n\nDie Stärke des Felsens ruht unter Euren Füßen.", sourceObjective = "Findet das Painit in den Bruchtiefen.", completion = "<Das ist er. Das ist der Stein, den Ihr für Diamant holen solltet.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26870] = { id = 26870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säuberung der Höhlen", description = "Naralex hatte ein edles Ziel.\n\nUnser großer Anführer hatte sich vorgenommen, den Smaragdgrünen Traum zu betreten und dabei zu helfen, dieses unwirtliche Land wieder zu dem üppigen Wald zu machen, der es einst gewesen war. Aber etwas ging furchtbar schief.\n\nDie treuen Verbündeten von Naralex, die Druiden des Giftzahns, wandten sich gegen ihn! Ihr Ziel ist es nicht, das Brachland zu heilen, sondern es zu beherrschen. {name}, bevor wir Naralex erwecken und das Gleichgewicht an diesem wichtigen Ort wiederherstellen können, müsst Ihr die Giftzahnlords auslöschen. Ihr Einfluss ist viel zu groß geworden.", sourceObjective = "Ebru in den Höhlen des Wehklagens möchte, dass Ihr die Giftzahnlords Cobrahn, Anacondra, Pythas und Serpentis vernichtet.", completion = "Ich spüre bereits, wie das Gleichgewicht zurückkehrt! Schnell, sprecht mit Muyoh und helft ihm, Naralex zu erwecken!", sourceObjectiveStatus = "unverified-source-field" }
quests[26871] = { id = 26871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Fels unter vielen", description = "<Der Boden unter Euren Füßen erzittert leicht und die tiefe, bekannte Stimme von Diamant scheint aus dem Stein selbst zu sprechen.>\n\nIhr habt das getan, worum ich gebeten hatte.\n\nGeht zurück und verlasst die Höhle unverletzt.\n\nVergesst den Edelstein nicht.", sourceObjective = "Kehrt mit dem Painitbrocken zu Diamant an Lorthunas Tor zurück.", progress = "Ihr lebt. Das ist gut.\n\nTragt Ihr den Edelstein bei Euch?", completion = "Gut gemacht, Fleischling!\n\nDie Tunnelgräber zählen zu unseren gefährlichsten Feinden.\n\nDie anderen Steinlords werden diesen Erfolg nicht ignorieren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[26872] = { id = 26872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deviatbälge", description = "Als Naralex tiefer in seinen Alptraum vorstieß, stieg eine seltsame Schar von Bestien unter dem Brachland in die Höhlen des Wehklagens vor.\n\nDiese Deviatkreaturen haben seltsame, überirdische Eigenschaften. Ihre bloße Existenz verursacht der Welt große Schmerzen. Ich glaube, dass ihr Tod unseren Versuchen, den Höhlen Heilung zu bringen, sehr helfen wird.\n\nWenn Ihr Euch der Aufgabe gewachsen fühlt, steigt in die Höhlen hinab, tötet so viele wie möglich und bringt mir ihre Bälge als Beweis ihres Ablebens.", sourceObjective = "Nalpak möchte 10 Deviatbälge.", progress = "Wie viele dieser Bestien konntet Ihr töten?", completion = "Eure Bemühungen werden nicht unbemerkt bleiben, {name}.\n\nVielen Dank für Eure Mühe.", sourceObjectiveStatus = "unverified-source-field" }
quests[26873] = { id = 26873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbeugende Maßnahmen", description = "In diesen Höhlen befindet sich ein Kraut mit unvorstellbaren Kräften, {name}. Möchtet Ihr mir helfen, es zu sammeln?\n\nEs handelt sich um eine seltene Blume mit Namen Schlangenflaum. Ich glaube, dass große Mengen davon weitere Alpträume, wie den von Naralex in Zukunft verhindern können.\n\nLeider findet man Schlangenflaum nur in den dunkelsten Ecken dieses Ortes.", sourceObjective = "Nalpak möchte, dass Ihr 5 Schlangenflaum sammelt.", progress = "Ich bin gespannt, ob Ihr genug Schlangenflaum sammeln könnt.", completion = "Gut gemacht, {name}. Hoffentlich können wir sie benutzen, um weitere Alpträume zu verhindern.", sourceObjectiveStatus = "unverified-source-field" }
quests[26874] = { id = 26874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Auferstehung von Naralex", description = "Jetzt, da die Giftzahnlords tot sind, sprecht mit Muyoh. Er wird Euch dabei helfen, Naralex aufzuwecken und diesen Alptraum zu beenden.", sourceObjective = "Sprecht mit Muyoh.", sourceObjectiveStatus = "unverified-source-field" }
quests[26875] = { id = 26875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsterbliches Zwielicht", description = "Die Schattenhammerkultisten sind hier! Sie versuchen, das Ritual zu verhindern! Geht zurück in die Kammern und wehrt sie ab!", sourceObjective = "Tötet 12 Zwielichteindringlinge und 1 entweihten Erdwüter.", completion = "Immer mehr Zwielichttruppen strömen herein, aber offenbar können die Verteidiger des Irdenen Rings ihrer Herr werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26876] = { id = 26876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Weltensäulenfragment", description = "Es wird Zeit, {name}. Wir haben Abyssion erspäht, auf dem Weg zu seinem Hort.\n\nDer Schattenhammer dachte wahrscheinlich, dass das Fragment sicher ist, wenn ein Drache es bewacht, aber ich habe genug Drachen gesehen und kenne ihre einzige Schwäche. Stolz.\n\nAbyssion wird nicht vor einem Kampf mit uns kläglichen Sterblichen davonlaufen.\n\nStellt das Banner des Irdenen Rings in die Mitte seines Horts. Wenn wir ihn besiegt haben, bringt das Fragment zu Maruut. Wir müssen die Weltensäule so bald wie möglich reparieren.", sourceObjective = "Stellt das Banner des Irdenen Rings in der Mitte von Abyssions Hort auf, tötet ihn und nehmt das erste Weltensäulenfragment an Euch.", progress = "{name}! Ihr seid zurückgekehrt!", completion = "Eure Bemühungen, die Weltensäule zu reparieren, sind von unschätzbarem Wert, {name}. Sobald der Tempel der Erde wieder stabil ist, wird auch der Riss zwischen den Welten sich stabilisieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26878] = { id = 26878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jünger von Naralex", description = "{class}, das Brachland war einst einer der schönsten Orte in ganz Kalimdor. Es war vielversprechend und voller Leben.\n\nWie Ihr seht, ist das nicht länger der Fall. Es ist ein Land voller Qual und Zwietracht.\n\nDie Jünger von Naralex wollen die Höhlen des Wehklagens säubern und sie in ihrer früheren Schönheit wiederherstellen. Sprecht in den Höhlen des Wehklagens hinter dem Eingang mit Nalpak.", sourceObjective = "Sprecht in den Höhlen des Wehklagens mit Nalpak.", completion = "Ja, {class}? Was bringt Euch an diesen Ort?", sourceObjectiveStatus = "unverified-source-field" }
quests[26881] = { id = 26881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Thaelrid", description = "Finstere Dinge gehen an diesem Ort vor sich, {name}. Wir fürchten, dass die Gerüchte über eine Zusammenarbeit der Naga mit dem Schattenhammer wahr sind.\n\nIch habe Thaelrid, einen unserer besten Späher, ausgeschickt, um der Angelegenheit nachzugehen. Doch er ist nicht zurückgekommen.\n\nFindet ihn. Wenn er noch lebt, findet heraus, was er entdeckt hat.", sourceObjective = "Sucht Späher Thaelrid auf.", completion = "Gut, dass Ashelan Euch geschickt hat. An diesem Ort der Verderbnis wird ein finsterer Plan geschmiedet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26882] = { id = 26882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schurkerei in der Tiefschwarzen Grotte", description = "Meine Kräfte haben mich verlassen. Ich brauche Eure Hilfe!\n\nDiese Stätte war einst ein großer Tempel von Elune. Doch das Unglück führte zum Untergang, als die Verderbnis eines Alten Gottes unter der Erde emporwallte und den heiligen Mondbrunnen besudelte.\n\nAku'mai, ein Diener des Alten Gottes, erhob sich aus den Wassern.\n\nDie Kultisten des Schattenhammers haben sich mit den Naga verbündet, um diesen Ort zu besetzen. Die Kultisten opfern unter Führung von Kelris Unschuldige für Aku'mai, um Macht zu erlangen.\n\nErschlagt Kelris und bringt seinen Kopf zu Ashelan.", sourceObjective = "Holt den Kopf von Zwielichtfürst Kelris.", progress = "Schön, Euch wiederzusehen, {name}. Welche Neuigkeiten bringt Ihr?\n\nWar Euer Vorstoß erfolgreich? Habt Ihr Thaelrid gefunden?", completion = "Kelris hat sich uns schon seit geraumer Zeit entzogen.\n\nOffenbar war Kelris immer dann beteiligt, wenn sich in dieser Gegend das Böse zeigte. Wir glaubten seit einiger Zeit, er sei entweder tot oder vermisst.\n\nAber das hier passt alles wunderbar zusammen. Indem Ihr seiner Herrschaft ein Ende gesetzt habt, rettet ihr die Leben vieler unschuldiger Menschen.\n\nEinem Diener eines Alten Gottes Opfer zu bringen, nur um sich persönliche zu bereichern ist mehr als verabscheuungswürdig!\n\nIhr habt eine große Tat vollbracht, {name}. Ich danke Euch in Namen Eschentals.\n\nIch wünschte nur, Thaelrid hätte überlebt...", sourceObjectiveStatus = "unverified-source-field" }
quests[26883] = { id = 26883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stunde der Finsternis", description = "Mit der Macht der uralten Rituale der chaotischen Alten Götter versuchen die Mitglieder des Schattenhammers, ihre dunklen Schutzherren zurückzuholen und Tod und Schrecken in der Welt zu verbreiten.\n\nWir glauben, dass der Schattenhammer sich mit den Naga verbündet hat und sich ihre Anhänger hier zusammenrotten.\n\nWelch schändliche Pläne in den Tiefen des alten Tempels auch immer geschmiedet werden, wir müssen sie vereiteln.\n\nFührt Krieg gegen den Schattenhammer und bringt Beweise Eurer Taten mit. Eure Bemühungen sollen reich belohnt werden.", sourceObjective = "Bringt 3 Zwielichtanhänger an Euch.", progress = "Die Tiefschwarze Grotte war einst ein uralter Tempel der Nachtelfen. Er beherbergte einen äußerst mächtigen Mondbrunnen. Wer weiß, was der Schattenhammer hier Böses ausbrütet.\n\nHabt Ihr Fortschritte dabei gemacht, den Tempel von ihrer Anwesenheit zu befreien?", completion = "Zweifellos seid Ihr tapfer und von noblem Geblüt, {name}. Wir und alle Menschen in Eschental preisen Euch für Eure Bemühungen gegen das Böse.", sourceObjectiveStatus = "unverified-source-field" }
quests[26884] = { id = 26884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erforschung der Verderbnis", description = "Törichte Blutelfen spielen mit Dämonenmagie. Wurden sie nicht Zeugen, was mit den Naga und den Satyrn von Kalimdor geschehen ist?\n\nIch fürchte, die Blutelfen werden auf ähnliche Weise deformiert. Azeroth darf kein weiteres Volk abscheulicher Monster hervorbringen.\n\nIch möchte die Hirnstämme der Satyrn und Naga untersuchen, damit ich daraus folgern kann, welches Schicksal die Elfen erwartet. Versucht die Hirnstämme nicht zu beschädigen während Ihr sie tötet, ich brauche ausschließlich makellose Exemplare.", sourceObjective = "Sammelt 8 verderbte Hirnstämme.", progress = "Wenn ich genügend Proben habe, kann meine wahre Arbeit beginnen. Mit den verderbten Hirnstämmen der Satyrn und Naga der Tiefschwarzen Grotte kann ich versuchen, einen Zusammenhang zwischen den Mutationen zu finden.\n\nMit diesem Wissen verhindern wir vielleicht, dass die Blutelfen noch deformierter und böser werden.", completion = "Ihr habt zweifellos großen Gefahren getrotzt, um diese hier zu bekommen.\n\nEure Taten waren selbstlos. Es dient ganz Azeroth, wenn Ihr mir bei meinen Forschungen helft. Ich danke Euch für alles, was Ihr getan habt, {name}.\n\nWenn Ihr mich nun entschuldigen würdet, ich habe viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[26885] = { id = 26885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen in der Tiefe", description = "Wie Ihr vielleicht wisst, ist es meine Pflicht als Auszubildende, Lehren für meine Vorgesetzten zusammenzutragen. Alte Lehren. Mächtige Lehren. Lehren, die Portale öffnen, und Lehren, die die schlafenden Alten Götter erwecken können, wenn sie missbraucht werden.\n\nEs kursieren Gerüchte um einen alten Text, das 'Manuskript von Lorgalis', das sich tief auf dem Boden des Teichs von Ask'ar befindet, in einer eingedellten Eisentruhe. Dieser Ort ist die ehemalige Heimat unserer längst verstorbenen Ahnen, die über großes Wissen verfügten, bevor ihre Stadt zerfiel.\n\nSucht das Manuskript, bitte. Ich verfüge nicht über genug Fähigkeiten, um weiter voranzuschreiten!", sourceObjective = "Findet das Manuskript von Lorgalis.", progress = "Eure Aufgabe ist keine leichte, mein Freund.\n\nAber wenn Ihr mir das Manuskript besorgt, {name}... dann gebührt Euch eine großzügige Belohnung und wir erhalten ein besseres Verständnis davon, was der Schattenhammer und die Naga im Schilde führen.", completion = "Ihr habt das Manuskript gefunden! Was für ein Freudentag! Ich werde es gründlich studieren und alles lernen, was es zu lernen gibt.\n\nIch werde es doch noch zur Schildwache bringen!\n\nIhr habt uns einen größeren Dienst erwiesen, als Ihr ahnt, {name}. Ich hoffe, dieses Geschenk zeigt Euch meine Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[26886] = { id = 26886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genug gebrüllt", description = "Das fiese Schiff auf der Nordseite der Bucht feuert ständig seine Kanonen auf uns ab. Es ist ja ganz lustig zuzusehen, wie die Goblins von Kanonenkugeln getroffen werden, aber einige meiner Gnomfreunde werden auch getroffen!\n\nEs wäre wirklich sehr nett, wenn Ihr es schafft, Euch an den Kanonen vorbei auf das Schiff zu begeben. Da ist ein gemeiner alter Zuchtmeister, der die anderen Deckmatrosen anschreit. Ich bin sicher, wenn Ihr ihn verprügelt oder tötet, werden sie nicht länger auf uns schießen!", sourceObjective = "Tötet den Zuchtmeister der Südmeerfreibeuter.", completion = "Wunderbar! Ich hoffe, Ihr wurdet nicht von zu vielen Kanonenkugeln getroffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26887] = { id = 26887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir füllen uns die Taschen", description = "Ich weiß, wir sind hier um uns mit den Dampfdruckgoblins anzufreunden, aber diese grässlichen Bilgewassergoblins sind so unverschämt.\n\nWarum? Ich sah gerade, wie eine Gruppe von ihnen aus den Zähnen von Musketieren und Schlägern der Südmeerfreibeuter Goldfüllungen herausrissen. Glauben die, sie können das einfach für sich behalten?\n\nNatürlich wäre es nett, wenn wir die Piraten selbst umbringen, ihre Füllungen selbst herausnehmen und dann den Dampfdruckgoblins einige als Dankesgeschenk übergeben! Geht dort hinunter und kommt den Goblins zuvor.", sourceObjective = "Sammelt 20 Goldfüllungen von Musketieren oder Schlägern der Südmeerfreibeuter.", progress = "Habt Ihr die Füllungen?", completion = "Noch mehr Gold! Wir werden Mister Noggenfogger bestimmt etwas davon abgeben, damit unsere Beziehung auch in Zukunft reibungslos verläuft.\n\nNur ein kleiner Teil wird nach Gnomeregan für die Entwicklung experimenteller Waffen zurückgebracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26888] = { id = 26888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alptraum in der Tiefe", description = "In den dunkelsten Winkeln der Tiefschwarzen Grotte ist ein Monster dort erschienen, wo die Alten Götter lauern. Wir kennen es nur als Aku'mai.\n\nDie Alten Götter und ihre Diener sind eine große Gefahr für unsere Welt. Vor langer Zeit herrschten sie über Azeroth und ich fürchte, dass sie diese Herrschaft erneut anstreben, auch wenn sie Azeroth bei dem Versuch zerstören würden.\n\n{name}, Aku'mai ist eine Kreatur unbeschreiblicher Alpträume. Wir können einfach nicht dulden, dass sie weiter existiert. Vernichtet sie.", sourceObjective = "Tötet Aku'mai.", completion = "Das Ungeheuer ist tot. Ich spüre, wie seine dunkle Gegenwart für immer vergeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26889] = { id = 26889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genug der Fröhlichkeit", description = "Meine Güte, wir haben hier ganz schön aufgeräumt!\n\n<Kelsey räuspert sich.>\n\nHört mal, {name}, ich freue mich darauf, diese Tötungskiste zu verlassen, damit ich endlich von diesen Goblins wegkomme und die aufgesetzte Fröhlichkeit ablegen kann. Wenn Ihr hier in der Gegend die Interessen von Gnomeregan weiter vertreten möchtet - und damit auch die der Allianz -, geht vom Außenposten der Schmuggler nach Süden.\n\nSprecht dort mit Zeke Scheuerschuh und denkt daran, dass jegliche Arbeit für die Dampfdruckgoblins uns dabei helfen wird, die Bilgewassergoblins endgültig aus Tanaris zu vertreiben.", sourceObjective = "Sprecht am Außenposten der Schmuggler mit Zeke Scheuerschuh.", completion = "Wisst Ihr, eigentlich bin ich ja nicht beeindruckt, wenn ich einen {race} sehe, aber ich habe gehört, was Ihr für Dampfdruck getan habt. Ihr seid in Ordnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[26890] = { id = 26890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Essenz von Aku'mai", description = "Im Eingangsbereich der Tunnel der Tiefschwarzen Grotte findet man überall an den Höhlenwänden große Saphiransammlungen. Uns ist aufgefallen, dass die Naga zur selben Zeit angefangen haben, diese Kristalle abzubauen, als sich auch ihre Waffen stark verbessert haben.\n\nDie Kristalle besitzen offenbar große Elementarkraft und wenn man sie zweckentfremdet, könnten sie eine mächtige Komponente für meine Schmiedekunst sein.\n\nWerdet Ihr mir helfen, {name}? Die Tiefschwarze Grotte liegt am Zoramstrand nördlich unseres Außenpostens.", sourceObjective = "Sammelt 20 Saphire von Aku'mai.", progress = "Wie läuft Eure Suche nach den Kristallen, {name}? Meint Ihr wir können daraus einen Gegenstand anfertigen, mit dem wir die Naga aufhalten können?", completion = "Ausgezeichnet! Die sind genau richtig. Hier habt Ihr eine Belohnung für Eure harte Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[26891] = { id = 26891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inmitten der Ruinen", description = "Die Anhänger des Schattenhammers sind hier in die Mondschreinruinen eingezogen. Ihre Gegenwart kann nur dazu dienen, die Elemente gegen uns aufzubringen.\n\n{name}, findet die Zwielichtagenten hier, dann sucht den Tiefenstein der Ruinen. Er dürfte sich irgendwo unter Wasser befinden, wahrscheinlich direkt vor ihren Nasen. Darin ist ein Tiefenkern - ein Gerät, das, wenn man es richtig abliest, eine Aufstellung über alle Aktivitäten von Elementaren liefert. Wenn ich es habe, können der Irdene Ring und ich vielleicht etwas tun, um sie aufzuhalten.", sourceObjective = "Findet den Tiefenkern.", progress = "Konntet Ihr den Tiefenkern finden? Ohne ihn haben wir keine Ahnung, was genau die Anhänger des Schattenhammers da unten vorhaben.", completion = "Genau das brauche ich! Ein Tiefenkern ist ein unglaublicher Quell an Informationen, aus denen wir guten Nutzen ziehen können. Was auch immer die Schattenhammerkultisten da unten im Schilde führen - und glaubt mir, wenn ich sage, dass es nichts Gutes sein kann - meine Kollegen und ich werden es jetzt aufdecken.\n\nIhr habt Eure Sache hier heute gut gemacht. Der Irdene Ring ist Euch sehr dankbar für Eure Hilfe. Ihr habt außerdem der Horde als Ganzes geholfen, und darauf solltet Ihr stolz sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26892] = { id = 26892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den tiefsten Tiefen", description = "Die Naga und der Schattenhammer arbeiten zusammen, um all den Fortschritt, den wir in dieser Gegend erzielt haben, zunichtezumachen. Schlimmer noch, Je'neu sagte mir, dass er die Gegenwart eines Alten Gottes tief unter uns spürt.\n\nWenn sie Chaos haben wollen, dann werden wir ihnen genau das geben.\n\n{name}, schlagt ihre stärksten Krieger und dann werden wir sehen, wie ihnen das gefällt.\n\nSeid bei Eurer Suche vorsichtig, die Tiefschwarze Grotte ist voller Unterwasserpassagen und Seitengänge, in denen sich Eure Ziele verbergen können.", sourceObjective = "Vernichtet Ghamoo-Ra, Lady Sarevess und Gelihast.", progress = "Sagt mir, {name}, rennen sie panikerfüllt umher? Sie bekommen genau das, was sie verdienen.", completion = "Ich kann ihre Schreie von hier aus hören! Vielleicht wird ihnen dies zeigen, wie töricht es ist, sich die Rückkehr eines Alten Gottes zu wünschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26893] = { id = 26893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tiefschwarze Grotte", description = "Es gibt eine Aufgabe, für die Ihr perfekt geeignet seid, {class}. Wir müssen die Gegend um die Tiefschwarze Grotte herum gegen die Allianz sichern, die den Außenposten von Zoram'gar im Westen von hier bedroht.\n\nGeht zur Tiefschwarzen Grotte nördlich des Außenpostens von Zoram'gar und sprecht mit Je'neu vom Irdenen Ring. Er wird viel für Euch zu tun haben.", sourceObjective = "Sprecht mit Je'neu Sancrea.", sourceObjectiveStatus = "unverified-source-field" }
quests[26894] = { id = 26894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tiefschwarze Grotte", description = "Die Naga verspotten uns mit ihrem offenen Widerstand. Wir werden sie und ihre Verbündeten endgültig aus diesen Landen vertreiben.\n\nReist nach Norden zu der Tiefschwarzen Grotte und sprecht mit Je'neu Sancrea. Er hat sie bereits betreten.\n\nÜbrigens, nehmt Euch vor Zeya in Acht. Sie ist manchmal etwas... launisch.", sourceObjective = "Sprecht mit Je'neu Sancrea.", completion = "Hat Kommandant Grimmfang Euch geschickt? Ich habe ihn gebeten, passende Rekruten zu finden, die mir hier helfen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[26895] = { id = 26895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Donnerkuppel!", description = "Hey, Freund, sucht Ihr Aufregung? Abenteuer? Geld? Gewalt? \n\nNun, Ihr solltet Gewalt schon mögen, denn die Donnerkuppel in Gadgetzan wurde gerade wieder eröffnet. Es war schon traurig, dass sie so lange nicht genutzt werden konnte, wegen der ganzen Schmerzensgeldklagen, Anzeigen wegen Gaunereien und Urheberrechtsverletzungen... Aber nun ist sie wieder da und wartet nur darauf, dass stattliche, wilde Typen wie Ihr kommt und Euch mit den garstigsten Gegnern aller Zeiten anlegt! Macht Euch auf den Weg nach Gadgetzan und sprecht mit Dr. Haudenlukas, um Euch einzuschreiben. Und sagt es all Euren Freunden weiter!", sourceObjective = "Sprecht in Gadgetzan mit Doktor Haudenlukas.", completion = "Noch ein stolzer {class}, angelockt vom Versprechen des Ruhms! Von Reichtum! Von GEWALT!\n\nJa, willkommen, mein Freund. Willkommen in der DONNERKUPPEL!", sourceObjectiveStatus = "unverified-source-field" }
quests[26896] = { id = 26896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Donnerkuppel!", description = "Hey, Freund, sucht Ihr Aufregung? Abenteuer? Geld? Gewalt? \n\nNun, Ihr solltet Gewalt schon mögen, denn die Donnerkuppel in Gadgetzan wurde gerade wieder eröffnet. Es war schon traurig, dass sie so lange nicht genutzt werden konnte, wegen der ganzen Schmerzensgeldklagen, Anklagen wegen Gaunereien und Urheberrechtsverletzungen... Aber nun ist sie wieder da und wartet nur darauf, dass stattliche, wilde Typen wie Ihr kommt und Euch mit den garstigsten Gegnern aller Zeiten anlegt!\n\nMacht Euch auf den Weg nach Gadgetzan und sprecht mit Dr. Haudenlukas, um Euch einzuschreiben. Und sagt es all Euren Freunden!", sourceObjective = "Sprecht in Gadgetzan mit Doktor Haudenlukas.", completion = "Noch ein stolzer {class}, angelockt vom Versprechen des Ruhms! Von Reichtum! Von GEWALT!\n\nJa, willkommen, mein Freund. Willkommen in der DONNERKUPPEL!", sourceObjectiveStatus = "unverified-source-field" }
quests[26897] = { id = 26897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tiefschwarze Grotte", description = "Obwohl wir hier ziemlich auf dem Präsentierteller stehen, sind wir noch sicher im Vergleich zu unseren Freunden in der Tiefschwarzen Grotte! Sie sind nur einige Fuß entfernt von den tödlichsten Nagatruppen des Landes. Sprecht mit Schildwache Aluwyn und gebt ihnen die Hilfe, die sie so dringend benötigen!", sourceObjective = "Sprecht mit Schildwache Aluwyn.", completion = "Elune sei Dank - Ihr seid hier! Wir können jede Hilfe gebrauchen, die wir bekommen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[26898] = { id = 26898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tiefschwarze Grotte", description = "Ich mache mir sehr viel aus diesen Wäldern, {class}. Es sieht wirklich nicht gut aus hier, aber ich würde mich lieber der Horde allein entgegenstellen, als zuzusehen, wie sie sich ihren Weg durch die Bäume hacken und schneiden.\n\nReist nach Westen zur Tiefschwarze Grotte. Sobald Ihr sie betretet, sucht Schildwache Aluwyn auf. Sie ist eine enge Vertraute, die Hilfe benötigt. Die \n\nOrcs im Außenposten von Zoram'gar bedrohen ihre Position in diesem Augenblick. Wenn sie die Tiefschwarze Grotte einnehmen, werden sie bestimmt jeden Baum fällen, um ihren Wahnsinn zu schüren.", sourceObjective = "Sprecht mit Schildwache Aluwyn.", completion = "Elune sei Dank - Ihr seid hier! Wir können jede Hilfe gebrauchen, die wir bekommen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[26899] = { id = 26899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind meines Feindes", description = "Kultisten...Opfer...Macht...\n\nFeind...erwacht...\n\nAlter Gott...sperrt...mich ein...\n\nLord...Kelris...\n\nBringt Kopf...Rache...\n\nAUSLÖSCHEN!!!", sourceObjective = "Verschafft Euch den Kopf von Zwielichtfürst Kelris.", progress = "Rache...Belohnung...", completion = "<Der flammende Vernichter scheint sich zu konzentrieren.>\n\nIch schone Euer Leben für Eure Hilfe, {race}. Geht jetzt...bevor ich es mir...anders überlege.", sourceObjectiveStatus = "unverified-source-field" }
quests[26901] = { id = 26901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go, Go, Guano!", description = "Die Fledermäuse aus dem Kral der Klingenhauer produzieren eine äußerst seltsame, natürliche Substanz. Der Gestank ihres Guano scheint die Stacheleber in mörderische Raserei zu versetzen - und hier stinkt es gewaltig danach!\n\nIhr müsst die Fledermaushöhle finden und mir eine passende Probe bringen. Wenn wir die Auswirkungen umkehren und ein Gegengift herstellen können, können wir die Stacheleber vielleicht retten.", sourceObjective = "Sammelt 1 Häufchen Kralguano", progress = "Ah, wie ich sehe, seid Ihr zurückgekehrt. Konntet Ihr etwas Kralguano beschaffen?", completion = "Gut gemacht! Das ist genau das, was wir brauchen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26903] = { id = 26903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willix der Importeur", description = "Endlich ist Hilfe eingetroffen!\n\nIhr habt keine Ahnung, wie lang ich hier gefangen gehalten wurde. Ich kann mich nicht erinnern, wann ich zum letzten Mal draußen war.\n\nWisst Ihr, ich bin Unternehmer. Immer auf die schnelle Mark aus, wie man so sagt. Ich habe Wind davon bekommen, dass sich Schweineschnauzen unglaublich gut auf dem Markt verkaufen lassen. Ich dachte mir, das würde ein leichtes Spiel werden. Wie Ihr sehen könnt, habe ich mich geirrt!\n\nWie auch immer, wenn Ihr so freundlich wärt, mir hier raus zu helfen, soll es Euer Schaden nicht sein.", sourceObjective = "Führt Willix den Importeur aus dem Kral der Klingenhauer hinaus.", completion = "Nochmals danke, Freund! Ich sagte doch, es würde sich für Euch lohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26904] = { id = 26904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbnis", description = "Nur wenige Menschen, besonders unter unseren Verbündeten, sind wirklich in der Lage, die Natur der Macht nachzuvollziehen, die wir besitzen. Sie meiden uns, weil sie zu schwach sind, das Wissen, das wir besitzen, richtig anzuwenden.\n\nwenn Ihr mächtiger werdet, werdet Ihr neue Zauber entdecken, die Eure Macht nur weiter mehren.\n\nGeht, sammelt Erfahrung und kehrt zu mir zurück, sobald Ihr einen neuen Zauber erlernt habt. Dann werden wir sehen, ob Ihr die dunklen Künste wahrlich beherrscht.", sourceObjective = "Erreicht Stufe 3, um 'Verderbnis' zu erlernen. Wirkt es dann fünfmal auf eine Trainingsattrappe nahe des Eingangs zu Ambossar.", sourceObjectiveStatus = "unverified-source-field" }
quests[26905] = { id = 26905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agamaggans Auftrag", description = "Hört gut zu, Sterblicher.\n\nDie Stacheleber sind meine Kinder. Dieses Land ist von meinem Blut durchzogen.\n\nCharlga Klingenflanke hat meine Kinder in die Dunkelheit geführt, nachdem sie von der Geißel in den Wahnsinn getrieben wurde.\n\nTötet sie, {name}. Tötet sie und öffnet meinen Kindern die Augen.\n\nGebt den Stachelebern die Chance, wieder zu ihren edlen Wurzeln zurückzukehren.\n\nLasst sie meinen Segen wieder verdienen. Bringt mir ihr Herz!!!", sourceObjective = "Nehmt Charlga Klingenflanke das Herz.", progress = "<Der Geist von Agamaggan betrachtet Euch geduldig.>", completion = "Nehmt dieses Geschenk. Ihr habt Euch heute wahrlich meinen Segen verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[26906] = { id = 26906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agamaggan", description = "Ich spüre eine ungeheure Macht in diesen gewundenen Dornen, {name}. Die ganze Gegend wird durch ihre Gegenwart belebt.\n\nEs muss der Geist von Agamaggan sein! Er war eins der ersten und mächtigsten Wesen, die je gelebt haben - die Stacheleber verehren ihn zutiefst.\n\nJede Ranke, die Ihr im Lande seht, stammt von seinem Blut - von dem Opfer, das er brachte, um Azeroth während des Kriegs der Ahnen zu retten.\n\nWenn ein Wesen die Stacheleber wieder zu ihren edlen Wurzeln führen kann, dann er.\n\nIhr müsst ihn finden.", sourceObjective = "Sprecht mit dem Geist von Agamaggan.", completion = "<Der Geist von Agamaggan betrachtet Euch. Eine uralte Stimme ertönt in Eurem Kopf.>\n\nIch habe darauf gewartet, dass Ihr herkommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26907] = { id = 26907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht sie nieder!", description = "Oberanführer Rammhauer und die Totenköpfe machen für den Krieg mobil. Es hat viele Späher das Leben gekostet, aber wir haben erfahren, mit Hilfe welcher Waffe sie den Rest des Brachlands übernehmen wollen.\n\nMan nennt ihn Agathelos den Tobenden. Er ist ein gewaltiger Eber mit schwerer Rüstung, dem man zwangsweise Kralfledermausguano verabreicht hat, das Raserei auslöst.\n\n{race}, Ihr müsst sie aufhalten, bevor sie unschuldige Leben vernichten!", sourceObjective = "Tötet Aggem Dornfluch, Todessprecher Jargba, Oberanführer Rammhauer und Agathelos den Tobenden.", completion = "Ihr habt Eure Sache heute gut gemacht. Agathelos hätte in seiner Wut viele Leben ausgelöscht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26908] = { id = 26908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dorn im Auge", description = "Mankriks Wut über seine tote Frau bietet Anlass zu weiterer Sorge, {class}.\n\nDie Stacheleber im Kral der Klingenhauer sind weitaus skrupelloser und hasserfüllter als Mankrik sich vorstellen konnte.\n\nIhr solltet nach Süden reisen und mit meinem alten Freund Auld Steinkeil sprechen. Er arbeitet daran, ihrer Raserei ein Ende zu bereiten, bevor das ohnehin geschwächte Land noch mehr leidet.", sourceObjective = "Sprecht mit Auld Steinkeil.", completion = "Nur ein Veteran wie Ihr könnte den Gefahren, die hier lauern, trotzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26909] = { id = 26909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Steinsplitter", description = "Uralte Steine sind über das ganze Land verstreut. Die Elemente strömen in Scharen zu ihnen und umringen sie schützend.\n\nEs handelt sich um Orte großer Macht. Der größte von ihnen liegt westlich von Hammerfall. Keine Seele dringt dort widerrechtlich ein, aber wenn Ihr alleine dort hingeht, hört ihr das Flüstern der Erde.\n\nIch bin schon lange nicht mehr dort gewesen, aber unsere Grunzer berichteten mir, dass das Flüstern wieder begonnen hat. Würdet Ihr für mich nachsehen? Werdet ihr nachsehen, ob die Steine immer noch sprechen?", sourceObjective = "Untersucht die Splitter von Myzrael.", completion = "<Die Splitter pulsieren sanft und ein Flüstern hallt in Eurem Kopf wider.>\n\nHilfe...", sourceObjectiveStatus = "unverified-source-field" }
quests[26910] = { id = 26910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geätzter Brief", description = "Mir wurde aufgetragen, Euch so bald wie möglich, nachdem Ihr von der Angelegenheit mit den Spionen des Schwarzfels zurückgekehrt seid, hierauf aufmerksam zu machen, {name}. Es scheint sich um einen Brief zu handeln, der mit dem Siegel von Ashley Blank, unserer Jägerlehrerin, versehen ist. Ich würde keine Zeit verlieren und ihn sofort lesen, bevor Ihr hier in der Abtei irgendetwas anderes macht.", sourceObjective = "Lest den geätzten Brief und sprecht im Nordhaintal mit Ashley Blank.", progress = "Hallo, {name}. Gibt es etwas, das ich für Euch tun kann?", completion = "Ihr habt meine Nachricht also erhalten? Ausgezeichnet. Ihr habt Euch im Umgang mit den Orcs als recht geschickt erwiesen. Während Ihr immer mächtiger werdet, werde ich Euch einige neue Techniken lehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26911] = { id = 26911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Myzraels Geschichte", description = "Als der Stein in Schweigen verfällt, bleibt Ihr mit einem vagen Unbehagen zurück. Etwas stimmt nicht.\n\nVielleicht solltet Ihr Zaruk erzählen, was Ihr bis jetzt getan habt.", sourceObjective = "Kehrt in das Arathihochland nach Hammerfall zu Zaruk zurück.", completion = "Ich weiß, {name}. Ich hätte Euch nicht schicken dürfen.\n\nVergebt mir... Das Flüstern der Stimmen aus der Vergangenheit ist manchmal zu stark.", sourceObjectiveStatus = "unverified-source-field" }
quests[26912] = { id = 26912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die entfesselte Prinzessin", description = "Myzrael ist eine Betrügerin. Sie ist eine uralte Macht, die vor langer Zeit unter Verschluss genommen wurde und da sollte sie auch bleiben.\n\nIhr müsst an den Splittern von Myzrael, wo Ihr zuerst mit ihr gesprochen habt, die Konfrontation mit ihr suchen. Ruft sie mit dieser Schriftrolle herbei. Wenn sie dann in voller Größe an der Oberfläche angelangt ist, besiegt sie. Dann nehmt die geisterhaften Fesseln von ihrem Körper und legt sie auf die Splitter, damit sie wieder vollkommen gebunden ist.\n\nViel Glück, {name}... Möge die Vergangenheit Euch nicht mehr beunruhigen.", sourceObjective = "Ruft Myzrael an den Splittern von Myzrael herbei und besiegt sie.", progress = "Die Splitter von Myzrael sind jetzt seltsam still.", completion = "Als die geisterhaften Fesseln um die Splitter gelegt werden, erschallt von tief unten ein unmenschliches Heulen. Auf den Schrei folgt ein Brüllen.\n\nDie Splitter von Myzrael rufen nicht länger Gefühle der Wärme und Sicherheit hervor, wie sie es zuvor taten. Jetzt sind sie erfüllt von einer feindseligen Aura... als ob das Ding unter ihnen der Außenwelt nicht wohlgesinnt wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[26913] = { id = 26913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Kampf stürmen", description = "Jetzt, da Ihr Gelegenheit hattet, Eure Fähigkeiten im Kampf zu erproben, wird es Zeit, Euch noch einen Grund vorzustellen, warum das Üben so wichtig ist.\n\nWenn Ihr nämlich mehr Erfahrung sammelt, könnt Ihr bald Techniken beherrschen, die Ihr Euch jetzt nicht zutrauen würdet.\n\nAlso macht Euch auf und sammelt noch etwas mehr Erfahrung. Erlernt eine neue Fähigkeit und zeigt sie mir an einer der Trainingsattrappen.", sourceObjective = "Erreicht Stufe 3 und erlernt Sturmangriff. Übt dann die Anwendung von Sturmangriff an einer Trainingsattrappe südlich des Eingangs zur Abtei von Nordhain.", completion = "Ihr lernt schnell, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26914] = { id = 26914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbnis", description = "Wir müssen hier in der Abtei und in ihrer Umgebung vorsichtig mit dem sein, was wir sagen, aber lasst Euch dadurch nicht vom Pfad der Macht abbringen.\n\nWenn Ihr mehr Erfahrung sammelt, werdet Ihr die Teufelsstimmen hören, die Euch ihre Macht über die dunklen Künste gewähren.\n\nGeht, sammelt mehr Erfahrung und erlernt einen neuen Zauber. Wenn es so weit ist, möchte ich, dass Ihr ihn bei einer der Trainingsattrappen ausprobiert.", sourceObjective = "Erreicht Stufe 3, um 'Verderbnis' zu erlernen. Übt dann die Anwendung von 'Verderbnis' fünfmal an einer Trainingsattrappe südlich des Eingangs zur Abtei von Nordhain.", progress = "Nun, habt Ihr es ausprobiert?", completion = "Wie ich sehe, beherrscht Ihr Feuerbrand bereits. Ich freue mich darauf, Euch in Zukunft weiter zu unterrichten. Vergesst nicht, für weitere Lektionen zurückzukehren, während Ihr immer mächtiger werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26915] = { id = 26915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefe Einschnitte", description = "Bisher kennt Ihr die Grundlagen für den Kampf als Schurke, aber ich möchte Euch eine neue Fähigkeit lehren. Als Schurken sind wir dafür bekannt, Ketten von Kampftechniken ausführen zu können und uns den mächtigsten Schlag bis zum Ende aufzubewahren.\n\nWenn Ihr erfahrener werdet, erlernt Ihr neue Dinge - und dies ist eins der Dinge, das Ihr als erstes erlernt. Wenn es so weit ist, möchte ich, dass Ihr es bei einer der Trainingsattrappen ausprobiert, die sich südlich vom Eingang der Abtei befinden.", sourceObjective = "Erreicht Stufe 3, um 'Ausweiden' zu erlernen. Sucht dann eine Trainingsattrappe südlich des Eingangs zur Abtei von Nordhain und übt daran dreimal die Anwendung von 'Ausweiden'.", completion = "Ihr habt schnell begriffen, {name}, und ein agiler Geist wird Euch sehr nützlich sein. Kehrt zu mir zurück, wenn Ihr mächtiger geworden seid und ich werde Euch neue Techniken lehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26916] = { id = 26916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschung des Arkanen", description = "Als Magier werdet Ihr mit wachsendem Verständnis eine Vielzahl von Zaubern lernen. Alles, was Ihr tun müsst, ist Erfahrungen sammeln und die Geheimnisse des Arkanen werden sich Euch offenbaren.\n\nIhr werdet sehen. Geht, entwickelt Eure Kräfte und zeigt mir dann, was Ihr gelernt habt.", sourceObjective = "Erreicht Stufe 3, um 'Frostnova' zu erlernen. Übt den Zauber dann zweimal an einer Trainingsattrappe südlich des Eingangs zur Abtei von Nordhain.", completion = "Beherrscht Ihr die Anwendung von 'Frostnova' bereits? Ihr lernt die arkanen Künste schnell und habt eine vielversprechende Zukunft vor Euch. Vergesst nicht, für weitere Ausbildung zu mir zurückzukehren, während Ihr immer mächtiger werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26917] = { id = 26917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Jägers", description = "Ich hörte, dass Ihr geholfen habt, einige der Orcs auszumerzen. Ihr habt bewiesen, dass Ihr Euch im Kampf zu verhalten wisst.\n\nWenn Ihr mehr erfahrener im Kampf werdet, lernt Ihr auch neue Dinge. Ich will, dass Ihr da raus geht, Erfahrungen sammelt und dann die neu erlernten Fähigkeiten an den Trainingsattrappen am Eingang der Abtei ausprobiert.", sourceObjective = "Erreicht Stufe 3, um 'Zuverlässiger Schuss' zu erlernen. Sucht dann eine Trainingsattrappe südlich des Eingangs zur Abtei von Nordhain und übt fünfmal 'Zuverlässiger Schuss'.", completion = "Ich wusste, Ihr würdet 'Zuverlässiger Schuss' schnell meistern. Ich freue mich darauf, Euch neue Techniken zu zeigen, wenn Ihr weitere Erfahrungen als Jäger gesammelt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26918] = { id = 26918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Lichts", description = "Je weiter Ihr den Pfad des Paladins beschreitet, desto näher kommt Ihr dem Licht und desto mehr Fähigkeiten könnt Ihr lernen.\n\nZieht los, sammelt etwas Erfahrung und erlernt eine neue Fähigkeit. Wenn Ihr sie mir vorgeführt habt, können wir mit Eurer Ausbildung fortfahren.", sourceObjective = "Erreicht Stufe 3, um das Siegel des Befehls zu erlernen. Wirkt das Siegel des Befehls auf Euch selbst und schlagt dann eine Trainingsattrappe südlich des Eingangs zur Abtei von Nordhain.", progress = "Nun, habt Ihr es ausprobiert?", completion = "Ihr lernt schnell, {name}. Kehrt zu mir zurück, wenn Ihr stärker geworden seid und ich werde Euch mehr darüber lehren, wie Ihr das Licht zur Vernichtung Eurer Feinde und zur Stärkung Eurer Verbündeten anwenden könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26919] = { id = 26919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das richtige Wort", description = "Als <Priester/Priesterin> müsst Ihr Euch unter anderem um die Verwundeten kümmern. Eine weiter Verpflichtung ist, in die Welt hinauszugehen und etwas… aktiver an ihre Verteidigung heranzugehen.\n\nWährend Ihr das tut, werdet Ihr mehr Macht erlangen und alle möglichen neuen Dinge lernen.\n\nGeht, sammelt mehr Erfahrung und kehrt dann zu mir zurück und zeigt mir, was Ihr erlernt habt.", sourceObjective = "Erreicht Stufe 3, um 'Schattenwort: Schmerz' zu erlernen, und benutzt es fünfmal an den Trainingsattrappen vor der Abtei von Nordhain.", completion = "Ihr lernt schnell, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26920] = { id = 26920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Andorhal", description = "Beeilt Euch, {name}... Wir haben keine Zeit zu verschwenden.\n\nDie Stadt Andorhal steckt mitten in einem dreiseitigen Krieg zwischen den Verlassenen, der Allianz und der Geißel. Fürstin Sylvanas hat einen ihrer besten Todesritter entsandt, um den Sturmangriff für ihre Sache zu leiten. Dennoch bin ich sicher, dass er jede Hilfe gebrauchen kann. Arthas ist tot, deshalb ist jetzt der perfekte Zeitpunkt für die Verlassenen, Andorhal einzunehmen.\n\nSprecht mit dem Fledermausführer Timothy Cunningham, wenn Ihr bereit seid, und er wird Euch den nächsten Flug dorthin verschaffen.", sourceObjective = "Meldet Euch in den Westlichen Pestländern innerhalb Andorhals bei Koltira Todesweber.", completion = "Wurde auch Zeit, dass Ihr eintrefft, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26921] = { id = 26921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erst die Geißel... dann die Allianz", description = "Dunkelmeister Gandling vom Kult der Verdammten führt die Offensive der Geißel hier in Andorhal an. Mein alter Widerpart, Thassarian, führt die Streitkräfte der Allianz an. Wenn wir Andorhal für uns gewinnen wollen, müssen wir beide besiegen. Doch wir werden sicherlich nicht beide gleichzeitig angreifen können.\n\nIch kenne Thassarian gut genug, um zu wissen, dass er sich zuerst auf die Geißel konzentrieren wird. Wir werden dasselbe tun.\n\nSchaltet die schwächeren ausgedörrten Geißeldiener aus, damit sie zahlenmäßig unterlegen sind. Die Allianz wird unsere Rache erst später zu spüren bekommen.", sourceObjective = "Tötet 15 ausgedörrte Geißeldiener in Andorhal.", completion = "Ihr seid zwar nicht besonders schnell, aber wenigstens enttäuscht Ihr mich nicht.\n\nSehr schön. Sobald die Zeit reif ist, werde ich noch eine wichtigere Aufgabe für Euch haben, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26922] = { id = 26922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der unendliche Fluss", description = "Araj der Beschwörer verstärkt die Verteidigung der Geißel mit einfachen Skeletten... eine Armee von Schwächlingen, die Euch eher überrennen als übermannen wird. Er hat Animi in den nördlichen Türmen Andorhals versammelt, die diese Skelette in einer erschreckenden Geschwindigkeit hervorrufen können. Ich habe aber eine Lösung!\n\n<Jearl reicht Euch ein paar Granaten.>\n\nIhre Funktion ist einfach. Wenn diese Granaten auf einen Knochenanimus - oder in unserem Fall einen Haufen Skelette - geworfen werden, wird nicht mehr als Splitter von ihnen übrig bleiben.", sourceObjective = "Benutzt Jearls Handgranaten und tötet 5 Berserker der Klapperknochen und zerstört einen Knochenanimus der Geißel.", completion = "Diese Granaten sind Sprengstoff, mehr nicht. Selbst als Mitglied der Königlichen Apothekervereinigung sehe ich ein, dass sich manche Probleme nicht dadurch lösen lassen, mehr Seuche nach ihnen zu werfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26923] = { id = 26923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsmaschinen", description = "Ihr Narren werdet die Geißel niemals besiegen, solange diese Monstrositäten herumlaufen. Koltira quasselt ständig davon, sie zahlenmäßig unterlegen zu machen, aber die beste Waffe der Geißel hier in Andorhal findet man unter diesen herumtorkelnden Schlägern, die meine Todeswachen wie Puppen umherschleudern.\n\nDas hat jetzt ein Ende.\n\n{name}, geht auf das Schlachtfeld und vernichtet diese Monster.", sourceObjective = "Vernichtet 6 aufgeschlitzte Ungetüme in Andorhal.", completion = "Jetzt, da die Ungetüme aus dem Weg sind, ist uns der Sieg gegen die Geißel gewiss.\n\nUnsere Chancen gegen die Allianz sind momentan nicht ganz so günstig... Aber das soll Euch nicht kümmern. Jedenfalls noch nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26924] = { id = 26924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scholomancer", description = "Scholomance ist eine der letzten verbliebenen Bastionen der Geißel im Westen von Thondroril. Der Direktor von Scholomance, ein Kultist namens Dunkelmeister Gandling, ist auf dem Schlachtfeld aufgetaucht.\n\nDas wird sein letzter Fehler sein.\n\nIhr findet Gandling auf einem Platz in der Nähe des südlichen Stadtrands. Ich möchte, dass Ihr mit Gandling kämpft und ihn schwächt. Ich werde Euch unterstützen, damit er sein Ende findet.", sourceObjective = "Tötet Dunkelmeister Gandling in Andorhal.", completion = "Ausgezeichnete Arbeit, {name}. Jetzt, da der Anführer der Streitmächte der Geißel nicht länger in Andorhal sein Unwesen treibt, müssen wir den richtigen Augenblick abwarten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26925] = { id = 26925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Araj der Beschwörer", description = "Nun da der Animus besiegt ist, ist der nächste logische Schritt die Auslöschung Arajs und der Erhalt einer Scherbe seines Phylakteriums. Ihr habt ihn wahrscheinlich schon am Brunnen in der Stadtmitte herumlümmeln gesehen.\n\nNehmt meine Granaten mit. Sie werden Araj keinen Schaden zufügen, aber Ihr könnt sie benutzen, wenn er auf die Idee kommt, Skelette zu beschwören, und diese damit in die Luft jagen. Ihr wisst ja, wie das geht.", sourceObjective = "Tötet Araj den Beschwörer. Ihr könnt Jearls Handgranaten benutzen, um die Berserker der Klapperknochen zu zerstören.", progress = "Araj ist ein ausgezeichneter Gegner. Ihr solltet gut vorbereitet sein.", completion = "Araj ist tot... das ist gut. Die Königliche Apothekervereinigung hat ihren Part getan. Und Ihr auch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26926] = { id = 26926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieg, im Moment", description = "Die Verlassenen haben gesiegt und unsere Streitmächte sind immer noch stark. Gemäß unserer strategischen Kriegsführung müssten wir die Allianz jetzt angreifen, solange man sich dort noch vom Kampf erholt und nicht mit einem Angriff rechnet. Ich habe allerdings andere Pläne...\n\nWir werden warten. Wir greifen Thassarian und seine Truppen an, wenn der richtige Zeitpunkt gekommen ist. Sprecht in der Zwischenzeit mit Rhonda Molver und nehmt einen Flug Richtung Bollwerk an der westlichen Grenze der Pestländer. Hochexekutor Derrington wird Euch mit Eurer nächsten Aufgabe vertraut machen.\n\nVon mir werdet Ihr wieder hören, sobald Ihr in Andorhal gebraucht werdet.", sourceObjective = "Meldet Euch in Tirisfal am Bollwerk bei Hochexekutor Derrington.", completion = "Die Nachricht traf kurz vor Euch ein, {name}. Dass die Geißel aus Andorhal hinausgeworfen wurde hat die Stellung der Verlassenen in Lordaeron gefestigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26927] = { id = 26927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...und plötzlich Murlocs!", description = "Also, wir haben Troggs, die für Kobolde arbeiten und Kobolde, die für Gnolle arbeiten. Die Gnolle müssen aus dem Sumpfland hergezogen sein.\n\nWas weiß ich denn? Nun, sie haben Freunde mitgebracht, denn die Murloc der Blaukiemen schwärmen überall am Loch herum, oder an dem, was von ihm übrig geblieben ist.\n\nPlagegeister sind Plagegeister, aber die Koordination ist besorgniserregend. Ihr müsst mit Kanari Zielwasser reden. Sie ist eine der besten Jägerinnen im Umkreis und sie wird wissen, wie man mit den Murlocs umgeht - wenn es Euch gelingt, sie lange genug von ihrem Krug wegzuzerren.", sourceObjective = "Sprecht mit Kanari Zielwasser.", completion = "Murlocs? Natürlich habe ich Murlocs gejagt.\n\nUnd jeder einzelne dieser Stinker hat bekommen, was er verdiente! Versteht Ihr mich?", sourceObjectiveStatus = "unverified-source-field" }
quests[26928] = { id = 26928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das riecht nach 'nem Plan", description = "Murlocs, die mit Gnollen zusammenarbeiten? Das ist lachhaft! Nun, sie einfach nur zu töten wird Euch auch nicht weiterhelfen. Es gibt zu viele von den Quälgeistern.\n\nAber ich habe einen Plan - ich benutze mein Köpfchen, müsst Ihr wissen. Diese Murlocs sondern einen Geruch ab, den sie überall hinterlassen. Wenn andere Murlocs das riechen, werden sie irre! Damit kann man sie prima ködern.\n\nWie auch immer, sie haben kleine Drüsen, in denen sich der Geruchsstoff befindet. Geht und holt mir ein paar davon.", sourceObjective = "Sammelt am Loch 7 Stinkdrüsen eines Murlocs von beliebigen Murlocs der Blaukiemen.", progress = "Ihr stinkt ja zum Himmel! Ich nehme an, dass das an den Murlocs liegt, aber es ist schwer zu sagen.", completion = "Puh! Welch ein Gestank.\n\nJetzt haltet Euch fest, denn ich werde Euch mit dem, was von meinen geistigen Fähigkeiten geblieben ist, umhauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26929] = { id = 26929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Haufen Kroki", description = "Während Ihr herumlauft und das tut, was immer ihr da auch tut - würde es Euch da etwas ausmachen, mir ein wenig zu helfen?\n\nSchaut, normalerweise gehe ich unten am Loch Krokilisken jagen, aber unter den gegebenen Umständen ziehe ich es vor, hier zu sitzen. Es ist sehr höflich von Euch, mir deshalb keine Vorwürfe zu machen. Danke!\n\nDa ihr <solch ein feiner Herr/so eine feine Dame> seid, warum bringt Ihr mir nicht ein paar Krokiliskenkiefer mit und ich gebe Euch im Gegenzug ein bisschen fast sauberes Geld?", sourceObjective = "Sammelt 6 Krokiliskenkiefer.", progress = "Habt Ihr diese Krokiliskdinger gefunden oder habe ich das geträumt?", completion = "Mächtig nett von Euch, einem alten Narren wie mir zu helfen. Hier ist Eure versprochene Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[26930] = { id = 26930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach dem Kreuzzug", description = "Unsere Siege häufen sich, {name}. Der Scharlachrote Kreuzzug, der die Verlassenen schon seit Langem verfolgt, pfeift aus dem letzten Loch. Sie halten immer noch ihr Kloster hier in Tirisfal, aber sie haben Herdweiler und Tyrs Hand im fernen Osten verloren.\n\nErst letzte Woche gab es Berichte von Aktivitäten des Scharlachroten Kreuzzugs in einem kleinen Lager östlich vom Teufelssteinfeld, aber ich habe guten Grund anzunehmen, dass auch sie ausgelöscht wurden. Reist dorthin und überprüft für mich diese Information.", sourceObjective = "Späht östlich vom Teufelssteinfeld in den Westlichen Pestländern das Lager des Scharlachroten Kreuzzugs aus.", completion = "Brennende Leichen? Keine Überlebenden? Ich habe richtig vermutet.\n\nUmso besser! Wir sind besser dran, wenn die scharlachrote Verderbnis nicht über Lordaeron liegt. Sie verkörperten alles Schlechte am Menschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26931] = { id = 26931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Füchse und Hunde", description = "Die Streitkräfte der Allianz laufen in den Pestländern herum, als ob die Gegend ihnen gehört. Nun, dem ist nicht so. Dieses Land gehört rechtmäßig der Dunklen Fürstin!\n\nAls der Kampf um Andorhal zum Ende kam, zerstreuten sich die Kräfte der Allianz, die die Pestländer besetzten. Einige von ihnen sind genau östlich von hier und jagen Füchse. Beweist ihnen, dass das hier das Gebiet der Verlassenen ist.\n\nTötet die Jäger. Tötet ihre Jagdhunde. Und wenn Ihr gerade dabei seid, tötet die Füchse noch obendrein.", sourceObjective = "Tötet 4 Fuchsjäger der Allianz, 4 Bullenmastiffs und 4 Weißschwanzfüchse in den Westlichen Pestländern.", completion = "Die Jäger aus dem Weg zu haben ist solch eine Erleichterung. Wir sind allerdings noch nicht fertig damit, Allianzler zu töten...", sourceObjectiveStatus = "unverified-source-field" }
quests[26932] = { id = 26932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgeflattert", description = "Als der Steinwerkdamm brach, legte er fast den ganzen See trocken. Eine verheerende Umweltkatastrophe.\n\nUnd wagt es nicht, zu denken, dass das keine Auswirkungen auf uns Zwerge hatte! Wir haben nicht nur absolut keine Fische mehr, sondern da draußen liegen über viele Morgen verstreut tote Dreschadon und verrotten in der Sonne. Die Bussarde sind hinter ihnen her und verbreiten dabei Dreck und Krankheiten an den Außenbezirken der Stadt.\n\nIch kann Euch nicht darum bitten, das alles zu säubern, aber könntet Ihr Euch der Bussarde annehmen? Es wird schon helfen, nur ein paar zu töten.", sourceObjective = "Tötet 8 Lochbussarde.", completion = "Das sollte die weitere Verbreitung von Krankheiten in dem Wasser, das uns noch geblieben ist, verhindern. Vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26933] = { id = 26933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feind oder Bauer?", description = "Die Männer, die das Teufelssteinfeld bestellen, sind keine Bauern. Sie sind Soldaten.\n\nThassarians Streitkräfte benötigten Nahrung, also hat er einige Allianzler aus Andorhal nach Norden entsandt, damit sie sich um das Teufelssteinfeld kümmern. Der Kampf um Andorhal mag vorüber sein, aber es droht bereits die nächste Schlacht... Verlassene gegen Menschen. Wenn die dort auf dem Teufelssteinfeld arbeitenden Soldaten getötet werden, wird das den Streitkräften der Dunklen Fürstin einen entscheidenden Vorteil verschaffen.", sourceObjective = "Tötet 9 Allianzarbeiter auf dem Teufelssteinfeld.", completion = "Haha! Ich hoffe, sie kommen als Zombies zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[26934] = { id = 26934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verborgene Krankheit", description = "Ich brauche verseuchtes Gras für ein... ein Experiment sozusagen. Diese Argentumkreuzfahrer und die höllischen Cenarischen Druiden haben bei der Heilung der Pestländer wirklich ganze Arbeit geleistet. Ich kann keine brauchbaren Reagenzien in erreichbarer Nähe finden.\n\nAllerdings tragen einige der hiesigen Wildtiere noch die Seuche in sich. Tötet einen kranken Schwarzbär und pflückt dann das Gras, das dort wächst, wo sein verfallender Körper liegt. Das ist nicht optimal, aber es wird genügen.", sourceObjective = "Tötet kranke Schwarzbären in den Westlichen Pestländern und pflückt dann 20 Pesttentakel, die in der Nähe ihrer Körper wachsen.", progress = "Krankheiten erhalten sich in Tiergewebe so viel besser als in Pflanzengewebe, nicht wahr?", completion = "Großartig! Das ist das letzte Stück, das ich benötige.\n\nWartet doch noch einen Moment, {name}. Lasst mich Euch ein wenig mehr über unseren Plan erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26935] = { id = 26935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sägewerk des Nordkamms", description = "Wir sind nicht die einzigen Argentumkreuzfahrer hier in den Pestländern. Unser Hauptquartier, Herdweiler, liegt im Norden. Noch etwas näher im Norden ist ein kleines Sägewerk, das ebenfalls unter unserer Kontrolle steht.\n\nNathaniel Dumah ist mein Kontaktmann im Sägewerk. Sprecht ihn ruhig an, wenn Ihr dort einmal in der Nähe seid.", sourceObjective = "Meldet Euch bei Nathaniel Dumah im Sägewerk des Nordkamms in den Westlichen Pestländern.", completion = "Willkommen in Nordkamm, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26936] = { id = 26936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weniger Bumm", sourceObjective = "Teufelssteinfeld ist geräumt und die Bomben sind scharfgemacht. Ich hoffe, Ihr seid bereit. Ich schlage vor, Ihr haltet Euch die Ohren zu.\n\n<Derrington schaut nach unten und legt seinen Finger auf einen Zündschalter.>\n\nALLES KLAR ZUR ZÜNDUNG! IN 3...\n\n2...\n\n1...", sourceObjectiveStatus = "unverified-source-field" }
quests[26937] = { id = 26937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn der Tod nicht ausreicht", description = "Derrington und seine Männer wissen es nicht, aber ich habe die Verseuchung vom Teufelssteinfeld angeordnet. Wir brauchen das Gebiet zum Üben. Wenn wir diesen Krieg für Andorhal gewinnen wollen, müssen wir unsere neueste und vielseitigste Waffe einsetzen:\n\nVal'kyr.\n\nNehmt diese umzauberte Val'kyr mit, {name}, und tötet den jämmerlichen Abschaum der Allianz, der auf dem Teufelssteinfeld noch zu finden ist. Sobald einer tot ist, wird er von ihr in diese Welt zurückgeholt... als einer von uns.\n\nDie Verlassenen werden nicht aussterben!", sourceObjective = "Tötet 8 Allianzarbeiter auf dem Teufelssteinfeld, damit Eure bezauberte Val'kyr sie in Verlassene umwandeln kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[26938] = { id = 26938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampftraining", description = "Der einzige Lebenszweck einer Val'kyr ist zu dienen - und diese dient Euch. Ich werde Euch jetzt volle Kontrolle über ihre Fähigkeiten geben, {name}.\n\nWenn Ihr in den Außenbereichen des Hofs herumlauft, solltet Ihr einige der Verlassenen finden, die Ihr gerade erschaffen habt. Ich möchte, dass Ihr Eure Val'kyr benutzt, um mindestens fünf von ihnen einzusammeln. Wenn Ihr das getan habt, nehmt Eure neue Soldatenkolonne, bringt sie in die Teufelssteinscheune und tötet die Bestie darin. Heute werdet Ihr lernen, was es heißt, für die Dunkle Fürstin zu kämpfen.", sourceObjective = "Benutzt die Fähigkeit Eurer umzauberten Val'kyr, um 5 Gardisten der Verlassenen auf dem Teufelssteinfeld zu mobilisieren. Dann tötet die aufgeschlitzte Monstrosität in der Teufelssteinscheune.", completion = "Wenn Koltira das Zeichen gibt, werde ich diese Val'kyr nach Andorhal hineinbringen. Wir werden gewinnen. Und noch ein weiterer Teil Lordaerons wird sich der Macht der Verlassenen beugen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26939] = { id = 26939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das G-Team", description = "Wie seid Ihr hier reingekommen?\n\nAch, ist auch egal. Ich bin Mör'dok vom G-Team. Wir sind die Besten, die es gibt und wir sind hier, um Gnomeregan zurückzuerobern!\n\nAls niemand anders ihm helfen konnte, kam der Hochtüftler zu uns und hat uns angeheuert.\n\nAber das kriegen wir nicht alleine hin! Ihr seid jetzt ein G-Team Kommandosoldat ehrenhalber, {name}.\n\nNehmt diesen Fallschirm, springt geradeaus in die Halle der Zahnräder und tötet die Verflüssigte Ablagerung. Wenn Ihr fertig seid, meldet Euch bei Kommandosoldat Bi'ay Bäräkuss im westlichen Korridor. Ihr beide werdet Euch mit Sicherheit gut verstehen.", sourceObjective = "Tötet die Verflüssigte Ablagerung.", completion = "Ich hoffe, das hat Euch nicht überfordert. Die Mission ist noch längst nicht vorbei!", sourceObjectiveStatus = "unverified-source-field" }
quests[26940] = { id = 26940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostnova", description = "Wir sind die Erben eines Vermächtnisses arkaner Magie und Euer Weg wird kein leichter sein. Viele machen uns immer noch für die Taten unserer Vorfahren verantwortlich, doch unsere Talente werden gebraucht.\n\nObwohl Ihr vorsichtig sein müsst, ist es wichtig, dass Ihr Eure Kräfte weiterentwickelt, da Ihr dadurch Eure Verbindung mit dem Arkanen vertieft und Zugang zu neuen Zaubern erhaltet.\n\nGeht, sammelt mehr Erfahrung mit Euren Zaubern und zeigt mir, was Ihr gelernt habt.", sourceObjective = "Erreicht Stufe 3, um 'Frostnova' zu erlernen. Sucht in der Nähe nach einer Trainingsattrappe und übt daran die Anwendung von 'Frostnova' zwei Mal.", sourceObjectiveStatus = "unverified-source-field" }
quests[26941] = { id = 26941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das G-Team", description = "Dieser Mör'dok ist verrückt, {class}. Passt bloß auf, dass Ihr niemals mit diesem Gnom in einem Flugzeug sitzt.\n\nVerstohlenheit ist normalerweise nicht mein Ding, und sie wird ganz bestimmt auch nicht Eures sein. Geht diesen Flur entlang bis zur Abschussrampe und entledigt Euch des Elektrokutor 6000.\n\nDer Elektrokutor ist verantwortlich für die Luftfahrzeuge...\n\n... und ich hasse Luftfahrzeuge. Mich bekommt man in kein Luftfahrzeug!\n\nBenutzt diesen Fallschirm, um anschließend abzuspringen und sprecht mit Kommandosoldat Fähs über Eure nächste Aufgabe.", sourceObjective = "Tötet den Elektrokutor 6000.", completion = "Hat ja lange genug gedauert. Kommt mit mir hinter die Säule, bevor Ihr unsere Tarnung auffliegen lasst!", sourceObjectiveStatus = "unverified-source-field" }
quests[26942] = { id = 26942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das G-Team", description = "Ich würde mich von Bi'ay Bäräkuss und Mör'dok geflissentlich fernhalten - die sind beide nicht ganz dicht.\n\nAber Ihr seid es, also an die Arbeit! Geht diesen Tunnel entlang, bis Ihr zum Tüftlerhof kommt. Hoffentlich wisst Ihr, was zu tun ist, wenn Ihr Robogenieur Thermadraht begegnet.\n\nUnser Anführer, Kommandosoldat Hann Ibal möchte Euch irgendwo da drin treffen. Er wird Euch reich für Eure Bemühungen belohnen.\n\nWahrscheinlich.", sourceObjective = "Tötet Robogenieur Thermadraht.", completion = "Ich hätte Euch liebend gern als vollwertigen G-Team Kommandosoldaten, aber Ihr verfolgt andere Abenteuer.\n\nIch bin sicher, wir werden uns wiedersehen und ich hoffe, Ihr habt Euch bis dahin überlegt, uns beizutreten. Hier ist etwas für Eure Unannehmlichkeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26943] = { id = 26943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trautes Heim, Gnom allein", description = "Ich hatte in Eisenschmiede mal ein ganz nettes Zuhause. Bis man mich rausgeworfen hat, um Platz für die Gnome zu machen.\n\nDie könnten nicht mal eine Gruppe Troggs aufhalten mit ihren ganzen Dingsdas und Maschinen! Und ich soll für ihre Schwäche bezahlen?\n\nNein, Sir! Nicht mehr.\n\nGeht nach Gnomeregan und redet mit Kommandosoldat Mör'dok. Klar, er ist ein Gnom, aber seine Leute... S.I.C.H.E.R. Ich glaube, so heißen sie... die werden Gnomeregan zurückerobern.\n\nLos! Ich will mein Haus zurück!", sourceObjective = "Sprecht mit Mör'dok.", completion = "Ich hätte nie gedacht, dass ich einen {race} wie Euch hier unten sehen würde. Gibt es einen bestimmten Grund dafür, dass Ihr Leib und Leben riskiert?", sourceObjectiveStatus = "unverified-source-field" }
quests[26944] = { id = 26944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomeregan erforschen", description = "Die Hauptstadt der Gnome, Gnomeregan, ist seit einiger Zeit nicht mehr unter ihrer Kontrolle. Ich weiß, wie es ist, ein Zuhause zu verlieren.\n\nBitte begebt Euch nach Gnomeregan und sprecht mit Kommandosoldat Mör'dok, einem Mitglied von S.I.C.H.E.R. Wenn Ihr ihnen irgendwie helfen könnt, ihre Heimat zurückzuerobern, dann fordere ich Euch auf, es zu tun. Jene Hallen bergen dunkle Geheimnisse.", sourceObjective = "Sprecht mit Mör'dok.", completion = "Ich hätte nie gedacht, dass ich einen {race} wie Euch hier unten sehen würde. Gibt es einen bestimmten Grund dafür, dass Ihr Leib und Leben riskiert?", sourceObjectiveStatus = "unverified-source-field" }
quests[26945] = { id = 26945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Techniken lernen", description = "Wenn Ihr die Herausforderungen in Eurem Weg meistert, werdet Ihr beginnen, neuen Techniken zu erlernen.\n\nGeht, sammelt mehr Erfahrung und erlernt eine neue Fähigkeit. Demonstriert sie mir dann an einer der Trainingsattrappen.", sourceObjective = "Erreicht Stufe 3, um 'Sturmangriff' zu erlernen. Sucht in der Nähe nach einer Trainingsattrappe und übt daran die Anwendung von 'Sturmangriff'.", completion = "Ihr habt Euch als fähiger Schüler erwiesen. Wenn es an der Zeit ist, Eure Ausbildung fortzusetzen, kehrt zu mir zurück und ich werde Euch neue Techniken lehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26946] = { id = 26946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Vorteil eines Schurken", description = "Ich bin sicher, dass Ihr inzwischen den Finsteren Stoß meisterlich gegen Eure Feinde anwendet. Dennoch, wenn Ihr mehr lernt und als Schurke voranschreitet, werdet Ihr Euch neue Techniken aneignen. Eine, die Ihr schon bald erlernen werdet, nennt sich 'Ausweiden' und ist ein mächtiger Abschluss für eine Kombination von Angriffen.\n\nIch möchte, dass Ihr Erfahrung sammelt, die Fähigkeit erlernt und sie dann ausprobiert. Sucht nach einer Trainingsattrappe am südöstlichen Ende Aldrassils.", sourceObjective = "Erreicht Stufe 3, um 'Ausweiden' zu erlernen. Sucht im Südosten von Aldrassil nach einer Trainingsattrappe und übt daran dreimal die Anwendung von 'Ausweiden'.", completion = "Ihr habt schnell gelernt. Wenn Ihr so scharfsinnig seid, wie Ihr wirkt, dann könntet Ihr einer meiner besten Schüler werden. Kehrt zu mir zurück, wenn Ihr weitere Ausbildung benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26947] = { id = 26947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung eines Waldhirten", description = "Die meisten Menschen, die an die Kaldorei denken, haben Visionen von Druiden und Schildwachen, aber der Weg des Jägers ist ebenso alt und genauso ehrenvoll.\n\nIch habe Euch beobachtet und Ihr habt einige Erfahrungen mit Eurem Bogen gesammelt. Durch Erfahrung werdet Ihr beginnen, einige neue Fähigkeiten zu erlernen.\n\nGeht, sammelt mehr Erfahrung und findet heraus, wie man etwas Neues erlernt. Sucht dann nach einer Trainingsattrappe am südöstlichen Ende Aldrassils und probiert es aus.", sourceObjective = "Erreicht Stufe 3, um 'Zuverlässiger Schuss' zu erlernen. Sucht im Südosten von Aldrassil nach einer Trainingsattrappe und übt daran fünfmal die Anwendung von 'Zuverlässiger Schuss'.", completion = "Ihr lernt unsere Gepflogenheiten schnell. Ich freue mich darauf, Eure Ausbildung fortzusetzen. Kehrt zu mir zurück, wenn die Zeit reif ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[26948] = { id = 26948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondfeuer", description = "Druiden spielen in unserer Gesellschaft eine wichtige Rolle. Doch allzu oft werden wir als passive Träumer angesehen, in einer Welt, die sich um uns herum verändert.\n\nDie Wahrheit ist allerdings, dass wir aktiv üben und in die Welt hinausgehen müssen, um unsere Verbindung mit der Natur zu entwickeln.\n\nAlso, geht, sammelt Erfahrungen. Ihr werdet spüren, wie sich die Verbindung vertieft, wenn Ihr neue Fähigkeiten erlernt. Demonstriert mir die erste, die Ihr erlernt.", sourceObjective = "Erreicht Stufe 3, um 'Mondfeuer'. Wendet 'Mondfeuer' bei einer Trainingsattrappe in Aldrassil an.", completion = "Ihr habt die Grundlagen des Heilens schnell gelernt, {name}. Ich habe keine Zweifel, dass Eure Heilfähigkeiten oft nützlich sein werden. Kehrt zu mir zurück, wenn Ihr weitere Ausbildung benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26949] = { id = 26949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das richtige Wort", description = "Wenn Ihr Euch in die Welt da draußen wagt und Eure Fähigkeiten entwickelt, werdet Ihr neue Fertigkeiten erlernen, von denen Ihr nicht wusstet, dass sie in Euch stecken.\n\nIch möchte, dass Ihr loszieht, weitere Erfahrungen sammelt und mir dann die erste neue Fähigkeit zeigt, die Ihr gelernt habt.", sourceObjective = "Ihr müsst Stufe 3 erreichen, um Schattenwort: Schmerz zu erlernen. Wendet es dann 5-mal an Trainingsattrappen an.", completion = "Ihr werdet nie Mangel an Verbündeten haben, die Heilung benötigen. Kehrt zu mir zurück, wenn Ihr weitere Ausbildung benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26950] = { id = 26950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dunkle Seite des Lichts", description = "Der Scharlachrote Kreuzzug lockt junge Krieger mit dem Versprechen an, die Untoten auszulöschen. Was sie nicht sehen, ist die Schattenseite der ganzen Operation.\n\nBefrager Vishas ist der grausamste Mann, den ich je das Missvergnügen hatte zu treffen - er hat aus meiner Mutter Informationen \"herausgeholt\", als die Seuche zum ersten Mal ausbrach. Der gnadenlose Blutmagier Thalnos bewacht den Friedhof.\n\nDer heilige Zorn der Kreuzfahrer macht sie blind gegenüber ihrer eigenen Dunkelheit. Sorgt dafür, dass sie ihre Scheinheiligkeit bereuen.", sourceObjective = "Tötet Befrager Vishas und Blutmagier Thalnos.", completion = "Was meint Ihr damit, das Thalnos ein Untoter war? Das ist unmöglich. Dies ist ein heiliger Ort, der Scharlachrote Kreuzzug würde niemals zulassen...\n\nNehmt dies als Belohnung und ruht Euch aus. Die Gruften müssen sehr an Euren Nerven gezerrt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26951] = { id = 26951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufräumen auf der E. Insel", description = "Der Kampf, um die Echoinseln zurückzuerobern, ist uns teuer zu stehen gekommen. Aber er war es wert, {class}. Der große Geist, Bwonsamdi, hat unseren Kriegern geholfen, den widerlichen Zalazane zu besiegen. Er hat unsere Krieger mit den Geistern der Insel beschützt. Aber einige dieser Geister sind im Kampf gefallen. Helft dabei, diesen Geistern die ewige Ruhe zu verschaffen. Ihr werdet auf den Echoinseln herumliegende Masken finden. Sammelt sie auf und bringt sie hierher.", sourceObjective = "Sammelt 8 entzauberte Tikimasken.", sourceObjectiveStatus = "unverified-source-field" }
quests[26952] = { id = 26952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stätte der Heiler", description = "Es gefällt mir nicht, was die Verlassenen hier am Bollwerk anrichten. Bomben, Kessel, sinnloses Blutvergießen... Nichts davon verkörpert das, wofür der Argentumkreuzzug steht. Außerdem gefällt mir die Tatsache nicht, dass sie Söldner wie Euch anheuern.\n\nNichts gegen Euch persönlich, {class}. Nur könntet Ihr so viel mehr aus Euch machen. Wenn Ihr Euch eher für die Heilung der Pestländer interessiert als dafür, sie erneut zu verseuchen, dann meldet Euch in der Stätte der Heiler bei Außenagent Kaartish. Die Stätte liegt gen Osten.", sourceObjective = "Meldet Euch bei Außenagent Kaartish in der Stätte der Heiler in den Westlichen Pestländern.", completion = "Willkommen, {class}. Wie Ihr sehen könnt, besteht unser Lager aus einer Gemeinschaftsexpedition des Argentumkreuzzugs und Druiden des Zirkels des Cenarius. Wir heißen jedoch alle willkommen, die bei der Heilung des Landes helfen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26953] = { id = 26953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zen'Kiki, der Druide", description = "Ich bin Adrine Wergfell, ein Druide des Zirkels des Cenarius. Ihr könnt Euch bei uns für die Heilung dieses Landes, wo einst nur Tod zu finden war, bedanken.\n\nWir nehmen alle auf, die dem Weg des Druiden folgen möchten ungeachtet ihres Volkes, ihrer Fraktion oder ihrem Talent. Hin und wieder bedeutet das die Aufnahme eines Druiden, der mehr Hilfe benötigt als andere.\n\nIch möchte Euch Zen'Kiki vorstellen. Er ist noch recht neu und lernt immer noch sein Handwerk. Würde es Euch etwas ausmachen, wenn Ihr ihn eine Weile mit hinaus nehmt? Ihr könnt an den verseuchten Tieren, die in der Nähe herumstreunen, kämpfen üben.", sourceObjective = "Tötet mit Zen'Kiki an Eurer Seite 20 verseuchte Wildtiere. Ihr könnt schwerfällige Seuchenbären, kranke Wölfe, Giftnebellauerer oder Seuchenlauerer töten.\n\nKehrt zur Stätte der Heiler zurück, wenn Ihr von Zen'Kiki getrennt werdet.", completion = "Anscheinend hat Zen'Kiki immer noch Schwierigkeiten mit der Gestaltwandlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[26954] = { id = 26954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein anderer Ansatz", description = "Zen'Kiki muss unter anderem an der Genauigkeit seiner Zauber arbeiten. Ich konnte sogar von hier aus sehen, wie sein Zorn Zauber vollkommen außer Kontrolle geriet. Ich konnte ihn sogar als Markierung nutzen, um Euren Fortschritt in den Wäldern zu verfolgen.\n\nVielleicht können wir Zen'Kiki anderweitig einsetzen. Nehmt ihn mit hinauf auf den Hügel im Osten. Die kranken Falken, die über diesem Hügel kreisen, müssen vernichtet werden. Bittet Zen'Kiki, auf diese Falken zu schießen. Selbst, wenn er sie nicht trifft, wird er sie ablenken, damit Ihr sie erledigen könnt.", sourceObjective = "Bringt Zen'Kiki auf den Hügel östlich der Stätte der Heiler und lasst ihn 7 kranke Falken herbeirufen und töten.", completion = "Das wird ja langsam was. Wie viele Vögel hat Zen'Kiki getötet?\n\nKeine? Ihr habt sie alle selbst getötet?\n\nAlso gut, ich denke, wir werden für ihn eine andere Verwendung finden müssen. Wir werden Euch informieren, wenn es so weit ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[26955] = { id = 26955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zen'Kiki und die Kultisten", description = "Während Eurer Abwesenheit habe ich versucht, für unseren Freund eine neue Verwendung zu finden. Ich glaube, er könnte eine Zukunft als Heiler haben. Das liegt hauptsächlich daran, dass man mit Heilungszaubern nicht danebenschießen kann.\n\nWie Außenagent Kaartish mir mitteilt, kommen die verseuchten Tiere aus dem Lager der Kultisten im Osten. Ich hoffe, es macht Euch nichts aus, Zen'Kiki dorthin zu begleiten... Vielleicht kann er in dem Lager dort einige der verseuchten Tiere heilen.", sourceObjective = "Bringt Zen'Kiki in den Westlichen Pestländern zu Malicias Außenposten, holt 4 gefangene Seuchenbären aus ihren Käfigen und lasst Zen'Kiki sie heilen.", completion = "Bei der Gnade der Erdenmutter - er hat es geschafft! Danke, {name}.\n\nIch gebe zu, dass ich die Hoffnung, was Zen'Kiki angeht, schon fast aufgegeben hatte. Es ist nur Eurer Geduld und Eurem Pflichtbewusstsein zu verdanken, dass er jetzt zu sich als Druide gefunden hat und ein Mitglied des Zirkels des Cenarius ist. Ganz zu schweigen von dem Guten, das Ihr für die Natur getan habt.\n\nEuch gebührt meine Bewunderung und mein Respekt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26956] = { id = 26956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Guten ins Töpfchen...", description = "{race}! Endlich ist jemand da, der mir helfen kann.\n\nWir Druiden des Cenarius haben Dalsons Hof, der direkt hinter mir liegt, neu bewirtschaftet. Das Land blüht geradezu auf und unsere Ernten waren erfolgreich... zum großen Teil.\n\nEinige Pflanzen scheinen aber noch immer mit der Seuche infiziert zu sein, die dieses Land überzogen hat. Vielleicht waren sie zu tief verwurzelt oder ihre Samen zu schwach. Ich weiß es nicht. Ich weiß nur, dass <ein fähiger/eine fähige:c> {class} wie Ihr vonnöten ist, um die schlechten Pflanzen von den guten zu trennen.", sourceObjective = "Entfernt 6 verdorbene Maispflanzen, 4 verfaulte Äpfel und 3 ungesund aussehende Kürbisse von Dalsons Hof in den Westlichen Pestländern.", completion = "Danke für Eure Hilfe, {name}. Ich weiß, dass Gemüse pflücken nicht gerade die heldenhafteste Tat ist, die man sich vorstellen kann, aber auch bescheidene Aufgaben haben ihren Lohn.", sourceObjectiveStatus = "unverified-source-field" }
quests[26957] = { id = 26957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der lange Heimweg", description = "Ich bin in meinem Leben schon an vielen Orten gewesen, {class}. Ich habe den Kampf um Ahn'Qiraj mitgemacht, bin durch das Dunkle Portal in die Scherbenwelt getreten und habe mich den Argentumkreuzfahrern angeschlossen, um die Geißel im kalten Nordend niederzuschlagen.\n\nDoch vor all dem war ich ein Bauer hier in Lordaeron. Jetzt bin ich hier in Herdweiler, nur wenige Meilen von zu Hause weg. Es wird Zeit, dass ich meinen Respekt erweise.\n\nIch bin unterwegs zur Stätte der Heiler bevor ich nach Hause zurückkehre. Ich würde mich freuen, wenn wir uns nach meiner Ankunft dort wiedertreffen.", sourceObjective = "Trefft Euch erneut mit Del Gahrron in den Westlichen Pestländern in der Stätte der Heiler.", completion = "Anscheinend bin ich vor Euch eingetroffen, {name}.\n\nAußenagent Kaartish hat mir Einzelheiten über meine alte Heimat berichtet. Wie es scheint, sind meine Kämpfe mit der Geißel noch nicht ganz vorüber.", sourceObjectiveStatus = "unverified-source-field" }
quests[26958] = { id = 26958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die erste Lektion", description = "Lasst uns sofort mit Eurer Ausbildung beginnen. Wenn Ihr im Kampf erfahrener seid, werdet Ihr beginnen, neue Techniken zu entwickeln.\n\nGeht, sammelt Erfahrungen, erlernt neue Fähigkeiten und demonstriert sie an den Trainingsattrappen im Nordwesten.", sourceObjective = "Erreicht Stufe 3, um 'Sturmangriff' zu erlernen. Sucht eine Trainingsattrappe an der nordwestlichen Seite der Absturzstelle und übt 'Sturmangriff'.", sourceObjectiveStatus = "unverified-source-field" }
quests[26959] = { id = 26959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beraubt sie ihrer Verteidigung", description = "Wir müssen die Verteidigung des Scharlachroten Klosters ausschalten, bevor eine richtige Invastion stattfinden kann. Stoßt bis in ihre Bibliothek vor und bringt Hundemeister Loksey und Arkanist Doan um. Sie halten die mächtige Verteidigung ihrer Kameraden aufrecht.\n\nMeine Magie wird sicherstellen, dass der Rest des Klosters Euch nicht bemerken wird. Sobald sie tot sind, kann ich weitere Verstärkung herbeirufen, die uns bei unserem Angriff unterstützen wird.\n\nWir müssen erfolgreich sein, {name}. Die Dunkle Fürstin wird ein Versagen nicht im Mindesten tolerieren.", sourceObjective = "Tötet Hundemeister Loksey und Arkanist Doan.", progress = "Habt Ihr Euch um Loksey und Doan gekümmert? Mich zu enttäuschen heißt, die Dunkle Fürstin zu enttäuschen, {race}.", completion = "Ich wusste, ich kann auf Euch zählen! Diese Narren werden niemals wissen, wie ihnen geschah.", sourceObjectiveStatus = "unverified-source-field" }
quests[26960] = { id = 26960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein Sohn, der Prinz", description = "Mein Sohn musste in seinem kurzen Leben bisher schon viele Bürden schultern und ich fürchte, er wird noch mehr Verantwortung übernehmen müssen.\n\nEr wird nie lernen, ein Anführer zu sein, wenn er sich nur in der Burg aufhält, doch ich hasse es, ihn ohne Begleitung hinauszuschicken.\n\n{name}, Eure Taten in der Zeit nach dem Kataklysmus sind bereits legendär. Ihr wärt bestimmt <ein ausgezeichneter Mentor/eine ausgezeichnete Mentorin> für den jungen Prinz Anduin.\n\nBitte, stellt Euch ihm vor. Es gibt dringende Geschäfte für die Stadt, die ihr beide für mich wahrnehmen könnt.", sourceObjective = "Stellt Euch in Burg Sturmwind Prinz Anduin vor. Sprecht mit König Wrynn, wenn Ihr Euch bekannt gemacht habt.", progress = "Wie versteht Ihr beide Euch? Anduin lernt schnell - zeigt ihm, wie er ein wahrer Meister wird, {class}!\n\nSeid Ihr beide bereit?", completion = "Ausgezeichnet, Anduin wird viel lernen, wenn er Euch beobachtet.\n\nDenkt daran, verlasst nicht die Stadt. Haltet ihn von Ärger fern. Und das Wichtigste: Bewacht ihn mit Eurem Leben!\n\n<König Wrynn wendet seine Aufmerksamkeit seinem Sohn zu.>\n\nAnduin - keine Abenteuer! Bleib in der Nähe von {name} und komm zur Burg zurück, wenn es Schwierigkeiten gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26961] = { id = 26961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Götzen sammeln", description = "Vor einer Weile, kurz bevor die Troggs in der Stätte auftauchten, fanden wir eine große Anzahl merkwürdiger, verzierter Götzen Leider hatten wir keine Gelegenheit, sie zu untersuchen, denn kurz nach ihrer Entdeckung haben uns die Troggs aus den Ruinen verjagt! Und diese Götzen haben eine seltsame Wirkung auf die Troggs. Sie verfallen dadurch in Raserei!\n\nBringt mir 8 Götzen - ich möchte sie studieren, und ich will sie nicht mehr in den Händen der Troggs sehen! Ihr könnt die Götzen bei den Troggs finden, die die Stätte heimsuchen.", sourceObjective = "Bringt Magmar Todesstreich an der Eisenband Ausgrabungsstätte 8 verzierte Steingötzen.", progress = "Habt Ihr die Götzen? Wir müssen sie studieren und Eisenschmiede von unseren Ergebnissen berichten!", completion = "Ihr habt sie! Gut gemacht, {name}!\n\nUnd Ihr seht nicht einmal besonders angeschlagen aus, trotz all der wild gewordenen Troggs. Ich werde Euch im Auge behalten... Ihr seid viel versprechend.", sourceObjectiveStatus = "unverified-source-field" }
quests[26962] = { id = 26962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beraubt sie ihres Angriffs", description = "Wie Ihr seht, {name}, ist unser erster Angriff auf die Waffenkammer nicht wie geplant verlaufen. Wir hatten bereits den nahegelegenen Hof eingenommen, da tauchte der Scharlachrote Champion Herod auf.\n\nWir müssen unseren Angriff fortsetzen. Der Scharlachrote Kreuzzug darf hier niemals wieder Krieger ausbilden, geschweige denn, einen Angriff auf Unterstadt starten.\n\nEure Aufgabe ist wohl klar. Nieder mit dem Scharlachroten Held.", sourceObjective = "Tötet Herod.", completion = "Herod ist tot! Die Waffenkammer wird fallen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26963] = { id = 26963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfeinerung Eurer Schüsse", description = "Lasst uns sofort mit Eurer Ausbildung beginnen. Es wird nicht leicht sein, hier zu überleben, und Ihr werdet eine wichtige Rolle für die Versorgung und Sicherheit unserer Leute spielen.\n\nWenn Ihr mehr Erfahrungen sammelt, werdet Ihr neue Fähigkeiten erlernen. Geht, erlernt neue Dinge und probiert sie aus. Kehrt zu mir zurück, wenn Ihr glaubt, dass Ihr sie beherrscht.", sourceObjective = "Erreicht Stufe 3, um 'Zuverlässiger Schuss' zu erlernen. Sucht eine Trainingsattrappe an der nordwestlichen Seite der Absturzstelle und übt fünfmal 'Zuverlässiger Schuss'.", completion = "Ihr solltet diese Technik immer anwendungsbereit haben, {name}. Ich finde sie stets äußerst nützlich. Kehrt zurück, wenn Ihr weitere Ausbildung benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26964] = { id = 26964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Der Silberwald!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Großexekutor Mortuus in der Kommandozentrale der Verlassenen im Silberwald zu melden.\n\nMehr denn je wird Eure Hilfe benötigt, um die Heimsuchung durch unsere Feinde in dieser Region zu beenden und den Hafen von Gilneas zu erobern!\n\nIhr müsst nach Süden durch Tirisfal reisen und Euch in den Silberwald begeben, um die Kommandozentrale der Verlassenen zu erreichen. Folgt der Straße im Silberwald nach Süden, bis Ihr die Kommandozentrale der Verlassenen erreicht.\n\nVorwärts, <Bruder/Schwester>! Das Schicksal ruft!", sourceObjective = "Meldet Euch bei Großexekutor Mortuus in der Kommandozentrale der Verlassenen im Silberwald.", completion = "Sehr gut! Ein neuer Rekrut ist eingetroffen. Es gibt viel zu tun... in der Tat sehr viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[26965] = { id = 26965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegshäuptling kommt", description = "Ihr kommt gerade rechtzeitig, {name}nub. Ihr heißt doch {name}nub, stimmt's?\n\n<Großexekutor Mortuus betrachtet ein Blatt Papier.>\n\nJa, das steht hier in den Papieren: \"{name}nub\".\n\n<Großexekutor Mortuus zeigt auf dem Blatt Papier auf Euren Namen.>\n\nWo war ich noch gleich? Ach ja, Ihr kommt gerade rechtzeitig! Der Kriegshäuptling müsste jeden Moment hier eintreffen, um sich mit unserer Anführerin und Retterin höchstpersönlich zu treffen - der Dunklen Fürstin. Wartet einfach ab und benehmt Euch anständig. Ich bin davon überzeugt, dass wir alle Belobigungen bekommen, wenn diese Kundgebung vorbei ist!", sourceObjective = "Wartet auf die Ankunft von Kriegshäuptling Garrosh Höllschrei.", progress = "Stillgestanden, Sylnarnub!", completion = "Also das war überraschend! Ich will ja nicht an unserem Kriegshäuptling zweifeln, aber...\n\nEgal! Wir haben noch genug Arbeit vor uns. Ich bin sicher, die Dunkle Fürstin und der Kriegshäuptling werden das alles hier in den Griff bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26966] = { id = 26966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Lichts", description = "Als Paladin kennt Ihr das Licht, das uns alle berührt. Gleichzeitig habt Ihr die einzigartige Macht, das Licht im Kampf zur Unterstützung herbeizurufen.\n\nWenn Ihr mehr Erfahrungen sammelt, werdet Ihr dem Licht noch näher kommen und im Kampf neue Kräfte nutzen können.\n\nGeht, werdet erfahrener, bis Ihr eine neue Kraft erlernt habt und zeigt sie mir dann.", sourceObjective = "Erreicht Stufe 3, um 'Siegel des Befehls' zu erlernen. Wendet es an, sucht eine Trainingsattrappe auf der Nordwestseite der Absturzstelle und benutzt Richturteil.", completion = "Ihr habt Euch als guter Schüler erwiesen, {name}. Ich freue mich darauf, Euch wieder zu lehren, wenn die Zeit gekommen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[26967] = { id = 26967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kampf um das Scharlachrote Kloster", description = "Blicket auf die Macht der Verlassenen! Der unaufhaltsame Wille der Dunklen Fürstin durchfließt unsere Körper!\n\nDie meisten der verbliebenen Truppen des Kreuzzugs sind geflohen. Einige leisten allerdings immer noch Widerstand.\n\nIhr habt eine wichtige Rolle beim Erfolg dieser Kampagne gespielt. Sylvanas lässt Euch die Ehre zuteilwerden, ihre letzten noch verbleibenden Feinde zu töten, {name}.\n\nLasst keine Gnade walten.", sourceObjective = "Tötet den Scharlachroten Kommandanten Mograine und Hochinquisitorin Weißsträhne.", completion = "Ja! Das Scharlachrote Kloster gehört jetzt den Verlassenen! Niemand entkommt unserer Rache!\n\nIhr habt die Aufgabe mit der Präzision eines wahren Champions erledigt. Nehmt dies als Belohnung - mit freundlicher Genehmigung der Bansheekönigin.", sourceObjectiveStatus = "unverified-source-field" }
quests[26968] = { id = 26968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostnova", description = "Man erwartet von Euch als zukünftigem Magier, dass Ihr eine Vielzahl von Zaubern beherrscht. Um das zu können, müsst Ihr Eure Verbindung zum Arkanen vertiefen, indem Ihr mächtiger werdet.\n\nGeht, sammelt mehr Erfahrungen als Magier und zeigt mir, was Ihr erlernt habt.", sourceObjective = "Erreicht Stufe 3, um 'Frostnova' zu erlernen. Sucht eine Trainingsattrappe an der nordwestlichen Seite der Absturzstelle und übt 'Frostnova' 2-mal.", completion = "Ihr habt schnell gelernt, diesen neuen Zauber zu beherrschen, {name}. Ich wünschte, alle meine Schüler wären so talentiert. Kehrt zu mir zurück, wenn Ihr weitere Ausbildung benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26969] = { id = 26969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urtümlicher Schlag", description = "Eure Reise mit der Elementarenergie wird Euch an viele Orte führen. Wenn Ihr mehr Macht erlangt, werdet Ihr beginnen, neue Fähigkeiten zu erlernen.\n\n.Lasst uns Eure Reise mit einer einfachen, aber nützlichen Lektion beginnen.\n\nErlernt das Geheimnis des 'Urtümlichen Schlags' und probiert Eure neue Fähigkeit an den Trainingsattrappen aus, die sich nordwestlich der Absturzstelle befinden. Kehrt zu mir zurück, wenn Ihr fertig seid.", sourceObjective = "Erreicht Stufe 3, um 'Urtümlicher Schlag' zu erlernen. Sucht eine Trainingsattrappe an der nordwestlichen Seite der Absturzstelle und übt daran dreimal die Anwendung von 'Urtümlicher Schlag'.", completion = "Es ist ein Vergnügen, einen so fähigen Schüler zu haben. Solange Ihr die Traditionen getreu fortführt, werden die Künste des Schamanismus unserem Volk nie mehr verloren gehen. Kehrt zu mir zurück, wenn Ihr weitere Ausbildung benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26970] = { id = 26970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das richtige Wort", description = "Eine Eurer wichtigsten Pflichten als Priester ist die Anwendung der Macht des Lichts, um Verwundeten zu helfen.\n\nEine weitere ist, Eure Macht offensiv einzusetzen, um sie zu beschützen.\n\nWenn Ihr mehr Erfahrungen sammelt, werdet Ihr dem Licht noch näher kommen und im Kampf neue Kräfte nutzen können.\n\nGeht, werdet erfahrener, bis Ihr eine neue Kraft erlernt habt und zeigt sie mir dann.", sourceObjective = "Erreicht Stufe 3, um 'Schattenwort: Schmerz' zu erlernen und benutzt es dann fünfmal an den Trainingsattrappen an der Absturzstelle.", completion = "Eure Fähigkeiten als Heiler werden sehr gefragt sein, {name}. Zögert nicht, zu mir zurückzukehren, wenn Ihr weitere Ausbildung benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26971] = { id = 26971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bindung", description = "Ein Geräusch in der Hauptkammer des Tempels erregt Eure Aufmerksamkeit. Ihr hört ein wohlbekanntes Lachen... Lorthuna. Sie ist zurückgekommen, um das Ritual zu unterbrechen - Ihr müsst sie aufhalten!", sourceObjective = "Tötet Hohepriesterin Lorthuna.", completion = "Als all dies begann, sagte Maruut, dass er mit Vergnügen sein Leben gäbe, damit unsere Aufgabe erledigt würde. Er wäre stolz auf diesen Erfolg... auf diesen Tod.\n\nDer Riss ist auf dieser Seite jetzt geschlossen. Tiefenheim sollte sich jetzt ein wenig stabilisieren. Es wird Zeit brauchen, bis Thrall die Wunde in Azeroth geheilt hat, und wir werden wahrscheinlich hierbleiben müssen, bis er es geschafft hat.\n\nDanke für alles, was Ihr getan habt. Ohne Euch hätten wir das wahrscheinlich nicht so schnell erreicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26972] = { id = 26972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dunkle Seite des Lichts", description = "Ich habe mich dem Scharlachroten Kreuzzug als junger Paladin voller Eifer angeschlossen, um das Böse aus der Welt zu tilgen. Wie wenig wusste ich doch über die dunkle Wahrheit dieser Fanatiker.\n\nBefrager Vishas und Blutmagier Thalnos überwachen diesen Friedhof. Es bereitet ihnen großes Vergnügen, neue Rekruten endlos zu quälen, um sicherzustellen, dass sie 'rein' sind. Das ist eine Beleidigung des Lichts, {class}!\n\nIch kann nicht länger Teil dieser verdorbenen Organisation sein. Ihr müsst sie beide töten, damit andere nie wieder die Qualen erdulden müssen, die ich ertragen musste.", sourceObjective = "Tötet Befrager Vishas und Blutmagier Thalnos.", completion = "Was meint Ihr damit, dass Thalnos ein Untoter war? Das ist unmöglich. Die ganze Mission des Scharlachroten Kreuzzugs ist darauf ausgerichtet, Untote zu vernichten! Auf gar keinen Fall...\n\nIhr habt meine Gedanken durcheinandergebracht. Bitte nehmt diese Belohnung für Euren Erfolg und lasst mich ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26973] = { id = 26973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der einzig wahre Weg", description = "Ich glaube, dass die Wurzel der Verderbnis des Kreuzzugs hier zu finden ist. Arkanist Doan überwacht die Bibliothek und lehrt viele junge Rekruten, wie man mit den arkanen Künsten umgeht.\n\nDas Licht ist der einzig wahre Weg! Ihr müsst ihn töten, {class}, und diese glorreiche Bewegung rehabilitieren!\n\n<Josef der Erweckte bewegt sich unruhig.>\n\nIhr werdet Euch auch Lokseys entledigen müssen. Seine Hunde scheinen etwas gegen unsere noble Absicht zu haben.", sourceObjective = "Tötet Hundemeister Loksey und Arkanist Doan.", completion = "Gute Arbeit! Ich weiß einfach, dass das Licht wohlwollend auf uns und unsere Arbeit scheint. Unsere Sache ist gerecht!", sourceObjectiveStatus = "unverified-source-field" }
quests[26974] = { id = 26974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der falsche Champion", description = "Wir...wir...wir mussten sie töten! Sie waren hinter uns her!\n\nIhr glaubt mir doch, nicht wahr, {name}?\n\nHerod ist nicht der wahre Champion des Scharlachroten Kreuzzugs. Ich bin es! Er hat das, was rechtmäßig mir gehört, an sich gerissen!\n\nIhr solltet ihn töten. Er ist...eine Bedrohung! Er bildet Soldaten aus, die jeden töten und nicht nur die Untoten.\n\nIch werde Euch fürstlich belohnen...", sourceObjective = "Tötet Herod.", completion = "Also ist er wirklich tot? Das bedeutet... Ich, Josef, bin der neue Scharlachrote Champion!!!\n\nNehmt dies. Ich habe ohnehin keine Verwendung für derartige Besitztümer. Schließlich bin ich der Scharlachrote Champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[26975] = { id = 26975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flotte zusammenrufen", description = "Ich rufe eine Kriegsflotte zusammen, um das Schattenhochland anzugreifen und den Lakaien von Todesschwinge ihr Ende zu bereiten.\n\nMeine Soldaten sind bereit, aber die Vorbereitungen der Flotte verzögern sich. Meine Männer an den Docks brauchen Inspiration und Motivation. Ein Besuch des Prinzen sollte sie aufmuntern und ihnen erneut die glorreiche Zukunft vor Augen führen, für die sie kämpfen.\n\nGeht mit Prinz Anduin zu den Docks und sprecht mit Nachschuboffizier Graves. Ich möchte, dass Anduin sieht, wie ein geborener Anführer mit der Situation umgeht.", sourceObjective = "Begleitet Prinz Anduin zu den Docks in Sturmwind und sprecht mit Nachschuboffizier Graves. Wenn Ihr und der Prinz Euch aus den Augen verliert, findet Ihr ihn im Thronzimmer von Sturmwind.", completion = "<Graves verbeugt sich respektvoll vor dem Prinz.>\n\nBitte versteht, Eure Hoheit, die Leute arbeiten in Doppelschichten. Das, was Euer Vater vorhat, ist von ungeheurem Ausmaß.\n\nAber wir sind bestrebt, alles fertig zu bekommen. Ich gebe Euch mein Wort.", sourceObjectiveStatus = "unverified-source-field" }
quests[26976] = { id = 26976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kampf um das Scharlachrote Kloster", description = "Oh, schön, Euch wiederzusehen, {name}! Ich fürchte, ich brauche Eure Hilfe.\n\nWisst Ihr, Mograine ist hier der Befehlshabende zusammen mit Hochinquisitorin Weißsträhne. Sie haben versucht, mir einzureden, dass ich eigentlich nicht der neue Scharlachrote Champion bin. Die Jungs und ich finden das gar nicht gut.\n\nWir werden jetzt das Scharlachrote Kloster selbst übernehmen und die Ordnung so wieder herstellen, wie sie immer hätte sein sollen - mit mir an der Spitze! Ich werde mich der Verlassenen und der Geißel endgültig entledigen.\n\nHelft Ihr einem alten Freund?", sourceObjective = "Tötet den Scharlachroten Kommandant Mograine und Hochinquisitorin Weißsträhne.", completion = "Ja! Das Scharlachrote Kloster gehört uns! Ihr seid ein wahrer Freund. Nehmt dies zur Belohnung und kommt mich jederzeit besuchen, nachdem ich Unterstadt ebenfalls übernommen habe.\n\nDas wird ein scharlachrotes Paradies!", sourceObjectiveStatus = "unverified-source-field" }
quests[26977] = { id = 26977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung im Zwielicht", description = "Die Verräterischen Taten des Schattenhammers in den letzten Monaten haben die Stadt in Aufruhr versetzt. Sie haben es auf die Ängste der Bauern abgesehen und korrumpieren unsere wichtigsten Bürger. Wir müssen herausfinden, wie tief diese Verschwörung bereits sitzt.\n\nIch habe Major Samuelson von der Stadtwache von Sturmwind beauftragt, eine Untersuchung zu leiten. Er ist hier im Thronraum. Seht, ob Ihr ihn bei seinen Bemühungen unterstützen könnt.", sourceObjective = "Sprecht in Burg Sturmwind mit Major Samuelson.", completion = "Hmmm, ja? Meine Untersuchung des Schattenhammers. Natürlich.\n\nEure Mitarbeit wird von unschätzbarem Wert sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26978] = { id = 26978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer braucht Kessel?", description = "Habt Ihr den Zustand vom Teufelssteinfeld gesehen? Die Streitkräfte der Allianz aus Andorhal haben das Gebiet übernommen und benutzen es, um...um...FELDFRÜCHTE anzubauen!\n\nDa gefiel es mir fast schon besser, als die Geißel das Gebiet noch besetzt hielt. Wenigstens hatten sie so viel Verstand, einen riesigen Seuchenkessel mitten aufs Feld zu stellen.\n\nWir werden uns den Hof von diesen Menschen zurückholen, {name}. Nehmt diese Fässer und stellt sie an Schlüsselpositionen um das Feld herum auf. Ich werde hier am Bollwerk warten.", sourceObjective = "Stellt Zitters Seuchenfässer in der Nähe der Windmühle, bei den Getreidesilos, am Farmhaus und bei der Scheune am Teufelssteinfeld auf.", completion = "<Zitters glüht geradezu vor Aufregung.>\n\nDie Fässer sind aufgestellt? Auf ihren Positionen?\n\nNun gut, ich werde dem Hochexekutor Bericht erstatten. Wenn es so weit ist, wird er derjenige sein, der den Auslöser drückt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26979] = { id = 26979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Merkwürdige neue Gesichter", description = "Jetzt, da Teufelsstein uns gehört, können wir seine Äcker - und alle Leichen, die wir finden - für unsere Zwecke nutzen. Ich habe von oben den Befehl erhalten, dass Ihr dabei helfen sollt.\n\nVielleicht habt Ihr Lindsay Rabensonn bereits auf dem Schlachtfeld bei Andorhal kennengelernt. Ich habe sie noch nie getroffen, aber sie scheint einige hohe Tiere als Freunde zu haben, denn sie übernimmt das Kommando hier in Teufelsstein. Ihr sollt sie bei dem niedergebrannten Scharlachroten Lager treffen, das ihr vor Kurzem ausspioniert habt.", sourceObjective = "Meldet Euch in den Westlichen Pestländern am Niedergebrannten Außenposten bei Lindsay Rabensonn.", completion = "{name}. Die Dunkle Fürstin wacht über Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26980] = { id = 26980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnellschalts Station", description = "Ihr habt hier gute Arbeit geleistet, {name}. Euch jetzt zu bitten, Sandsäcke zu schleppen, wäre die reine Verschwendung. Um ehrlich zu sein, schicke ich Euch lieber dahin, wo Eure Fähigkeiten gebraucht werden.\n\nWir haben im Marschengebiet weiter nördlich einen kleinen Außenposten. Schnellschalt ist der Gnom, der ihn gebaut hat, aber Ihr solltet mit Shilah Fliesmeißel sprechen und ihr bei Angelegenheiten für Eisenschmiede helfen.\n\nIch gebe zu, sie sieht echt gut aus... aber ich würde nicht den Fehler machen, mir bei ihr irgendwelche Freiheiten herauszunehmen! Die Familie heißt nicht umsonst Fliesmeißel.", sourceObjective = "Sprecht an der Station Schnellschalt nördlich vom Hafen von Menethil mit Shilah Fliesmeißel.", completion = "Starkfaust hat Euch geschickt, ja? Er ist ein guter Hauptmann, führt seine Leute gut. Ich wünschte nur, er würde aufhören, mir auf die Taille zu starren.\n\nUnd Euch will ich auch nicht dabei erwischen. Wir haben hier zu arbeiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[26981] = { id = 26981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whelgars Zuflucht", description = "Ausgrabungsleiter Whelgar hat südlich von hier in diesen Bergen seit geraumer Zeit die Ausgrabungen geleitet. Früher einmal hatte er Probleme mit Raptoren, aber in letzter Zeit hatte sich die Lage gebessert.\n\nVor ein paar Tagen haben wir nun erfahren, dass er die ganze Ausgrabungsstätte evakuieren musste. Ich weiß nicht, was dort vor sich geht, aber ich kann mir nicht vorstellen, dass der Kataklysmus einen Steinbruch sicherer gemacht hat als vorher.\n\nDort arbeiten gute Zwerge, {name}. Würdet Ihr hingehen und nachsehen, was dort los ist und vielleicht auch helfen?", sourceObjective = "Sprecht bei Whelgars Zuflucht südlich der Station Schnellschalt mit Ausgrabungsleiter Whelgar.", completion = "Seid gegrüßt, {class}. Wir haben auf jeden Fall ein Raptorenproblem... oder so was in der Art.\n\nEs ist eher, dass die ganze Grabungsstätte auf uns losgegangen ist. Ich habe noch nie gesehen, dass Felsen und Fossilien sich so aufregen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[26982] = { id = 26982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Scharlachrote Kloster", description = "Das Kloster in Tirisfal, das die Scharlachroten Kreuzfahrer jetzt besetzt halten, war früher einmal die Ausbildungsstätte für unsere Paladine. Jetzt lauern dort die Verlassenen aus Unterstadt und der Kreuzzug verhindert, dass wir es für die Ausbildung der Soldaten nutzen, die wir so dringend benötigen, um mit den Verlassenen fertigzuwerden.\n\nHört zu, ich traue ihm zwar nicht über den Weg, aber Josef der Erweckte wartet auf dem Friedhof. Geht und sprecht mit ihm - obwohl er ein Kreuzfahrer ist, sagt er, dass er sich gegen sie auflehnt und uns die Gelegenheit gibt, das zurückzuholen, was uns gehört.", sourceObjective = "Besucht Josef den Erweckten.", completion = "Hauptmann Nials hat Euch geschickt? Ich habe sie schon ewig lange nicht mehr gesehen! Wie geht es ihr? Hat sie meinen Brief erhalten?\n\nOh, Ihr seid nicht deswegen hier. Na, dann lasst uns zum Geschäft kommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26983] = { id = 26983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerade nah genug", description = "Täuscht Euch nicht - es gibt hier noch viel zu tun! Dennoch müssen wir auch dort gegen die Verlassenen zurückschlagen, wo wir sie empfindlich treffen können. Das Scharlachrote Kloster in Tirisfal liegt in perfekter Entfernung zu Unterstadt und Brill.\n\nMeldet Euch bei Josef dem Erweckten in der Bibliothek. Er ist ein aufständischer Kreuzfahrer, der uns vielleicht dabei helfen kann, das Kloster als unsere Basis für alle Operationen in dem Gebiet zu übernehmen. Wenn Ihr schon dabei seid, könnt Ihr auch gleich Arkanist Doan eliminieren, einen ihrer mächtigsten Magier.", sourceObjective = "Besucht Josef den Erweckten.", completion = "Ihr seid von Süderstade hiergekommen, nicht wahr? Ich wette, dass Rachehunger gegen die widerwärtigen Verlassenen den Ort in Schutt und Asche gelegt hat. Der Scharlachrote Kreuzzug kann helfen, sich darum zu kümmern!\n\nDas heißt, sobald Ihr mir geholfen habt, ihre fehlgeleiteten Seelen wieder auf den rechten Weg zu führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26984] = { id = 26984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein alter, verrückter Freund", description = "Josef der Wahnsinnige war hier einer meiner guten Freunde, bevor er sich dem Scharlachroten Kreuzzug im Scharlachroten Kloster in Tirisfal anschloss. Ich hörte, dass er in der Waffenkammer dort ist und einen lächerlichen Versuch unternimmt, Herods Position als Scharlachroter Champion zu übernehmen.\n\nEs ist reiner Selbstmord, Herod so herauszufordern! Geht dort hinauf und versucht, ihm das auszureden.", sourceObjective = "Besucht Josef den Wahnsinnigen.", completion = "Ihr seht zäh aus, {class}. Es gilt hier, viel Unrecht wiedergutzumachen. Lasst uns anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26985] = { id = 26985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahnsinn gegen Irrsinn ausspielen", description = "Unsere frisch verstärkten Streitkräfte kommen mit der Situation hier für eine Weile ohne Euch zurecht. Ich habe Berichte erhalten, dass Josef der Irrsinnige, eine früherer Offizier des Scharlachroten Kreuzzugs, sich im Scharlachroten Kloster aufhält und mit seiner Gruppe Abtrünniger gegen den Scharlachroten Kommandanten Mograine losschlagen will.\n\nDas ist eine ausgezeichnete Gelegenheit. Geht dort hin und helft ihm bei seinem irrsinnigen Vorhaben. Vielleicht können wir dann das Kloster als Festung genau auf der Türschwelle von Sylvanas benutzen.", sourceObjective = "Besucht Josef den Rasenden.", completion = "Moment, Ihr wurdet von DER Shandris Mondfeder hierhergeschickt? Ich traue meinen Ohren nicht! Zu wissen, dass meine Sache von ihrer riesigen Armee unterstützt wird...\n\nJa, ja, Ihr seid perfekt. Ihr seid der Schlüssel zu meiner Zukunft!", sourceObjectiveStatus = "unverified-source-field" }
quests[26986] = { id = 26986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In das Scharlachrote Kloster", description = "Um sicherzustellen, dass unsere Männer sich so wenig Verletzungen wie möglich zuziehen, ist es oftmals am besten, unseren Feinden zuhause großen Schaden zuzufügen, um so zu verhindern, dass Schlachten überhaupt stattfinden!\n\nReist zum Scharlachroten Kloster und sprecht mit der dunklen Waldläuferin Velonara auf dem dortigen Friedhof. Sie führt einen Angriff der Verlassenen an und <ein erfahrener/eine erfahrene:c> {class} wie Ihr könnte ihr eine große Hilfe sein.", sourceObjective = "Meldet Euch bei der dunklen Waldläuferin Velonara.", completion = "Sieht so aus, als ob Darthalia wie von mir gewünscht einen fähigen {class} geschickt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[26987] = { id = 26987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der rechte Weg", description = "Meine Leute sind generell nicht sehr von den arkanen Künsten, die von anderen Völkern missbraucht werden, angetan. Glücklicherweise sind wir weit von den Zauberen in der Bücherei des Scharlachroten Klosters entfernt, doch ihre Fähigkeit, sich über die materielle Welt hinwegzusetzen, bereitet mir Sorgen und stellt letztendlich eine Gefahr für das Überleben meines Stammes dar.\n\nReist weit nach Westen zur Bücherei des Klosters und sprecht dort mit der dunklen Waldläuferin Velonara. Ihre Streitkräfte stehen schon kurz davor Arkanist Doan, den führenden Magus des Kreuzzugs, höchstpersönlich anzugreifen.", sourceObjective = "Sprecht mit der dunklen Waldläuferin Velonara.", completion = "Ich bin überrascht, dass Jäger Mark'hor zur Abwechslung einmal mit mir zusammenarbeitet. Er ist sonst ziemlich stur. Allerdings nährt er einen starken Hass gegen Magie.\n\nIch hoffe, Ihr tut das auch, {class}, denn wir werden dem Scharlachroten Kreuzzug seine Magie wegnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26988] = { id = 26988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sache in Schwung bringen", description = "Ich warte auf einige sehr mächtige Reagenzien, die ich vor Kurzem aus Unterstadt bestellt habe. Wie ich höre, verzögert sich die Lieferung, weil die Kreuzfahrer des Scharlachroten Klosters den Weg versperren. Der Scharlachrote Champion Herod ist wahrscheinlich für diese Unannehmlichkeit verantwortlich.\n\nBitte geht und sprecht mit der dunklen Waldläuferin Velonara in der Waffenkammer des Scharlachroten Klosters. Sie wird sich um Herod kümmern, was bedeutet, dass meine Lieferung sicher ankommt!", sourceObjective = "Besucht die dunkle Waldläuferin Velonara.", completion = "Yayo'jin hat Recht, wenn Ihr mir hier helft, wird ihr das im Hinterland ebenfalls helfen.\n\nNoch ein Grund, warum wir sofort loslegen sollten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26989] = { id = 26989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gilnearische Befreiungsfront", description = "Der Kampf um die Region tobt immer noch, {name}nub. Obwohl wir die Verteidiger von Gilneas vernichtend geschlagen und Gilneas für die Horde eingenommen haben, ist es einer kleinen Gruppe Rebellen gelungen, zu entkommen. Die \"Gilnearische Befreiungsfront\" - wie sie sich selbst nennen - ergreift jede Gelegenheit, unsere Truppen draußen anzugreifen. Den Rebellen sind einige kleinere Siege gelungen und jetzt werden sie bei ihren Angriffen immer dreister! Es ist an der Zeit, zurückzuschlagen, {name}nub.\n\nGeht nach Süden in die Wildnis von Silberwald und tötet jeden Rebellen, dem Ihr begegnet.", sourceObjective = "Tötet 10 Worgenrenegaten.", completion = "Taubstummnub ist zurückgekehrt! In einem Stück!\n\nVerteidiger von Silberwald! Erlöser der Horde! Taubstummnub, Eure Tapferkeit muss belohnt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[26991] = { id = 26991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feinde vor den Toren", description = "Manchmal müssen wir die Notwendigkeit, unsere Verbündeten zu beschützen, anerkennen, damit sie uns beschützen können. Dies ist eine solche Gelegenheit, {race}.\n\nReist zum Scharlachroten Kloster in der Nähe von Unterstadt in Tirisfal. Sobald Ihr dort eintrefft, geht zur Kathedrale und sprecht mit der dunklen Waldläuferin Velonara. Sie führt den letzten Schlag gegen den Kreuzzug dort und es würde uns allen sehr zum Vorteil gereichen, wenn wir sicherstellen, dass unsere untoten Verbündeten das Kloster übernehmen, bevor die Kreuzfahrer eine Chance haben, ihre Hauptstadt anzugreifen.", sourceObjective = "Findet die dunkle Waldläuferin Velonara.", completion = "Nazeer ist ein kräftiger Krieger - sein Hass auf unsere Feinde ist noch stärker als meiner. Ihr seid eingeladen, meinen Streitkräften zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26992] = { id = 26992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmerz im Überfluss", description = "Zweifellos habt Ihr von dem Vorfall gehört, der sich am Zornestor in Nordend abgespielt hat, nicht wahr? Wegen dieser unglückseligen Vorkommnisse ist es uns strengstens verboten, den Erregerstamm der todbringenden Krankheit, den wir endlich perfektioniert hatten, zu verwenden. Jetzt gibt es Regeln und Vorschriften und anderen Unsinn!\n\nMan hat uns eine entschärfte Version der perfekten Krankheit gegeben und erwartet nun, dass wir daraus eine Waffe basteln.\n\nWenn ich diesen Mist zum Funktionieren bringen soll, dann brauche ich einige Taschen voll mit wildem Verdammniskraut. Ihr findet es überall im Silberwald.", sourceObjective = "Sammelt 8-mal Wildes Verdammniskraut.", progress = "Habt Ihr das wilde Verdammniskraut gesammelt, um das ich Euch gebeten hatte?", completion = "Schmerz im Überfluss, sage ich Euch! Das Land selbst droht, uns zu verschlingen und dennoch bestehen wir fort. Ich frage mich, warum das so ist? Mit diesem Verdammniskraut, den Eingeweiden und dem geronnenen Blut, das T'Veen benötigt, haben wir vielleicht etwas Geeignetes, das wir an die Frontlinie der Verlassenen senden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[26993] = { id = 26993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kompendium der Gefallenen", description = "Keine Angst, ich diene keinem Herrn, {race}. In diesen Hallen liegt ein Buch, genannt Kompendium der Gefallenen. Es enthält Unmengen von Forschungsergebnissen, die der Scharlachrote Kreuzzug im Laufe der Jahre über meinesgleichen zusammengetragen hat.\n\nEinfach gesagt möchte ich, dass Ihr es findet und zu mir zurück bringt, ohne Fragen zu stellen.", sourceObjective = "Findet das Kompendium der Gefallenen.", progress = "Ich möchte nicht noch länger in einem Kloster bleiben, das voller Zeloten ist, die Untote hassen. Das könnt Ihr sicherlich nachvollziehen. Sprecht mich nicht an, solange Ihr das Buch nicht bei Euch tragt.", completion = "Gut gemacht! Wie wäre es, wenn ich Euch eine hübsche Belohnung für Eure Arbeit gebe und Ihr erzählt niemanden, dass Ihr mich hier gesehen habt. Einverstanden?", sourceObjectiveStatus = "unverified-source-field" }
quests[26994] = { id = 26994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohne Sinn und Verstand", description = "Wie ich höre, möchte Joseph der Wahnsinnige, dass Ihr Herod tötet. Wenn Ihr schon dabei seid, warum bringt Ihr dann auch nicht gleich ihre besten Soldaten um? Ich werde Euch für Eure Arbeit gut bezahlen.\n\nZerbrecht Euch über das 'Warum' nicht den Kopf, nur über das 'Wie'.", sourceObjective = "Tötet 3 scharlachrote Myrmidonen, 3 scharlachrote Beschützer, 3 scharlachrote Gardisten und 3 scharlachrote Rufer.", progress = "Spielen wir keine Spielchen... Sind sie tot oder nicht?", completion = "Sehr gut! Ja, in der Tat, sehr gut.\n\nEure Belohnung, wie versprochen. Keine Fragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26995] = { id = 26995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Innereien und Blut", description = "Wenn wir diese neue Krankheit in die Gänge bringen wollen, brauchen wir saubere Tierinnereien. Das Problem ist, dass saubere Tierinnereien im Silberwald ausgesprochen selten sind. Die meisten Tiere sind von Krankheiten befallen und haben daher nur kranke Innereien.\n\nDurchsucht das Waldgebiet östlich von hier nach Worgs und ergrauten Bären. Tötet nur die, die nicht von Krankheiten befallen sind und reißt ihnen die Innereien heraus. Bringt mir so viele saubere Eingeweide, wie Ihr in Euren Rucksack stopfen könnt.", sourceObjective = "Findet 6 \"saubere\" Tierinnereien.", progress = "Denkt daran, ich kann nur saubere Tierinnereien für den neuen Erregerstamm der Krankheit, die wir entwickeln, gebrauchen.", completion = "Ausgezeichnet! Mit diesen Eingeweiden und dem wilden Verdammniskraut können wir den Erregerstamm unserer neuen Krankheit testen. Jetzt müssen wir nur noch ein geeignetes Ziel auswählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26996] = { id = 26996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genau vor ihren Nasen", description = "In dem rechten Seitenraum der verfluchten Kathedrale ist an der Wand eine Fackel. Bewegt sie und eine Geheimtür wird sich öffnen. Dahinter befindet sich Hochinquisitor Schönufer. Er ist jetzt ein Untoter.\n\nJemand muss ihn erledigen. Wenn möglich, tötet ihn in seinem Zimmer. Ich ziehe es vor, wenn die Kreuzfahrer ihn nicht sehen. Ihr kennt das ja - tötet ihn und ich gebe Euch eine Belohnung. Wir müssen nichts weiter sagen.", sourceObjective = "Tötet Hochinquisitor Schönufer..", completion = "<Dominic gibt Euch Eure Belohnung. Kein Wort wird gewechselt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26997] = { id = 26997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die üblichen Verdächtigen", description = "<Samuelson kratzt sich gedankenverloren das Kinn.>\n\nMeine Untersuchungen haben ergeben, ähm, es ist möglich, dass sich unter den Dockarbeitern von Sturmwind Ärger zusammenbraut. Durchtriebene Bande. Ich traue denen nicht!\n\nIhr solltet dahin gehen und alles mal ordentlich auf den Kopf stellen. Fühlt diesen Hafenarbeitern auf den Zahn. Das sollte Euch eine Weile beschäftigen.\n\nGeht und eliminiert diese Ungläubigen des Schattenhammers!", sourceObjective = "Fühlt im Hafen von Sturmwind 6 Dockarbeitern von Sturmwind auf den Zahn.", progress = "Samuelson schien nicht viel von Euch zu halten. Glaubt Ihr wirklich, dass die Dockarbeiter etwas mit dem Schattenhammer zu tun haben?", completion = "Das ergibt doch keinen Sinn, {name}.\n\nWarum hat Samuelson uns hier hinaus auf eine sinnlose Verfolgungsjagd geschickt?\n\nDa stimmt doch etwas nicht. Wir sollten auf eigene Faust Nachforschungen anstellen...", sourceObjectiveStatus = "unverified-source-field" }
quests[26998] = { id = 26998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Erfolg fortsetzen", description = "Das Gebräu ist endlich fertig, aber bevor ich diesem Erregerstamm mein Gütesiegel verleihe, müssen wir einen Feldversuch unternehmen.\n\nSprecht hier in der Kommandozentrale mit Fledermausführer Madenhauch und verschafft Euch eine Fledermaus. Die Fledermaus bringt Euch über den Lordameresee hinweg zu den Morgeninseln, mitten ins Herz der Verderbnis - zu den Höhlen der Murlocs der Finsterflossen.\n\nBenutzt dieses Gebräu gegen die Murlocs und berichtet mir über die Ergebnisse.\n\nDie Ergebnisse sollten natürlich so aussehen, dass Ihr sie alle wie befohlen getötet habt!", sourceObjective = "Tötet 50 Murlocs der Finsterflossen.", progress = "Habt Ihr die Murlocs der Finsterflossen auf den Morgeninseln ausgerottet?", completion = "Stark genug, um tausend Murlocs auszurotten! Ich glaube, das schreibe ich auf das Etikett. Ihr habt gute Arbeit geleistet, {name}, und gute Arbeit wird hier belohnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26999] = { id = 26999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Ära für die Pestländer", description = "Die Geißel hat die Macht über dieses Gebiet verloren. Wir, die Lebenden, übernehmen Lordaeron wieder.\n\nWir haben bereits große Fortschritte gemacht, wie Ihr gesehen habt. Die Erde erblüht, die Bäume wachsen immer höher und sind grün und die Tierwelt kehrt langsam zurück. Dennoch sind eine Handvoll Untote zurückgeblieben.\n\nDie Bäume und das Gras gedeihen, aber die Tiere haben Schwierigkeiten. Etwas hindert sie an ihrer Heilung und ich gedenke herauszufinden, was das ist. Bringt mir Proben von den verseuchten Tieren, damit ich sie mir genauer ansehen kann.", sourceObjective = "Sammelt Proben von 4 Seuchenlauerern, 4 Giftnebellauerern, 4 schwerfälligen Seuchenbären und 4 kranken Wölfen.", progress = "Sobald die Tiere geheilt sind, wird unsere Pflicht hier draußen fast erfüllt sein.", completion = "Das ist mehr als genug, {name}. Jetzt brauche ich etwas Zeit, um meine Studien durchzuführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27000] = { id = 27000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Komm, hol das Lasso raus", description = "Ah, schön wieder auf dem Nordkamm zu sein! Ich habe mein Sägewerk, meine hübsche Frau, meinen quietschfidelen kleinen Jungen... Ich habe mich sogar dem Argentumkreuzzug angeschlossen. Wir werden Tirions Streitkräfte mit Holz versorgen.\n\nMeine Holzfäller waren ausgesprochen produktiv... bis die Spinnen kamen. Jetzt weigern sie sich, tiefer in den Wald zu gehen.\n\nVielleicht könntet Ihr mir helfen. Schwingt Euch auf eins meiner Pferde und jagt den Spinnen Angst ein. Vielleicht können wir Blutvergießen vermeiden und sie einfach fortjagen.", sourceObjective = "Steigt am Sägewerk des Nordkamms auf einen Herdweiler Mustang und benutzt seine Fähigkeit 'Wiehern', um 25 Nordkammspinnen Angst einzujagen.", completion = "Nun, es hört sich so an, als ob sie große Angst vor dem Mustang haben, aber sie bleiben nicht weg. Ich kann Euch nicht ewig auf dem Pferd herumrennen lassen. Und ich glaube auch nicht, dass Ihr das möchtet.\n\nAlso gut. Dann eben Blutvergießen...", sourceObjectiveStatus = "unverified-source-field" }
quests[27001] = { id = 27001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hier ist WoW (Wald ohne Wildspinnen)", description = "Der Hochlord war so großzügig, einige seiner Rekruten zu entsenden, damit sie uns hier am Sägewerk unterstützen. Mit Eurer Reitkunst und ihren Kampfkünsten können wir uns dieses Spinnenproblems mit Leichtigkeit entledigen.\n\nSteigt wieder auf den Mustang und macht den Spinnen Angst. Diesmal müsst Ihr sie aber bis zum Sägewerk vor Euch hertreiben. Die Rekruten aus Herdweiler können sich dann hier der Dinge annehmen.", sourceObjective = "Besteigt am Sägewerk des Nordkamms einen Herdweiler Mustang und benutzt seine Fähigkeit 'Wiehern', um 10 Nordkammspinnen zu den Rekruten von Herdweiler an der Nordkamm Sägemühle zu treiben. Ihr könnt mehrere Spinnen auf einmal zusammentreiben.", completion = "So ist es schon viel besser! Jetzt können meine Holzfäller wieder an die Arbeit gehen.\n\nWie schon gesagt, Ihr seid da draußen gut geritten, {name}. Auf dem Mustang gebt Ihr ein echt gutes Bild ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[27002] = { id = 27002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Audienz mit dem Hochlord.", description = "Oh, bevor Ihr geht, {name}... Ich habe eine Nachricht für Euch. Jemand in Herdweiler möchte Euch gerne kennenlernen. Er sagte, dass er bereits einige Male über Euren Namen gestolpert ist.\n\nIhr könnt Euch glücklich schätzen, {name}. Nicht jeder bekommt eine persönliche Audienz mit Hochlord Tirion Fordring.\n\nOh - und Ihr dürft gerne einen meiner Mustangs für den Ritt dorthin nehmen. Sie sind die schnellsten, die man für Geld kaufen kann.", sourceObjective = "Meldet Euch in den Westlichen Pestländern in Herdweiler bei Hochlord Tirion Fordring.", completion = "{name}. Es ist mir wirklich ein Vergnügen.\n\nIch weiß, Ihr seid jung und steht noch in Ausbildung, aber ich habe Euch im Auge behalten. Wir beim Argentumkreuzzug suchen immer nach vielversprechenden Rekruten und Ihr habt großes Potenzial gezeigt. Ich habe noch keine Aufgaben für Euch, doch ich wollte Euch persönlich kennenlernen und mir selbst ein Bild davon machen, was Ihr für ein {race} seid.\n\nFür den Moment dürft Ihr Euch an den Annehmlichkeiten von Herdweiler erfreuen. Ich freue mich auf unser nächstes Treffen, {name}. Ihr dürft wegtreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27003] = { id = 27003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leichtverdientes Geld", description = "Wen haben wir denn da!\n\nWie auch immer Ihr hierhergekommen seid, ich bin so froh, dass Ihr hier seid!\n\nMeine Freunde hier würden es nie zugeben, aber wir können wirklich Hilfe gebrauchen.\n\nDie uralte Region von Uldum ist freigelegt worden! Dort gibt es Schätze, die Eure kühnsten Träume übertreffen, und man kann sie einfach mitnehmen!\n\nDas einzige, was wir brauchen, ist eine kleine Eskorte, bei den ganzen Banditen und so...\n\nIhr werdet uns begleiten, oder?\n\nIhr dürft auch so viele Schätze mitnehmen, wie Ihr tragen könnt!", sourceObjective = "Begleitet Adarrahs Karawane hinein nach Uldum.", completion = "Es riecht, als wäre vor Kurzem jemand in dieser Zelle gewesen.\n\nIgitt!", sourceObjectiveStatus = "unverified-source-field" }
quests[27004] = { id = 27004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtpläne", description = "Wir sind hierhergekommen, um Gerüchten über ein Artefakt der Titanen am Tor der Meister gen Südwesten nachzugehen.\n\nEiner dieser Kultisten vom Schattenhammer muss doch die Pläne für das, was sie hier vorhaben, bei sich haben. Ihr müsst sie für uns holen, {name}.\n\nDurchsucht die Kultisten, bis Ihr sie findet.", sourceObjective = "Sammelt die Pläne für das Tor der Meister.", progress = "Diese Pläne sind der Schlüssel zu allem.", completion = "<Mowi betrachtet die Pläne, die Ihr ihr gegeben habt.>\n\nAber… aber das ist nichts als Kauderwelsch!\n\nWas soll das überhaupt bedeuten? Welche Sprache ist das?", sourceObjectiveStatus = "unverified-source-field" }
quests[27005] = { id = 27005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtpläne", description = "Wir sind hierhergekommen, um Gerüchten über ein Artefakt der Titanen am Tor der Meister gen Südwesten nachzugehen.\n\nEiner dieser Kultisten vom Schattenhammer muss doch die Pläne für das, was sie hier vorhaben, bei sich haben. Ihr müsst sie für uns holen, {name}.\n\nDurchsucht die Kultisten, bis Ihr sie findet.", sourceObjective = "Sammelt die Pläne für das Tor der Meister.", progress = "Diese Pläne sind der Schlüssel zu allem.", completion = "<Der Prüfer betrachtet die Pläne, die Ihr ihm gegeben habt.>\n\nDas ist nichts als Kauderwelsch!\n\nWas soll das überhaupt bedeuten? Welche Sprache ist das?", sourceObjectiveStatus = "unverified-source-field" }
quests[27006] = { id = 27006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überflieger", description = "Ich hab versucht, die Terrasse zu überfliegen und mir selbst 'n Bild zu machen, aber diese toastfressenden Weicheier ha'm auf mich geschossen und ich kam nicht dran.\n\nIhr seht so aus, als ob Ihr mit Zügeln umgehen könnt. Warum nehmt Ihr nicht Euer Flugtierchen und fliegt hoch nach Südwesten, mal nachsehen, was der ganze Wirbel soll?", sourceObjective = "Untersucht den mittleren Bereich im hinteren Teil des Tors der Meister.", completion = "Ein Tor?! Die Kulties ha'm ein Titanentor ausgebuddelt?", sourceObjectiveStatus = "unverified-source-field" }
quests[27007] = { id = 27007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stelldichein in den Silbermarschen", description = "Ausgezeichnete Arbeit, {name}. Wir wissen genau, wo der Treffpunkt ist.\n\nDie Oberen Silbermarschen sind ein Quecksilbersumpf östlich von hier. Normalerweise hausen dort Elementare und gelegentlich auch Steintroggs, aber unsere Späher haben in der Region Aktivität des Schattenhammers beobachtet.\n\nMacht Euch auf den Weg dorthin und findet eine Möglichkeit, das Treffen des Schmiedemeisters zu belauschen.", sourceObjective = "Geht zu den Oberen Silbermarschen in Tiefenheim.", completion = "Das ist der Ort. Unsere Späher haben die Anwesenheit von hochrangigen Offizieren des Schattenhammers bestätigt und gleichzeitig mögliche Troggjäger ausgemacht.\n\nSeid vorsichtig, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27008] = { id = 27008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überflieger", description = "Ich bin ziemlich geschickt im Umgang mit dem fliegenden Teppich. Doch als ich versucht habe, herauszufinden, was diese Kultisten auf der Zwielichtterrasse entdeckt haben, haben sie mich fast vom Himmel geschossen.\n\nIhr seht aus, als wärt auch Ihr ein Meister der Lüfte. Würdet Ihr für mich nach Südwesten fliegen und herausfinden, was sie da ausgegraben haben?", sourceObjective = "Untersucht den mittleren Bereich im hinteren Teil des Tors der Meister.", completion = "Ein Tor?! Sie haben ein Tor der Titanen ausgegraben.\n\nDas ist äußerst interessant und möglicherweise sehr gefährlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[27009] = { id = 27009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kältebringer", description = "Amnennar der Kältebringer regiert die Hügel der Klingenhauer mit dunkelster und mächtiger Geißelmagie. Es ist mir gelungen, eine Öffnung in die Dornen oberhalb seines Machtsitzes zu schlagen, aber seine Zauberkraft verwehrt es mir, einen Angriff zu starten.\n\nWenn Ihr die Dornenspirale hinaufgeht und ihn angreift, wird ihn das ablenken, bis ich ihn angreifen und schwächen kann, damit er seine tödlichen Zauber nicht wirken kann. Wenn er erst geschwächt ist, tötet ihn, ohne Gnade zu zeigen.", sourceObjective = "Tötet Amnennar den Kältebringer.", completion = "Das war gute Arbeit, {name}. Die Stacheleber hier können nicht gerettet werden, aber wenigstens sind sie nicht mehr zum Angriff aufgestellt und sind nicht länger Sklaven unter Amnennars tyrannischer Herrschaft.\n\nBitte geht schnell. Die Hügel der Klingenhauer sind ohne Hoffnung. Sie müssen gereinigt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27010] = { id = 27010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untertauchen im Quecksilber", description = "Die Troggs in Tiefenheim sind genauso feindselig wie die in Azeroth. Dennoch, ihre Anwesenheit könnte für unsere Bemühungen von Vorteil sein.\n\nDie Kisten, die sie benutzen, um in dem Quecksilber herumzufischen, können Euch perfekt tarnen, wenn Ihr in den Marschen auf Tauchstation geht.\n\nBenutzt sie, um das Lager des Schattenhammers am östlichen Ende der Oberen Silbermarschen unentdeckt zu erreichen.", sourceObjective = "Verschafft Euch eine Troggkiste und versteckt Euch darunter. Dann belauscht das Lager des Schattenhammers im Osten.", completion = "Wir haben die benötigten Informationen. Wir sollten uns nicht verraten, indem wir den Feind zu früh angreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27011] = { id = 27011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rotkieferdiebstahl", description = "Weiter im Süden findet Ihr Gnolle der Rotkiefer...Neuankömmlinge in diesem Gebiet. Ihr seid wahrscheinlich auf dem Weg hierher an ihnen vorbeigekommen. Nathaniel tut so, als ob sie kein Problem darstellen, aber ich weiß es besser.\n\nIch habe gesehen, wie sie nachts mit unserem Holz weggerannt sind. Ich weiß gar nicht, was sie mit dem Holz vorhaben - sie scheinen keine guten Handwerker zu sein - aber das hält sie nicht davon ab, es zu stehlen. Geht hinunter zu ihren Lagern und stehlt das Holz zurück.", sourceObjective = "Holt aus dem Rotkieferlager in den Westlichen Pestländern 10 Stapel Nordkammholz zurück.", progress = "Einige der älteren Holzfäller erzählen, dass die Rotkiefer vor einigen Jahren hier gelebt haben. Doch als die Seuche ausbrach, sind sie fortgegangen. Trotzdem gibt ihnen das nicht das Recht, zu stehlen.", completion = "Ich bringe das nur eben zurück in die Holzlager draußen. Nathaniel wird wahrscheinlich nicht einmal bemerken, dass es gefehlt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[27012] = { id = 27012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lösung des Gnollproblems", description = "Ich habe so meine Zweifel, was die Absichten dieser Gnolle angeht. Bisher haben sie uns noch nicht angegriffen, aber es werden immer mehr und sie scheinen immer ihre Waffen im Anschlag zu haben. Ich bin kein Militärexperte, aber das erscheint mir ein wenig aggressiv.\n\nWenn wir ihnen einige ihrer Waffen wegnehmen, werden sie vielleicht nicht zur Bedrohung für unser Sägewerk. Ich würde mich viel besser fühlen, wenn Ihr dort hinunter geht und einige ihrer Waffen zu mir bringt.", sourceObjective = "Beschafft 6 Rotkieferstäbe und 6 Rotkieferkeulen von den Gnollen der Rotkiefer.", progress = "Ich will nicht allein wegen einer besorgten Mutter eine Art Massenmord an Gnollen befehlen. Ich möchte mich nur in meinem Zuhause sicher fühlen.", completion = "Danke, {name}. Ich werde die jetzt ins Feuer werfen. Schließlich wollen wir nicht, dass die Gnolle sich hineinschleichen und sie erneut stehlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27013] = { id = 27013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu knapp für meinen Geschmack", description = "Ich freue mich für Nathaniel. Er versucht schon so lange, wieder nach Nordkamm zurückzukehren. Jetzt, da der Scharlachrote Kreuzzug ihm nicht mehr im Weg steht, kann er endlich nach Hause. Nur ... Auch, wenn die Umgebung hier idyllisch zu sein scheint, ist sie nicht der beste Ort, um eine Familie aufzuziehen.\n\nZum Beispiel: Am Rande dieses Tals findet man tollwütige Füchse, die nach unschuldiger Beute suchen. Hin und wieder erhasche ich einen Blick auf einen von ihnen, der mich direkt anschaut.\n\nBitte, {class}, erlegt einige dieser Füchse. Ich fühle mich in ihrer Nähe nicht sicher.", sourceObjective = "Tötet in den Westlichen Pestländern nahe dem Sägewerk des Nordkamms 12 tollwütige Füchse.", completion = "Jetzt bin ich etwas erleichtert, {name}. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[27014] = { id = 27014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheiligte Notiz", description = "Gerade war ein Bote hier und hat Euch gesucht, {name}. Ich glaube, er wurde von der Priesterlehrerin Seherin Rabenfeder geschickt. Wenn diese Nachricht von der Seherin ist, würde ich sie sofort aufsuchen.", sourceObjective = "Sprecht im Camp Narache mit Seherin Rabenfeder.", sourceObjectiveStatus = "unverified-source-field" }
quests[27015] = { id = 27015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geweihte Notiz", description = "Gerade war ein Bote hier und hat Euch gesucht, {name}. Ich glaube, er wurde von dem Paladinlehrer Sonnenwandler Helaku geschickt. Wenn diese Nachricht von dem Sonnenwandler ist, würde ich ihn sofort aufsuchen.", sourceObjective = "Sprecht im Camp Narache mit Sonnenwandler Helaku.", progress = "Sehr erfreut, Euch kennenzulernen, {name}.", completion = "Es gibt viel zu tun. Im Laufe der Zeit werden Euch die Gepflogenheiten der Sonnenwandler in Fleisch und Blut übergehen, ebenso wie die Unterhaltungen der Schamanen mit den Elementen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27016] = { id = 27016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Freuden der Eberjagd", description = "Versucht, Eure Aufregung zu zügeln, {name}, denn Ihr befindet Euch in der Gesellschaft des besten Eberjägers in Azeroth!\n\nIhre Durchtriebenheit, ihre rasende Geschwindigkeit, die extreme Stärke und die widerstandfähigen Bälger... ja, Eber sind nur die Beute der meisterlichsten Jäger. Anfänger brauchen sich gar nicht erst bewerben!\n\nIch wette, Ihr habt noch nie so ein exotisches Tier gejagt. Ich halte jede Wette, dass Ihr meinen Rekord von zehn getöteten Ebern nicht einstellen könnt. Versucht es mit denen an der Ostseite des Loch, aber tut Euch nicht weh, Grünschnabel!", sourceObjective = "Tötet 10 Schlammbaucheber.", completion = "Ihr habt bereits zehn getötet? H...hah! Während Ihr unterwegs wart, habe ich meinen bisherigen Rekord gebrochen! Jetzt steht er auf zehn...hundert! Ja, zehnhundert Eber!\n\nEine Wette ist eine Wette...hier ist Euer Trostpreis, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27017] = { id = 27017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erinnerungen an längst vergangene Zeiten", description = "Schon komisch, an was man sich so erinnert. Ich habe 16 Stunden am Tag auf den Feldern gearbeitet und an jedem siebten Tag bin ich in das geschäftige Andorhal gegangen, um das, was ich angebaut hatte, zu verkaufen. Es war ein hartes Leben, aber wir kamen zurecht.\n\nDoch ich erinnere mich kaum daran. Wenn ich an die Zeit zurückdenke, fällt mir Glorias Lächeln ein - oder wie Andrea mir aus dem Fenster zugewinkt hat, wenn ich von dem Pflug aufsah.\n\nDer Hof ist etwas östlich von hier, aber ich bin nicht sicher, ob ich schon bereit bin, dorthin zurückzukehren, {name}. Ich möchte nur diese Erinnerungen nicht verlieren.", sourceObjective = "Begebt Euch zum Hof in Gahrrons Trauerfeld und sammelt alle Erinnerungsstücke, die Ihr finden könnt.", progress = "Ich möchte Euch nicht mit den Launen eines nostalgischen alten Mannes belästigen, {name}, aber solltet Ihr in der Gegend sein...", completion = "Dies... Gloria hat jeden Abend aus diesem Gebetsbuch gelesen! Wie konnte ich das nur vergessen? Sie war so fromm, {name}.\n\n\n\nOh...\n\nDieses Bild... meine Tochter, Andrea... sie hat so gerne gemalt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27019] = { id = 27019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißel der Hügel", description = "Phantastisch! Mein Name ist Belnistrasz und ich danke Euch für meine Rettung. Ich hatte mich schon tot gewähnt... oder schlimmer, als Mahlzeit für dieses von der Geißel befallene Gezücht.\n\nHört mir zu... anstatt einfach wegzulaufen, möchte ich doch uns allen zuliebe versuchen, etwas zu ändern. Könntet Ihr mir dabei helfen? Es ist wahrscheinlich gefährlich, aber irgendjemand muss es ja tun und ich bezweifle ernsthaft, dass noch andere Abenteurer ihren Weg an diesen hoffnungslosen Ort finden werden.", sourceObjective = "Wenn Ihr Belnistrasz helfen wollt, sprecht noch einmal mit ihm und übergebt ihm den Schwurstein, den er Euch gab.", progress = "Ich schere mich nicht um Politik; mich interessiert nicht, ob Ihr Euch auf die Seite der Horde oder der Allianz schlagt. Ich bin eher daran interessiert, direkte und schreckliche Drohungen gegen alle Völker auszuschalten... und das hier ist eine ziemlich große.\n\nWenn Ihr willens seid, für alle Völker ein wahrer Held zu sein, dann übergebt mir den Schwurstein, den ich Euch gab, als Zeichen der Verpflichtung. Ich bin... nicht aus dieser Gegend, ein Schwurstein bedeutet für Leute wie mich ein Bund der Übereinkunft.", completion = "Phantastisch, ich dachte schon, dass Ihr heldenmutig ausseht! Ich will Euch nicht anlügen, {name}, wir haben eine Menge Arbeit vor uns. Wenn wir uns auf die vor uns liegende Aufgabe konzentrieren, sollten wir in der Lage sein, als Sieger aus der Sache hervorzugehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27020] = { id = 27020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die erste Lektion", description = "Bis jetzt habt Ihr Euch wacker geschlagen. Je weiter Euer Weg Euch führt, desto stärker werdet Ihr. Ihr erlernt dann Techniken, von denen Ihr zuvor nicht einmal zu träumen gewagt habt.\n\nEure erste Lektion wird die Macht der Erfahrung sein. Geht, erlernt eine neue Fähigkeit und führt sie mir dann vor.", sourceObjective = "Erreicht Stufe 3 und erlernt Sturmangriff. Findet eine Trainingsattrappe in Camp Narache und übt diese Fähigkeit.", completion = "Ihr habt Eure Sache gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27021] = { id = 27021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Jägers", description = "Es ist Zeit für Eure erste Lehrstunde, {name}. Vor Euch liegt noch ein langer Weg, bis Ihr die Gebräuche der Jäger beherrscht, aber jede neue Fähigkeit ist ein weiterer Schritt auf diesem Weg.\n\nGeht, sammelt mehr Erfahrung und erlernt eine neue Fähigkeit. Probiert sie dann an einer Trainingsattrappe hier.", sourceObjective = "Erreicht Stufe 3, um 'Zuverlässiger Schuss' zu erlernen. Findet eine Trainingsattrappe in Camp Narache und übt fünfmal 'Zuverlässiger Schuss'.", completion = "Ihr habt Eure Sache gut gemacht,{name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27022] = { id = 27022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausschalten des Götzen", description = "In der Nähe des Eingangs befindet sich ein Götze, der als makabrer Ofen für die Stacheleber fungiert; sie... sie verzehren buchstäblich die aus dem Brachland Entführten. Ich kann den Götzen außer Funktion setzen und ihn unbrauchbar machen, aber ich benötige dabei Eure Hilfe. Mein Plan: Begleitet mich zum Götzen. Wenn wir dort angekommen sind, werde ich das Ritual einleiten. Ich werde kaum in der Lage sein, mit Euch zu kommunizieren, geschweige denn, mich zu verteidigen. Schützt mich, während ich den Götzen außer Funktion setze. \n\nSteht Ihr mir bei? Kann ich auf Eure Hilfe zählen, um diesen Gräßlichkeiten ein Ende zu bereiten?", sourceObjective = "Beschützt Belnistrasz.", completion = "Belnistrasz' plötzlicher Abgang hat eine brennende Kohlenpfanne hinterlassen. Während Ihr in die Flammen starrt, erfüllt das Bild eines roten Großdrachen mit riesigen Flügeln Euren Geist. Eine rauere Version von Belnistrasz' Stimme spricht direkt zu Euch.\n\n\"Wahrlich, sterbliche Wesen, Ihr seid die Helden, die ich mir erhofft hatte. Dank Euch gehören die Schlächtereien, die diese Bestien begangen haben, der Vergangenheit an. Mein Glaube an Wesen wie Euch ist wieder einmal erneuert worden. Nehmt dies als Belohnung, die eines Helden würdig ist.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[27023] = { id = 27023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Sonnenwandlers", description = "Es ist immer ein Vergnügen, einen anderen Sonnenwandler zu treffen. Von uns gibt es nicht so viele wie von den älteren Orden, aber unsere Wege sind nicht weniger mächtig und unsere Mitglieder werden nicht weniger respektiert.\n\nWährend Eurer Reise werdet Ihr dem Licht näher kommen und Fähigkeiten erlernen, die Ihr Euch bisher nicht ausmalen konntet.\n\nGeht, sammelt mehr Erfahrung und kehrt zurück, wenn Ihr eine neue Fähigkeit beherrscht und demonstriert sie mir.", sourceObjective = "Erreicht Stufe 3, um 'Siegel des Befehls' zu erlernen. Findet eine Trainingsattrappe in Camp Narache und übt die Anwendung von 'Siegel des Befehls'.", completion = "Ich bin stolz auf Euch, {name}. Ihr werdet einen guten Sonnenwandler abgeben. Kehrt zu mir zurück, wenn Ihr weitere Ausbildung wünscht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27024] = { id = 27024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Komplizen", description = "Obwohl Amnennar hier die größte Bedrohung darstellt, ist er beileibe nicht die einzige. Ihr müsst auch seine Leutnants erschlagen, wenn ihre Umklammerung der Niederungen aufhören soll.\n\nNimmersatt bewacht den Anfang der Dornenspirale.\n\nMordesh steht oben auf dem Knochenhaufen und wiegelt die Geißel zu blinder Wut auf.\n\nTuten'kash befindet sich unter der Erde. Um ihn herauszulocken, müsst Ihr den Gong in der Kammer des Rufers drei Mal schlagen.\n\nViel Glück, tapferer Held.", sourceObjective = "Tötet, Nimmersatt, Mordresh Feuerauge und Tuten'kash.", completion = "Gut gemacht! Ohne ihre Anführer ist die Geißel keine nennenswerte Bedrohung mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[27025] = { id = 27025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disteln im Dickicht", description = "Es ist die Jahreszeit der Dolchdisteln! Dolchdistelsamen sind für 89% der durch Samen verursachten Verletzungen bei Jägern verantwortlich.\n\nIhr werdet Dolchdistelsamen zum größten Teil in den unteren Waldländern nördlich der Jagdhütte finden. Man findet sie gewöhnlich auf dem Boden bei Bäumen und sie werden Euch stechen und Schmerzen zufügen.\n\nIch würde Euch ja den Rat geben, einen Bogen um sie zu machen, aber ich brauche jemanden, der mir hilft, sie aus Sicherheitsgründen zu entfernen. Bringt mir Dolchdistelsamen, damit andere sich nicht verletzen.", sourceObjective = "Sammelt 6 Dolchdistelsamen.", progress = "Ihr müsst sie mit größter Vorsicht behandeln!", completion = "Ich habe gehört, dass es für die Waldländer auch eine Bärenwarnung gibt. Bären lieben diese Dolchdistelsamen.\n\nGut, dass Ihr sie gesammelt habt, damit sie nicht noch mehr Bären anziehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27026] = { id = 27026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alarmstufe: Rotluchs", description = "Lasst alles stehen und liegen! Es ist mir zu Ohren gekommen, dass in der Nähe der Jagdhütte Rotluchse gesehen wurden. Rotluchse!\n\nIch habe zwar noch nie einen Rotluchs gesehen, aber sie sind bestimmt gefährlich. Sie sind wie Berglöwen oder so ähnlich. Ich will nicht, dass jemand fortgeht, bevor die Gegend nicht gesichert ist.\n\nAußer Euch, heißt das. Ich werde Euch dafür bezahlen, die Gegend zu sichern, {class}. Aber lasst Euch nicht in Stücke reißen.", sourceObjective = "Tötet 8 Rotluchse.", completion = "Also gut, ja, man hat mich informiert, dass die Rotluchse viel kleiner sind, als zunächst angenommen. Aber für Gnome ist das immer noch ganz schön gefährlich!\n\nIhr habt Euch um die Sicherheit diese Hütte verdient gemacht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[27027] = { id = 27027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urtümlicher Schlag", description = "Ich weiß, dass Ihr geholfen habt, Camp Narache vor den Borstennacken zu beschützen. Wir werden jeden Hammer und alles Glück, das wir bekommen können, brauchen.\n\nWährend Ihre Eure Fertigkeiten verbessert, werdet Ihr auch die Verbindung zu den Elementen vertiefen. Dadurch erhaltet Ihr Zugang zu neuen Fähigkeiten.\n\nDie erste, die Ihr erlernen werdet, nennen wir 'Urtümlicher Schlag'. Diese Fähigkeit sollte Euch dabei helfen, Eure Feinde schneller zu schlagen. Erlernt sie und probiert sie dann aus.", sourceObjective = "Erreicht Stufe 3, um 'Urtümlicher Schlag' zu erlernen. Findet eine Trainingsattrappe in Camp Narache und übt daran dreimal die Anwendung von 'Urtümlicher Schlag'.", completion = "Gut gemacht, {name}. Wie ich sehe, werdet Ihr keine Probleme haben, auch unsere fortgeschrittenen Künste zu meistern, wenn Ihr an Erfahrung gewinnt. Kehrt zu mir zurück, wenn Ihr weitere Ausbildung benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27028] = { id = 27028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hornissenjagd", description = "Wir suchen hier immer nach neuem Wild. Daryl mag seine Eber ja lieben, aber der Rest von uns bevorzugt etwas exotischere Dinge.\n\nNun, ich würde niemals behaupten, dass es gut war, den Loch trockenzulegen, aber es gab einen Lichtblick. Der sumpfige Untergrund hat neue Beute hervorgebracht: Hornissen!\n\nUnd obendrein noch riesige Hornissen. Nicht viele Jäger haben sich mit so riesigen Insekten gemessen. Das ist ziemlich neu.\n\nIch möchte gerne, dass Ihr es versucht - ich biete Euch eine Wette an. Bringt mir einige dieser wunderschön glänzenden Flügeln von ihnen und ich bezahle Euch.", sourceObjective = "Erbeutet 6 glasige Hornissenflügel.", progress = "Wie geht's mit den Hornissen?", completion = "Wunderbare Exemplare habt Ihr da! Hier ist mein Einsatz, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[27029] = { id = 27029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geißel heilen", description = "Viel wirksamer, als eine Welle der Geißel nach der anderen zu töten, wäre es, einen Weg zu finden, wie man lebende Kreaturen davor bewahrt, sich in sie zu verwandeln. Ich habe eine Idee für ein tolles Pulver. Wenn man es einatmet, könnte es den ganzen Prozess unterbinden.\n\nIch benötige verwitterte Hauer von den untoten Stachelebern hier, um dieses Pulver herzustellen. Bringt mir eine ausreichende Menge und wir sind vielleicht in der Lage, das Wachstum der Geißel endgültig aufzuhalten.", sourceObjective = "Besorgt 20 verwitterte Hauer.", progress = "Habt Ihr die Hauer?", completion = "Ich bin davon überzeugt, dass diese Substanz uns in Zukunft weitere Kopfschmerzen ersparen wird. Danke, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27030] = { id = 27030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Handvoll Fuchsschwänze", description = "Wir haben in letzter Zeit mehr Füchse hier in den Hügeln gesehen. Sie sind gerissene Wesen. Sie sind ein guter Test für die Fähigkeiten eines Jägers - und sie bringen einen schönen Profit!\n\nWegen ihrer Schwänze, <mein Freund/meine Liebe>. Die sind schön und buschig - man kann sie an seinen Gürtel hängen, um Flöhe abzuwehren, oder man kann mit ihnen die Handschuhe eines modebewussten Edelmannes füttern.\n\nAber ich plappere nur daher. Ich bin zwar kein Goblin und die Spannung liegt in der Jagd. Doch wenn Ihr mir ein paar Fuchsschwänze bringt, werde ich Euch gerne dafür bezahlen. Ihr findet die Füchse nördlich der Jagdhütte in den unteren Waldländern.", sourceObjective = "Erbeutet 7 flauschige Fuchsschwänze.", progress = "Was habt Ihr für mich?", completion = "Ahh, seht Ihr? Waren der feinsten Qualität. Das habt Ihr gut gemacht, die zu besorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27031] = { id = 27031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrückt nach Flügeln", description = "Ich habe die Nase von Gyrokoptern voll. Klar, sie erfüllen ihren Zweck, aber seit wann hat das einem Gnom jemals gereicht? Ich will richtig fliegen, mit FLÜGELN!\n\nIch beobachte seit Jahren Vögel und versuche, hinter das Geheimnis zu kommen, wie man eine Maschine baut, die genau wie sie fliegen kann. Dieses elegante Aufschwingen und Herabstoßen, der Wind, der über die Flügel streicht ... ahh.\n\nIhr! Ihr könnt mir helfen. Ich brauchte die besten Flugfedern, die ihr auftreiben könnt. Die goldenen Adler, die in der Nähe der Jagdhütte kreisen, wären eine ausgezeichnete Wahl.", sourceObjective = "Besorgt 3 makellose Flugfedern von Goldadlern.", progress = "Die besten Federn sind gerade gut genug!", completion = "Wunderschön. Ihr habt einen Blick für Qualität!\n\nWir sind auf der gleichen Wellenlänge! Offensichtlich könnt Ihr Euch für Flügel und Federvieh begeistern, also könntet Ihr mir noch weiter helfen...", sourceObjectiveStatus = "unverified-source-field" }
quests[27032] = { id = 27032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein schräger Vogel", description = "Ich habe die Maschine meiner Träume fast perfektioniert: den Himmelsschreiter! Der weltweit erste fliegende Roboschreiter! Aber, nun ja...\n\nAls ich in meinem geheimen Höhlenlabor die letzten Handgriffe daran machte, wurden meine anderen Kreationen... nun ja... eifersüchtig. Den mechanischen Vögeln überhaupt erst eine Persönlichkeit zu verleihen, war wohl keine gute Idee, aber das ist nun so.\n\nIch brauche das supermechanische Robodings aus dem ursprünglichen Himmelsschreiter, wenn ich ihn wieder aufbauen will! Bitte, begebt Euch in die Höhle und holt es für mich zurück!", sourceObjective = "Findet den verrosteten Himmelsschreiter in der Eisenschwingenhöhle.", completion = "<Der Himmelsschreiter sitzt schweigend da, seine Chance, davonzufliegen, ist vertan. Eine auffällige Klappe an seiner Vorderseite trägt die Aufschrift \"SRD\".>", sourceObjectiveStatus = "unverified-source-field" }
quests[27033] = { id = 27033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz der Himmelsstreiter", description = "Ihr öffnet die Klappe und findet ein beeindruckendes, mechanisches Gerät, das an einige Kabel, Zahnräder und wer-weiß-was noch angeschlossen ist.\n\nEs lässt sich ohne Schwierigkeiten lösen. Zeit, es zu Bingles zurückzubringen.", sourceObjective = "Bringt Bingles Blastenheimer in der Jagdhütte der Weltenwanderer das supermechanische Robodings.", completion = "Perfekt! Jetzt habe ich die perfekte Flügelbalance und habe alle Teile, die ich benötige. Alles, was noch fehlt, ist ein Pilot.", sourceObjectiveStatus = "unverified-source-field" }
quests[27034] = { id = 27034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er ist in dem Alter", description = "ich baue den Himmelsschreiter nicht für mich, {name}. Ich baue ihn nicht mal für die Gnomwelt. Ich möchte, dass mein Sohn derjenige ist, der ihn fliegt.\n\nIch bin alt und meine Reflexe sind nicht mehr das, was sie mal waren. Aber mein Junge Ando könnte der beste Pilot werden, den Azeroth je gesehen hat, wenn er nur seine Teenager-Launenhaftigkeit ablegen würde!\n\nEr sitzt draußen am See und starrt den ganzen Tag den Himmel an. Irgendetwas bedrückt ihn, aber er weigert sich, mit seinem Vater darüber zu sprechen. Ich bin mit meinem Latein am Ende!\n\nBitte, {name}, könntet Ihr nicht mit ihm reden? Sagt ihm, ich brauche ihn, um den Himmelsschreiter zu fliegen.", sourceObjective = "Sprecht mit Ando Blastenheimer auf der Ostseite des Loch.", completion = "Mein Vater und seine albernen Erfindungen sind mir egal! Das ist alles nur Unsinn!", sourceObjectiveStatus = "unverified-source-field" }
quests[27035] = { id = 27035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stellung beziehen", description = "Schaut sie Euch an. Der Schattenhammer hat dieses Land ruiniert!\n\nDieser Kult hat diesen Kataklysmus ausgelöst, den Steinwerkdamm zerstört und den ganzen Loch trockengelegt. Und jetzt laufen sie in den Trümmern herum, als ob hier ihr Zuhause wäre!\n\nWenn es in dieser Welt Gerechtigkeit gäbe, würde jemand in ihr Lager marschieren und ihr Artefakt in Stücke brechen. Aber ich bin zu schwach, um auch nur an einen Versuch zu denken.\n\nUnd niemand hat genug Mut dazu! Nicht einmal Ihr! Seht Ihr? Es ist alles so sinnlos...", sourceObjective = "Zerstört den Zwielichtumweltgestalter in der Mitte des Schattenhammerlagers.", completion = "Ihr habt es getan! Ihr habt es wirklich getan! Ihr habt gegen sie gekämpft und gewonnen!\n\nEs besteht doch noch Hoffnung...", sourceObjectiveStatus = "unverified-source-field" }
quests[27036] = { id = 27036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vyrins Rache", description = "Ihr seid nicht zufällig daran interessiert, es unserem ach so kühnen Kühnen ein wenig heimzuzahlen? Es schmerzt mich, das zu sagen, aber Daryl hat ein gewisses Talent.\n\nVor einem Jahr war ein großer Bär das Ziel der Jagdhütte der Weltenwanderer, aber keiner der Jäger hatte Glück mit ihm. Also dachte sich Daryl, er könnte sich mal an ihm versuchen. Das Einzige, was er nach seinem Versuch vorweisen konnte, war die hässliche Narbe über seinem Auge.\n\nErlegt den Bären und ich bin mir sicher, dass sogar Daryl mal sprachlos wäre.\n\nAlte Rußtatze, der Bär, hält sich irgendwo in der Nähe seines Baus nördlich von hier auf.", sourceObjective = "Tötet alte Rußtatze und bringt seinen Kopf an Euch.", progress = "Ah, {name}! Schon wieder hier? Zweifelsohne wart Ihr wieder auf der Jagd! Keine Sorge, es ist nicht schlimm, wenn Ihr ein paar Rückschläge einstecken müsst, davon werdet Ihr auf lange Sicht nur besser.\n\n... viel schlechter könntet Ihr ja sowieso nicht mehr werden...", completion = "Äh... was ist das da? Ein Bärenschädel, wie es aussieht.\n\n<Er fährt unbewusst mit einem Finger an seiner Narbe entlang>\n\nNun, das ist eine ziemlich interessante Beute, die Ihr da habt. Kann eigentlich nicht der Bär von damals sein...\n\n<Seine Stimme verliert sich, und er fängt sichtbar an zu zittern.>\n\nOh, nehmt das weg, nehmt es weg! Schafft dieses grausige Ding hier raus!", sourceObjectiveStatus = "unverified-source-field" }
quests[27037] = { id = 27037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vyrins Rache", description = "Licht! Bringt solche Dinge nicht in die Jagdhütte... das ist unhygienisch, unaussprechlich, un... un... unhygienisch!\n\nBringt es bitte einfach nur raus hier, ja? Niemand will Eure kleine blutige Trophäe sehen, aber wirklich nicht!", sourceObjective = "Bringt den Kopf der alten Rußtatzes zu Vyrin Flinkwind in die Jagdhütte der Weltenwanderer.", progress = "Sehr gute Arbeit, {name}! Wir haben's ihm wirklich gezeigt! Hier, gebt mir den Kopf, ich werde mich darum kümmern.", completion = "Danke für Eure Hilfe bei meinem kleinen Plan, {name}. Seit Monaten wollte ich es diesem hochnäsigen, eingebildeten Jungen schon heimzahlen und ich würde meinen, es hat so richtig gut geklappt! Hier, nehmt das, Ihr habt es Euch verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[27038] = { id = 27038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fehlende Teile", description = "<Der Unteroffizier wendet seine Aufmerksamkeit Euch zu.>\n\nHört zu, wenn Ihr helfen wollt, dass alles hier etwas schneller geht, dann haltet mir Flintlocke vom Leib. Eine ganze Ladung Belagerungsmaschinenteile ist verlegt worden und jetzt über das ganze Dock verteilt.\n\nSammelt die fehlenden Teile auf und bringt sie zu Flintlocke, damit er den Bau beenden kann. Er ist auf der anderen Seite der Straße und wartet.", sourceObjective = "Hebt 5 fehlende Teile im Hafen von Sturmwind auf.", progress = "Wat is'?\n\nMeine Teile. Wo sind sie? Man kann keinen Panzer ohne Teile bauen!\n\nUnd wenn, wäre er zu klein. Un' ziemlich inner-fektiv.", completion = "<Flintlocke wühlt gierig durch die Maschinenteile und wirft einige ausgewählte Stücke über die Schulter.>\n\nJau, hier is' das Zeugs ja. <Er steckt seinen Kopf tief in eine der Kisten.>\n\nAber wo ist mein Pulver? Alles ist hier, nur nicht das Pulver. Ich brauche Sprengstoff, Mann!\n\nSagt dem König: Keine Macht, wenn's nicht kracht. Ich brauch' 'n paar Kabummplosionen, sonst verlass ich den Hafen nich'.", sourceObjectiveStatus = "unverified-source-field" }
quests[27039] = { id = 27039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter Feinden", description = "Wisst Ihr, warum Mortuus 'nub' an Euren Namen anhängt, {name}? Weil er ein inkompetenter Kriecher ist, der kaum aus seinem übergroßen Helm hervorschauen kann. 'NUB' ist Eure Bezeichnung. Ihr seid jetzt nämlich Teil des NEUEN UNTERSTÄDTER BATAILLONS.\n\nDoch genug der Witze! Ich habe Todespirscherin Yorick vor zwei Tagen auf eine Überwachungsmission geschickt. Ihr Ziel war es, Informationen über die Gilnearische Befreiungsfront zu sammeln und zurückzukehren. Jetzt habe ich schon drei Tage lang nichts mehr von ihr gehört.\n\nGeht nach Südwesten zum Ivarfeld und sucht nach Yorick, {name}.", sourceObjective = "Findet Todespirscherin Yorick auf dem Ivarfeld im Silberwald.", completion = "Belmont wird ein bisschen nervös und schon schickt er irgendeinen Grünschnabel, um nach mir zu suchen? Hört zu, ich habe das Ivarhaus aus diesem Plumpsklo heraus drei Tage lang observiert. Eure Anwesenheit gefährdet die gesamte verdammte Mission!\n\nIch habe keine Zeit für Erklärungen. Wir müssen jetzt handeln. Sonst war alles umsonst.", sourceObjectiveStatus = "unverified-source-field" }
quests[27040] = { id = 27040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entschlüsselung leichtgemacht", description = "Wir haben nicht die Werkzeuge, um diese chiffrierten Pläne zu entschlüsseln. Doch der Schattenhammer hat sie.\n\nWärt Ihr so gut, mit den Plänen dort hinaufzugehen und sie durch die Einweg-Dechiffrierungsmaschine laufen zu lassen?", sourceObjective = "Entschlüsselt 6 Pläne.", sourceObjectiveStatus = "unverified-source-field" }
quests[27041] = { id = 27041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entschlüsselung leichtgemacht", description = "Wir haben nicht die Werkzeuge, um diese chiffrierten Pläne zu entschlüsseln. Doch der Schattenhammer hat sie.\n\nWärt Ihr so gut, mit den Plänen dort hinaufzugehen und sie durch die Einweg-Dechiffrierungsmaschine laufen zu lassen?", sourceObjective = "Entschlüsselt 6 Pläne.", sourceObjectiveStatus = "unverified-source-field" }
quests[27042] = { id = 27042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mächte des Feuers, des Wassers und der Luft", description = "Habt Ihr da oben diesen plappernden Idioten gehört? Das ist kein Geringerer als Haethen Kaul, ihr Anführer.\n\nDie Macht hat ihn in den Wahnsinn getrieben. Er entzieht sie den gebundenen Elementaren, was ihn nahezu unbesiegbar macht.\n\nDie einzige Chance, wie Ihr ihn im Kampf besiegen könnt, besteht darin, die Elementare zu töten und jeweils ihren Zauberschutz erlangen. Das sollte Euch vor Haethens Magie beschützen.\n\nNun, zumindest vor einem Großteil davon.", sourceObjective = "Erhaltet den Feuerzauberschutz, Wasserzauberschutz und Windzauberschutz und tötet dann Haethen Kaul.", progress = "Ihr müsst Euch schon mehr anstrengen, Kumpel!\n\nUnd jetzt hoch da mit Euch und erledigt Eure Aufgabe. Oder muss ich es selbst tun?", completion = "Das nenne ich Kampfgeist! Ein Übel weniger in dieser Welt, vor dem die Kleinen sich fürchten müssen, wenn sie abends ins Bett gehen.\n\nUnd wir müssen uns auch keine Sorgen mehr um ihn machen!\n\nNun, dann lasst mich mal nachsehen. Irgendwo in unseren Kisten haben wir sicher eine passende Belohnung für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[27043] = { id = 27043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mächte des Feuers, des Wassers und der Luft", description = "Habt Ihr da oben den Mann und sein unaufhörliches Geschrei gehört? Das ist Haethen Kaul, ihr Anführer.\n\nEs ist kein Geheimnis, dass die Macht, die er den gebundenen Elementaren entzieht, ihn in den Wahnsinn getrieben hat. Leider macht sie ihn auch nahezu unbesiegbar.\n\nWenn Ihr gegen ihn kämpfen wollt, müsst Ihr erst die Elementare töten und jeweils ihren Zauberschutz erlangen. Das sollte Euch vor Haethens Magie beschützen.\n\nNun, zumindest vor einem Großteil davon.", sourceObjective = "Erhaltet den Feuerzauberschutz, Wasserzauberschutz und Windzauberschutz und tötet dann Haethen Kaul.", completion = "Eine beeindruckende Vorstellung Eures Kampfgeschicks, {class}.\n\n\n\nIch glaube, dass Ihr Euch eine Belohnung verdient habt. Etwas, das einem mächtigen Mann wie Euch angemessen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27044] = { id = 27044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sorgen der Bauern", description = "Ich möchte noch nicht zur Burg zurückkehren. Würdet Ihr mir bei etwas helfen?\n\nEinige der hiesigen Bauern haben vor Kurzem beim König eine Eingabe gemacht, bei der es um vermisstes Nutzvieh ging. Mein Vater hat versprochen, dass jemand der Sache nachgeht, aber die Stadtwache ist so ausgelastet, dass das Wochen dauern würde.\n\nIch dachte, ich könnte doch helfen! Es wird den Bauern Mut machen, wenn sie sehen, dass jemand sich darum kümmert, besonders, wenn es jemand der königlichen Familie ist. Außerdem geht es ja nur um paar vermisste Kühe. Nichts Gefährliches.\n\nBringt mich hier in der Stadt zu Bauer Wollerton!", sourceObjective = "Begleitet Prinz Anduin zu Bauer Wollerton auf Wollertons Bauernhof in Sturmwind. Wenn er nicht mehr an Eurer Seite ist, findet Ihr ihn in Burg Sturmwind.", progress = "Äh, ja?", completion = "<Als er den Prinzregenten sieht, fällt Bauer Wollerton ungeschickt auf ein Knie.>\n\nEu - Eu - Eure Hoheit!", sourceObjectiveStatus = "unverified-source-field" }
quests[27045] = { id = 27045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lauschangriff", description = "Der Anführer der Gilnearischen Befreiungsfront, Darius Crowley, hält jetzt schon seit drei Tagen ein Treffen mit einem anderen Worgen in diesem Landhaus ab. Ich bin mir nicht sicher, was da los ist, aber wir müssen in das Haus gelangen und einen guten Platz finden, von dem aus wir sie belauschen können.\n\nJetzt oder nie, {race}. Eine zweite Chance werden wir wohl kaum bekommen.\n\nAber falls ich es nicht schaffe, müsst Ihr mir versprechen, zur Kommandozentrale der Verlassenen zurückzukehren und Belmont von unseren Erkenntnissen zu berichten.", sourceObjective = "Betretet das Landhaus auf dem Ivarfeld und sucht oben nach einem geeigneten Versteck. Belauscht dann Lord Darius Crowley.", completion = "Oh je, arme Yorick! Ich kannte sie gut, {name}. Eine Assassine mit unvergleichbarem Mut…\n\nAlso, was geht dort vor sich? Was habt Yorick und Ihr herausgefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[27046] = { id = 27046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bohrende Angst", description = "Die Tunnelgräber haben den Fels befallen und fressen die ganze Zeit daran; eines Tages wird unser Heim zusammenbrechen. Für jeden, den man tötet, brechen zweimal so viele hervor und wir müssen immer weiterkämpfen. Sie müssen ausgerottet werden.\n\nGeht zu den Bruchtiefen und vernichtet alle Würmer, die Ihr finden könnt.", sourceObjective = "Tötet 10 Schleifwürmer.", completion = "Ihr führt einen Krieg, den wir nicht führen können. Danke für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[27047] = { id = 27047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Partikel", description = "Einige der seltensten Kristalle entstehen an den gefährlichsten Orten. In den Bruchtiefen werdet Ihr Painitformationen finden. Das ist viel besser als das Gold, das Eure Rassen so schätzen.\n\nDa Ihr ein fleischliches Wesen von kleinem Wuchs seid, könnt Ihr die Bruchtiefen betreten und Painitpartikel für mich holen. Würdet Ihr Euch dieser Gefahr für mich aussetzen?", sourceObjective = "Holt 10 Painitpartikel.", progress = "Painit ist für uns eins der wertvollsten Materialien, besonders weil wir die meisten Vorkommen nicht selbst erreichen können.", completion = "Gut gemacht, {race}. Die werden gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27048] = { id = 27048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untergrundwirtschaft", description = "Hey! Ich versuche, einige dieser Kristalle zu sammeln. Die Elementare zahlen gut für das Zeug... wenn Ihr mir helft, die ganzen verschiedenen Sorten zu sammeln, bekommt Ihr einen Anteil vom Gewinn.\n\nBenutzt diese Bomben, um Teile aus den größeren Kristallformationen herauszusprengen.\n\nIch hab' die dumme Angewohnheit, mit Sprengstoff ein wenig zu dick aufzutragen. Nehmt Euch vor dem Rückstoß in Acht.", sourceObjective = "Benutzt Rickets Ticker, um 3 Tiefenalabasterkristalle, 3 Tiefencoelestinkristalle, 3 Tiefenamethystkristalle und 3 Tiefengranatkristalle zu sammeln.", progress = "Bumm?", completion = "Gut gemacht!\n\nIch habe hier dieses nette kleine Geschäft laufen. Ein Haufen Trottel geht da drüben zu Therazanes Thron und gibt D'lom bergeweise Gold für allen möglichen Unsinn. Und dieses ganze Geld gibt er mir für diese Kristalle. Ich gehe steinreich nach Hause, alles für ein paar Felsbrocken.\n\nAber erzählt es keinem, ich will keine Konkurrenz.\n\nGlaubt Ihr, Ihr könntet später vorbeikommen und noch eine Ladung Kristalle bringen?", sourceObjectiveStatus = "unverified-source-field" }
quests[27049] = { id = 27049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weicher Fels", description = "Die Verderbnis der Rubinspanne hat nicht nachgelassen. Zerstört die Fungusungetüme, die unser Land mit ihrem Schmutz besudeln. Wenn sie sich weiterhin erheben, werden wir sie weiterhin vernichten.", sourceObjective = "Tötet 8 Fungusungetüme.", completion = "Wenn sie einmal anfangen zu wachsen, ist es fast unmöglich, sie wieder einzustampfen. Durch Beharrlichkeit werden wir eines Tages unser Reich säubern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27050] = { id = 27050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn der Pilze", description = "Etwas auf der Rubinspanne ruft ständig neue, widerliche Gewächse auf dem Felsen hervor. Neue Pilze wachsen und müssen zerstört werden, bevor sie sich noch weiter verbreiten.", sourceObjective = "Zerstört 10 der neu gesprossenen Pilze in der Rubinspanne.", completion = "Ihr habt viel Erfahrung, wenn es darum geht, auf Dinge zu treten. Ihr würdet einen ausgezeichneten Riesen abgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27051] = { id = 27051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beharrlichkeit zahlt sich aus", description = "Die Troggs haben sich nicht zerstreut, nachdem Ihr Glop getötet habt. Seine Diener haben den Wachstumsbeschleuniger gefunden, der zurückgelassen wurde, und säen die Samen der Verderbnis überall auf der Rubinspanne.\n\nBringt sie zur Strecke und findet alles, was vom Wunderwachstumsmittel von Verlok noch übrig ist. Es muss entsorgt werden.", sourceObjective = "Nehmt einen Beutel mit Wunderwachstumsmittel von Verlok von den Verloks auf der Rubinspanne an Euch.", progress = "Habt Ihr getan, worum ich Euch gebeten hatte? Wir müssen das Wachstumsmittel, das sie noch in Besitz haben, beseitigen.", completion = "Danke, {race}. Wir werden den Rest im Laufe der Zeit auch noch beseitigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27053] = { id = 27053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kessel von Gahrrons Trauerfeld", description = "Meine Analyse ist abgeschlossen! Die Verseuchung, die die Tiere hier befallen hat, ist keine Resterkrankung. Nein, sie ist etwas Neues... und ich glaube, ich weiß, was es ist.\n\nDer Kult der Verdammten unterhält einen Seuchenkessel auf einem Hof, der Gahrrons Trauerfeld heißt.\n\nDer Hof ist genau im Südosten von uns, kurz vor den Östlichen Pestländern. Ich brauche eine Probe von diesem Kessel, um meinen Verdacht zu bestätigen.\n\nBeseitigt den Kessellord, der dort zugegen ist, um an seinen Schlüssel zu gelangen. Dann werdet Ihr Zugang zu dem Kessel erhalten und könnt eine Probe für mich entnehmen.", sourceObjective = "Geht zu Gahrrons Trauerfeld in den Westlichen Pestländern. Findet und besiegt den dort anwesenden Kessellord und benutzt seinen Schlüssel, um Zugang zu dem Kessel zu erlangen.", progress = "Die Zugangsklappe zu dem Kessel ist fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der Schlüssel von Kessellord Rachseele löst sich auf, als er das Schloss auf der Zugangsklappe am unteren Ende der Kesselplattform berührt. Innen ist ein leises Knacken zu hören, die Zugangsklappe schwingt auf und enthüllt noch weitere, zähflüssige Gifte, die sich in dem Gefüge des Kessels befinden.\n\nDort ist ein kleiner Zapfhahn, unter den die Flasche genau passt, um eine Probe für Außenagent Kaartish in der Stätte der Heiler abzuzapfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27054] = { id = 27054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifelte Taten", description = "Der Kult der Verdammten unterhält ein kleines Lager im Osten, Malicias Außenposten. Dort trainieren sie außerhalb von Scholomance. Möglicherweise haben wir ihnen schon viel zu lange erlaubt, unkontrolliert dieses Training auszuüben.\n\nWenn Kultisten wirklich diese Seuche benutzen, um die Tierwelt zu infizieren, dann muss diese Infizierung an Malicias Außenposten stattfinden.\n\nAusbilder Malicia leitet den Außenposten. Findet sie, tötet sie und findet heraus, von wem sie ihre Befehle empfängt.", sourceObjective = "Tötet Instrukteurin Malicia und nehmt ihre Befehle für den Kult an Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[27055] = { id = 27055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krastinovs Schüler", description = "Laut der Befehle für den Kult soll Seuche aus dem Kessel bei Gahrrons Trauerfeld für ZWEI Zwecke benutzt werden. Der erste dient zur Übung, wie man Krankheiten über die Tiere der Pestländer verbreitet, das kennt Ihr ja bereits.\n\nDer Rest der Seuche wird für düstere Experimente in die Weinende Höhle transportiert, die nördlich von Malicias Außenposen liegt. Schüler der Scholomance verwenden die Seuche, um die Toten zu reanimieren!\n\nDas muss unbedingt aufhören.", sourceObjective = "Tötet in der Weinenden Höhle, die in den Westlichen Pestländern liegt, 2 Schüler Krastinovs, 2 Schläger aus Formfleisch, 2 Reißer aus Formfleisch und 4 unheilige Körperchen.", completion = "Ihr habt Euch selbst übertroffen, {name}. Wir haben nicht nur dem Kult der Verdammten bei ihrem Kreuzzug, die Pestländer neu zu infizieren, einen empfindlichen Rückschlag versetzt, Ihr habt auch noch einen weiteren fatalen Plan aufgedeckt: Sie holen die Toten ins Leben zurück!\n\nEuer Name wird bestimmt erwähnt, wenn die Information dem Hochlord Fordring vorgetragen wird, {name}. Seid Euch meiner Dankbarkeit und dem Segen des Argentumkreuzzugs gewiss.", sourceObjectiveStatus = "unverified-source-field" }
quests[27056] = { id = 27056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belmonts Bericht", description = "<Belmont reicht Euch einen versiegelten Umschlag.>\n\nBringt diesen Bericht zu Fürstin Sylvanas Windläufer. Es ist meine Einschätzung der Lage im Silberwald basierend auf Eurer und Yoricks Feldarbeit.\n\nWenn wir diese rebellischen Worgen nicht aufhalten, werden sie uns überrennen! Jetzt ist es Zeit zu handeln!", sourceObjective = "Bringt Belmonts Bericht zu Fürstin Sylvanas Windläufer in der Kommandozentrale der Verlassenen im Silberwald.", progress = "Kniet nieder vor Eurer Fürstin, {name}.", completion = "Crowley… Eine lästige Schmeißfliege. Ein Insekt, das nur darauf wartet, unter meinem Stiefel zerquetscht zu werden.\n\nEr will also die wilden Worgen im Silberwald aufwiegeln? Wir werden ihm und seinen Verbündeten die Macht der Verlassenen zeigen!\n\nAber zuerst müssen wir das Durcheinander beseitigen, das die Flotte des Kriegshäuptlings angerichtet hat. Ohne ihre Hilfe könnten wir diesen Krieg verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[27057] = { id = 27057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum heimischen Hof", description = "Sorgfältig verschließt Ihr den Zapfhahn auf dem Bedienfeld und beobachtet, wie das faulige Sekret in die leere Flasche tropft.\n\nJetzt, da Ihr das Gift in Händen haltet, ist es Zeit zu Außenagent Kaartish in die Stätte der Heiler zurückzukehren.", sourceObjective = "Bringt die Gefüllte Flasche: Gahrrons Trauerfeld zu Außenagent Kaartish in der Stätte der Heiler in den Westlichen Pestländern.", progress = "Gahrrons Trauerfeld beherbergt einen hochgiftigen Seuchenkessel. Wenn wir erst eine Probe der Seuche haben, die er ausspuckt, werden wir in der Lage sein, festzustellen, ob der Kult der Verdammten wirklich hinter der Vergiftung unseres Landes steckt.", completion = "Gute Arbeit! Einen Moment bitte...\n\n<Der Draenei nimmt sich einen Moment Zeit, um Eure Probe mit der Probe, die er wahrscheinlich schon vorher destilliert hat, zu vergleichen.>\n\nJa, das scheint dieselbe Verderbnis zu sein, die auch die Wildtiere befallen hat. Mit diesem Wissen und Eurer Kampferfahrung könnten wir die Macht haben, das zu beenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27058] = { id = 27058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die falsche Folge", description = "Wir müssen den Schattenhammer daran hindern, das Tor zu benutzen. Es gibt nur einen Weg.\n\nGebt die falsche Aktivierungsfolge ein und zerstört es.\n\nHmm, mal sehen. Ja, damit öffnet man das Tor zu den explosiven Tiefen der Feuerlande, der Elementarebene des Feuers. Das sollte funktionieren.", sourceObjective = "Benutzt den Torwächter, um die falsche Aktivierungsfolge einzugeben und so das Tor zu zerstören.", completion = "Ihr habt es geschafft! Ihr habt herausgefunden, was der Schattenhammer vorhat und ihnen dann einen Strich durch die Rechnung gemacht!\n\n<Mowi stellt sich auf die Zehenspitzen und gibt Euch einen Kuss auf die Wange.>\n\nNun, ich bin mir sicher, dass ich hier irgendwo etwas für Euch habe.\n\n<Sie kramt nach Eurer Belohnung.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27059] = { id = 27059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die falsche Folge", description = "Wir müssen den Schattenhammer daran hindern, das Tor zu benutzen. Es gibt nur einen Weg.\n\nGebt die falsche Aktivierungsfolge ein und zerstört es.\n\nHmm, mal sehen. Ja, damit öffnet man das Tor zu den explosiven Tiefen der Feuerlande, der Elementarebene des Feuers. Das sollte funktionieren.", sourceObjective = "Benutzt den Torwächter, um die falsche Aktivierungsfolge einzugeben und so das Tor zu zerstören.", completion = "Ihr habt es geschafft! Ausgezeichnete Arbeit, junger Herr. Ihr habt herausgefunden, was der Schattenhammer vorhat und ihnen dann einen Strich durch die Rechnung gemacht!\n\n<Prüfer Rowe klopft Euch mit seiner knochigen Hand anerkennend auf den Rücken.>\n\nNun, ich bin mir sicher, dass ich hier irgendwo etwas für Euch habe.\n\n<Er kramt nach Eurer Belohnung.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27060] = { id = 27060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unheilige Kuh", description = "<Bauer Wollerton versucht, sich zusammenzureißen.>\n\nKühe? Erkundigt Ihr Euch nach dem vermissten Vieh?\n\nNormalerweise lasse ich die Kühe nördlich vom Haus grasen. Ab und zu wird eine weggezaubert. Da bleibt dann nur eine Blutspur zurück. Wer macht denn so was?\n\nIch habe Angst, dieser Spur zu folgen... etwas Krankes geht hier in Sturmwind vor!", sourceObjective = "Begleitet Anduin Wrynn und folgt der Blutspur von Wollertons Bauernhof zum Tatort. Haltet Anduin am Leben. Wenn er nicht mehr an Eurer Seite ist, findet Ihr ihn in Burg Sturmwind.", completion = "Das war knapp! Ich kann gar nicht glauben, dass Ihr Euch gegen so viele gleichzeitig behauptet habt.\n\nOffenbar wurde dieser Ort für ein widerliches Einführungsritual des Schattenhammers genutzt. Sie sind auf jeden Fall in Sturmwind aktiv. Was ist das?\n\n<Anduin findet ein Abzeichen, das auf dem Schrein liegt.>\n\nDieses Abzeichen zeigt eine Axt und einen Hammer, die gekreuzt sind. Es sieht alt aus. Wenn wir uns weiter umsehen, finden wir vielleicht heraus, was es bedeutet...", sourceObjectiveStatus = "unverified-source-field" }
quests[27061] = { id = 27061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zwielichtwarte", description = "Der Drache, von dem sie reden, ist Abyssion, {name}. Es wird nicht einfach sein, das Fragment von ihm zu erhalten.\n\nTrefft Euch erneut mit Mylra. Sie lenkt ihre Einsätze von der Zwielichtwarte hier in der Nähe aus.\n\nSie wird Euch sagen, was wir als Nächstes tun werden.", sourceObjective = "Sprecht mit Sturmruferin Mylra an der Zwielichtwarte in Tiefenheim.", completion = "Also müssen wir uns Abyssion stellen, um das Fragment zu bekommen? Diese Operation ist plötzlich sehr viel gefährlicher geworden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27062] = { id = 27062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lauernde Gefahr", description = "Die Stacheleber im Hügel der Klingenhauer scheinen sich mit der Geißel zusammengetan zu haben. Das sind düstere Nachrichten für uns, {class}. Wir haben genug ernsthafte Probleme damit, uns mit den Grimmtotem auseinanderzusetzen, wir können nicht noch einen Angriff der Geißel überstehen. Begebt Euch in den Hügel der Klingenhauer, der im Osten liegt, und seht, ob Ihr jemanden findet, der Euch dabei hilft, sie aufzuhalten, bevor sie uns hier angreifen.", sourceObjective = "Findet Hilfe bei den Hügeln der Klingenhauer.", completion = "Ihr scheint fähig als Krieger zu sein. Vielleicht könnt Ihr mir helfen, diesem schrecklichen Elend hier ein Ende zu bereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27063] = { id = 27063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lauernde Gefahr", description = "Die Geißel ist eine Beleidigung für die Natur. Sie haben es geschafft, die Stacheleber im Hügel der Klingenhauer zu verderben. Jetzt drohen sie sich noch weiter in den Tausend Nadeln auszubreiten und - wie ich fürchte - schlussendlich auch nach Westen nach Feralas. Ihr müsst dorthin gehen und alles tun, um sie festzusetzen. Vielleicht könnt Ihr jemand in dem Gebiet dort finden, der Euch hilft? Die Winde flüstern von einer mächtigen Präsenz in der Gegend.", sourceObjective = "Sucht im Hügel der Klingenhauer nach Hilfe.", completion = "Ihr wirkt wie ein fähiger Krieger. Vielleicht könnt Ihr mir dabei helfen, den Schrecken hier zu beenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27064] = { id = 27064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er hält uns hin", description = "{name}, es scheint beinahe so, als ob Samuelson absichtlich unsere Zeit verschwendet. Die Dockarbeiter wissen gar nichts. Was noch wichtiger ist - Sprengstoff aus dem Hafen von Sturmwind ist verschwunden.\n\nWisst Ihr, was ich denke? Ich wette, Samuelson weiß mehr, als er zugibt. Er hat wahrscheinlich eine Spur, den Schattenhammer betreffend, und will die Lorbeeren selbst einheimsen.\n\nWir sollten uns seine Akten im SI:7 Hauptquartier mal ansehen. Bringt mich dorthin, denn ich müsste Einblick in seine Akten bekommen, um herauszufinden, was er wirklich weiß.", sourceObjective = "Begleitet Anduin Wrynn in den dritten Stock des SI:7 Hauptquartiers in der Altstadt von Sturmwind. Wenn er nicht mehr an Eurer Seite ist, findet Ihr ihn in Burg Sturmwind.", progress = "Es wird Zeit, dass wir Antworten finden!", completion = "Das ist WIRKLICH verdächtig, {name}! Samuelson hat nicht einen Schnipsel Informationen über den Schattenhammer - es scheint beinahe so, als ob er überhaupt keine Untersuchungen über sie anstellt. Dennoch hat er hier eine Aufstellung über die fehlenden Sprengstoffe.\n\n\n\nUnd ich habe dieses merkwürdige Abzeichen mit einem Symbol darauf gefunden: Eine Axt und ein Hammer, die sich kreuzen.\n\nDas hat doch etwas zu bedeuten - aber was?", sourceObjectiveStatus = "unverified-source-field" }
quests[27065] = { id = 27065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flotte des Kriegshäuptlings", description = "Unsere Verstärkung aus Kalimdor ist letzte Nacht eingetroffen. Drei Kanonenboote der Orcs voller Vorräte, Waffen und Soldaten. Drei Kanonenboote der Orcs, die wir an die verdammten Worgen von Blutfang verloren haben.\n\nWie kann eine ganze Orcflotte gegen einen kleine Truppe feindlicher Kämpfer verlieren, die noch nicht einmal Belagerungswaffen besitzen? Diese wichtige Frage werdet Ihr mir beantworten. Sucht Eure Sachen zusammen und meldet Euch bei der orcischen Admiralin Hatchet an der Rückendeckung der Verlassenen, südwestlich von hier.\n\nMacht diesen Orcs Beine, {name}.\n\nIch erwarte Euren vollständigen Bericht.", sourceObjective = "Meldet Euch bei Admiralin Hatchet bei der Rückendeckung der Verlassenen im Silberwald.", completion = "Dieses Fiasko könnte als eine der größten Peinlichkeiten in die Geschichte der Seekriegsführung eingehen. Wie das passiert ist? Trunkenheit ist passiert. So war das.", sourceObjectiveStatus = "unverified-source-field" }
quests[27066] = { id = 27066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das richtige Wort", description = "Während Ihr Eure Fähigkeiten ausbaut, werdet Ihr Zugang zu vielen neuen Kräften erlangen.\n\nGeht los - sammelt Erfahrungen und kommt zu mir zurück, wenn Ihr etwas Neues gelernt habt. Ihr könnt es an den Trainingsattrappen in der Nähe demonstrieren.", sourceObjective = "Ihr müsst Stufe 3 erreichen, um Schattenwort: Schmerz zu erlernen. Erprobt es 5-mal an Trainingsattrappen in Camp Narache.", sourceObjectiveStatus = "unverified-source-field" }
quests[27067] = { id = 27067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondfeuer", description = "Je weiter Ihr Eure Druidenfähigkeiten entwickelt, desto mehr werdet Ihr fühlen, wie Eure Verbindung zu Mutter Erde immer tiefer wird. Dann werdet Ihr beginnen, neue Geheimnisse in der Natur zu entdecken, und lernen, neue Zauber anzuwenden.\n\nUnd nun geht und sammelt mehr Erfahrung. Kehrt zu mir zurück, wenn Ihr einen neuen Zauber gelernt habt. Dann werde ich begutachten, was Ihr gelernt habt.", sourceObjective = "Erreicht Stufe 3 und erlernt Mondfeuer. Dann übt diese Fähigkeit an einer Trainingsattrappe im Camp Narache.", completion = "Ihr habt Talent für Heilkünste, {name}. Wo immer Euer Weg Euch hinführt, Eure Fähigkeiten als Heiler werden begehrt sein. Kehrt zu mir zurück, wenn Ihr weitere Ausbildung benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27068] = { id = 27068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häuptling Ukorz Sandskalp", description = "Schaut genau hin, Mann. So läuft das hier, Verrat folgt auf Verrat. Erst trickse ich Euch aus, um das Schwert zu krieg'n, und dann kommt Häuptling Ukorz und legt mich so richtig aufs Kreuz.\n\nSo is' das Leben, ja! Oder war es...\n\nNa ja, ich weiß, dass Ihr Mazoga gar nie nich' leiden konntet. Aber ich weiß, dass Ihr trotzdem macht, worum ich Euch bitte. Tötet ihn für mich. Vergießt noch mehr Blut auf dem Sand und gebt Häuptling Ukorz Sandskalp was alle Sandwüter verdien'n...einen blutigen Tod.\n\nVielleicht überlasse ich Euch was von mir, auf dem kein Fluch liegt, ja?", sourceObjective = "Tötet Häuptling Ukorz Sandskalp.", completion = "Er ist weg? Hatte er das Schwert?\n\nNee... sagt nix. Ist egal. Mazoga kümmert das nicht.\n\nIch bin dann mal weg, Mann. Die Folgen meiner Handlungen warten auf mich. Nehmt, was immer ich bei mir trage... Wo ich hingehe, brauch' ich das nich' mehr...", sourceObjectiveStatus = "unverified-source-field" }
quests[27069] = { id = 27069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der stählerne Donner", description = "Wir brauchen uns von der Schmach dieser Niederlage wahrscheinlich gar nicht reinzuwaschen, {name}. Der Kriegshäuptling wird uns stattdessen alle hinrichten lassen.\n\nIch will verdammt sein, wenn wir kampflos aufgeben. Obwohl der ganze Strand von Blutfangworgen überrannt ist, könnte noch Hoffnung bestehen. Ich möchte, dass Ihr einen unserer Süßwassermatrosen zu dem Landestrand genau westlich von hier begleitet und unsere Vorräte wiederbeschafft. Kehrt zu mir zurück, wenn der Süßwassermatrose nichts mehr tragen kann.", sourceObjective = "Bergt 5 Seebärenkisten.\n\nFalls Ihr unerwartet Euren orcischen Süßwassermatrosen verlieren solltet, dann sprecht mit Admiralin Hatchet, um einen neuen zu bekommen.", completion = "In diesen Kisten befindet sich STÄHLERNER DONNER! Jetzt, da unsere Waffen wieder da sind, haben wir vielleicht eine Möglichkeit, uns zu rehabilitieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[27070] = { id = 27070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergebliche Mühe", description = "Ich hörte, dass ein Troll hier drin - Hydromantin Velratha hieß sie, glaube ich - in den Besitz eines sehr seltenen, wunderschönen und mächtigen Schmuckstücks gelangt ist - der Tiara der Tiefen. Sie benutzt sie, um den mächtigen Halbgott Gahz'rilla zu kontrollieren, dessen Schuppen angeblich vor Energie knistern. Wisst Ihr, was das bedeutet, {race}?\n\nIch brauche sie! Tötet Velratha, nehmt ihr die Tiara der Tiefen ab und tötet Gahz'rilla für eine seiner Schuppen. Bringt mir alles schleunigst her! Ich werde Euch fürstlich belohnen...", sourceObjective = "Beschafft Euch die Tiara der Tiefen und Gahz'rillas elektrisierte Schuppe.", progress = "Habt Ihr, was ich brauche?", completion = "Ausgezeichnet! Die Tiara verschafft mir die absolute Kontrolle über das Wasser hier und die elektrisierte Schuppe wird alle Maschinen antreiben, die ich zu meinem Vorteil nutze.\n\nIhr macht mich zu einem sehr reichen und mächtigen Goblin! Ihr könnt das hier haben, das ist nichts im Vergleich zu dem, was ich bald haben werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27071] = { id = 27071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn der Sandwüter", description = "Die Sandwüter sind ein widerstandsfähiger Stamm. Sie hab'n Sandstürme überlebt und über die Jahre hinweg noch ganz andere Sachen, die inzwischen längst von Sand bedeckt sind. Es wäre dumm zu glauben, dass die einzige Macht hier die Trolle sind. Wir hab'n Skarabäen gezähmt, Sul'lithuz gezüchtet und unsere Toten wiederaufersteh'n lassen, damit sie bis in alle Ewigkeit als Zombies kämpfen.\n\nRuuzlu, die rechte Hand von Häuptling Ukorz Sandskalp, hat vor, mit ihrer Hilfe Tanaris für die Sandwüter zurückzuerobern. Ihr solltet die Trolle, die dafür verantwortlich sind, töt'n, wenn Ihr leben wollt, Mann.", sourceObjective = "Tötet Theka den Märtyrer, Hexendoktor Zum'rah, Antu'sul und Ruuzlu.", completion = "Ihr habt sie getötet? Alle? Und seid lebendig zurückgekomm'n?\n\nDann nehmt von mir, was Ihr wollt. Es ist überwiegend frei von Flüchen, Mazoga verspricht es.", sourceObjectiveStatus = "unverified-source-field" }
quests[27072] = { id = 27072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Alte Kaserne", description = "Das Symbol auf diesen Abzeichen ist mir schon aufgefallen, bevor Todesschwinge die Stadt angegriffen hat. Die Soldaten in der Alten Kaserne, die im Westen der Stadt den Hafen überblickt, haben sie getragen.\n\nIhr hättet kaum zu einer besseren Zeit hier auftauchen können. Einer meiner Topagenten, Jack Bauden, ist in meinem Namen mit der Infiltration des Schattenhammers beschäftigt. Er wird seit gestern Nacht vermisst. Wenn Anduin und Ihr Recht habt, dann haben sich die Kultisten in der Alten Kaserne verkrochen. Die Zeit drängt! Greift die Alte Kaserne an, schaltet die Kultisten aus und rettet Jack Bauden.", sourceObjective = "Geht zur Alten Kaserne und tötet 6 wahnsinnige Kultisten, dann findet Jack Bauden.", progress = "<Bauden ist ohnmächtig. Die Gegend wimmelt noch immer vor Kultisten. Ihr solltet sie beseitigen, bevor Ihr Untersuchungen anstellt.>", completion = "<Ihr ohrfeigt Bauden bis er zu sich kommt.>\n\n{class}? Was macht Ihr denn hier?\n\nIch bin SI:7-Agent Jack Bauden. Heute ist der längste Tag meines Lebens.", sourceObjectiveStatus = "unverified-source-field" }
quests[27073] = { id = 27073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht ihnen die Hölle heiß!", description = "Die Goblins sind schuld, {race}!\n\n<hicks!>\n\nWisst Ihr, wir sind vom Bilgewasserhafen aus über Azshara zum Silberwald aufgebrochen. Ein riesiger Fehler! In unserem gesamten Imperium habe ich noch nie einen sündigeren und schmächlicheren Haufen erlebt! Diese verdammten Goblins haben uns zu jedem möglichen Laster verführt und uns mit Fässern voller Bier aufs Meer geschickt!\n\n<hicks!>\n\nDie Scham, die wir dafür empfinden, sitzt tiefer als jede Narbe. Unsere Ehre muss wiederhergestellt werden! Tötet die Blutfangworgen, die uns aufgelauert haben. Sie plündern gerade das Wrack im Südwesten.", sourceObjective = "Tötet 10 Blutfangplünderer.", completion = "Sieht aus, als hättet Ihr diese Worgen so richtig vermöbelt und die Scham von uns genommen. Vielleicht hören die Seebären jetzt auf, zu saufen.\n\nAch, wem mache ich was vor.\n\nHa!", sourceObjectiveStatus = "unverified-source-field" }
quests[27074] = { id = 27074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bekämpft den Hammer", description = "Ihr habt das Unmögliche möglich gemacht! Ich habe die Nase voll davon, hier herumzuschmollen. Es wird Zeit, sich aufzugnomen.\n\nIch muss meinen Vater finden. Aber Ihr! Befasst Euch nicht länger mit mir. Ihr müsst weiter gegen diese Kultisten kämpfen.\n\nGeht und sprecht mit Ashlan Schmunzelstein im Osten. Er versucht, den Schattenhammer aufzuhalten, aber er hat niemanden, der ihm hilft. Ihr seid seine einzige Hoffnung!\n\nGebt nicht auf, {name}. Ich werde es auch nicht tun.", sourceObjective = "Sprecht in Loch Modan in der Nähe der Festung Mo'grosh mit Ashlan Schmunzelstein.", completion = "Habt Ihr dem Zwielichtlager in der Mitte des Sees einen Schlag versetzt? Nicht schlecht, Junge!\n\nWenn Ihr den Kampf zu ihnen nach Hause tragen wollt, kann ich Euch die Gelegenheit dazu geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27075] = { id = 27075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diener von Cho'gall", description = "Der Schattenhammer war zunächst ein Klan der wilden Horde. Ihr Anführer - Cho'gall - formte aus seiner Bande Oger nach und nach einen tödlichen Kult, der jeden willkommen hieß, der verrückt genug war, sich das Ende allen Lebens zu wünschen. Wie Ihr seht, gibt es immer noch viele Oger unter ihnen. Sie sind verwirrt, fanatisch und immer noch so stark wie früher.\n\nDiese primitiven Monster besitzen die Frechheit, hierherzukommen und ihren Schmutz über unser Land auszubreiten. Je mehr Ihr tötet, desto besser wird Loch Modan dastehen, {name}.", sourceObjective = "Tötet 7 Oger der Mo'grosh in der Festung Mo'grosh.", completion = "Es mag zwar finster aussehen, aber wir werden mit Eurer Hilfe gewinnen, {name}. Sie werden die Zwerge nicht unterdrückt halten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[27076] = { id = 27076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einbruch mit schwerem Werkzeug", description = "Ein guter Kumpel von mir, Weegli Lunte, hat sich mit Unteroffizier Bly und seiner Gruppe Gesetzloser zusammengetan, um in Zul'Farrak einzumarschieren und das legendäre Sul'thraze zu erbeuten. Natürlich haben sie den Stamm der Sandwüter unterschätzt und jetzt sind sie alle festgesetzt und warten auf ihre Hinrichtung, um den Halbgott Gahz'rilla zufriedenzustellen.\n\nWenn Ihr Weegli befreit, wird er Euch helfen, den Weg zu Ukorzs Privatgemächern freizusprengen, wo er mindestens einen Teil der Klinge aufbewahrt.\n\nTötet Nekrum den Ausweider und Schattenpriester Sezz'ziz, die ihn gefangen genommen haben, als Rache...Ich werde Euch belohnen.", sourceObjective = "Befreit Weegli Lunte und tötet Nekrum den Ausweider und Schattenpriester Sezz'ziz.", completion = "Wow! Ich wusste, ich kann auf Euch zählen! Hier ist etwas für Eure Unannehmlichkeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27077] = { id = 27077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ans Chaos klammern", description = "Die Kultisten vom Schattenhammer benutzen ihre Kräfte, um Elementiummetall aus den Tiefen der Erde zu gewinnen. Sie locken es als verdrehte Stacheln heraus, um damit ihre Gebäude zu formen, die in dem entweihten Boden verwurzelt sind.\n\nDie Oger hier scheinen dabei kräftig mitzumischen und wir müssen zuschlagen, solange sie es noch in Form drehen.\n\nReißt die Stacheln aus dem Boden, solange sie noch biegsam sind und bringt sie zu mir. Wir werden diesen Hundesöhnen nicht einen Zoll unseres Landes überlassen.", sourceObjective = "Reißt 10 entstehende Elementiumstacheln aus dem Boden der Festung Mo'grosh.", progress = "Habt Ihr die Stacheln herausgerissen?", completion = "Schade, dass diese halbgestalteten Dinger zu brüchig und krumm sind, als dass wir sie als Waffen benutzen könnten. Aber nur dank Euch haben wir überhaupt die Chance, sie herauszuziehen, bevor sie sich verhärten. Deshalb werde ich mich nicht beschweren.", sourceObjectiveStatus = "unverified-source-field" }
quests[27078] = { id = 27078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gor'kresh", description = "Der Oger, der über diese primitiven Narren wachen soll, heißt Gor'kresh. Er ist groß genug, um selbst diese Schläger herumzukommandieren - und obendrein ist er gerissen. Setzt niemals voraus, dass ein Oger dumm ist, denn dann erwischt er Euch.\n\nWenn Ihr ihn beseitigt, dann werden wir dem Schattenhammer schon zeigen, dass Loch Modan kein Sprungbrett für sie ist. Stellt Euch Gor'kresh entgegen und treibt diese Narren zurück in das Hochland!", sourceObjective = "Besiegt Gor'kresh.", sourceObjectiveStatus = "unverified-source-field" }
quests[27082] = { id = 27082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfaire Methoden", description = "Habt Ihr die großen, schwerfälligen Ettins gesehen, die durch die Wälder streifen? Die verfluchten Dinger kamen aus Gilneas. Jetzt vagabundieren sie durch das Land und suchen ihre nächste, saftige Mahlzeit. Wir haben es geschafft, einige von ihnen zu unterwerfen und sie nutzbar zu machen, um unsere Wagen zu ziehen, aber die anderen... nun, sie müssen getötet werden.\n\nLeider können wir keine Soldaten erübrigen, um das zu erledigen. Da kommt Ihr ins Spiel, {class}.\n\nIch habe einen Plan, aber dafür brauchen wir noch Materialien. Geht hinaus in die Wälder, die diese Basis umgeben und beschafft die Organe kranker Tiere.", sourceObjective = "Beschafft 8 verseuchte Organe von ergrauten Riesenbären und tollwütigen Worgs.", progress = "Wir sind die Verlassenen! So machen wir das, {class}.", completion = "Ausgezeichnet! Und jetzt müssen wir das \"Mahl\" vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27083] = { id = 27083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht geht weiter!", description = "Es gibt Nachrichten aus Andorhal, {name}. Die Schlacht hat wieder angefangen.\n\nUnter den Streitkräften der Verlassenen ist es wohl bekannt geworden, dass Ihr Euch in der ersten Schlacht um Andorhal als einer der Helden hervorgetan habt. Koltira verlangt umgehend nach Eurer Anwesenheit.", sourceObjective = "Meldet Euch in den Westlichen Pestländern in Andorhal bei Koltira Todesweber.", completion = "Thassarian und die Menschen haben ihren Zug gemacht. Ich dachte, ich hätte eine Abmachung mit Thassarian... aber das muss dann wohl reichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27084] = { id = 27084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bauernmiliz", description = "Der Kampf begann, als sie uns von hinten angriffen. Ich habe kurz nicht aufgepasst und eine Gruppe schlecht bewaffneter Bauern und Milizen stieß vom Trostlosen Feld in unsere Flanke vor.\n\nSie mögen schwach sein, aber wenn sie so ungehindert angreifen, besteht die Gefahr, dass sie uns allein durch ihre zahlenmäßige Überlegenheit überwältigen.\n\nLindsays domestizierte Monstrositäten können sich um den Nahkampf kümmern. Nehmt dieses Halsband, bleibt hinten und benutzt es, um meinen schwarzen Gargoyle auf diese Bauern zu hetzen.", sourceObjective = "Benutzt das ebenhölzerne Gargoylehalsband auf 6 Provinzmilizen in Andorhal.", completion = "Das hat nur ein winziges Loch in ihre Reihen gerissen...aber der Anblick ihrer Freunde, die vom Himmel fielen, hat ihre Entschlossenheit ins Wanken gebracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27085] = { id = 27085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Truppen unterstützen", description = "Auch wenn diese Bauern uns zu überrennen drohen, dürfen wir die Hauptstreitmacht der Allianz nicht vergessen.\n\nReist in den Westen nach Andorhal und tötet die menschlichen Soldaten, die gegen unsere Todeswachen kämpfen. Wir können alle Hilfe gebrauchen, die wir bekommen können.", sourceObjective = "Tötet 15 Verteidiger von Andorhal.", completion = "Ihr habt gut gekämpft, {name}. Ich wünschte, ich hätte Eure Fähigkeiten ... und Euren Mut.", sourceObjectiveStatus = "unverified-source-field" }
quests[27086] = { id = 27086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asche zu Asche", description = "Im Westen, tief in dem von der Allianz gehaltenen Andorhal, findet Ihr ihre Kommandanten. Sie kämpfen nicht, sondern befehligen nur von den Rücken ihrer Pferde.\n\nJagt und tötet diese Kommandanten, {name}. Die Menschen werden machtlos sein.", sourceObjective = "Tötet 3 Streitkräftekommandanten von Andorhal.", completion = "Gut gemacht. Jetzt, da sie ausgeschaltet wurden, habe ich keine Ausreden mehr.\n\nBald muss ich mich Thassarian im Kampf stellen, für Ehre und für Andorhal.", sourceObjectiveStatus = "unverified-source-field" }
quests[27087] = { id = 27087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Entlarvung der Lindsay Rabensonn", description = "Man hat mir gesagt, dass dieses nutzlose Weib, Lindsay Rabensonn, hier wäre, um mich in diesem Kampf zu unterstützen. Bisher hat sie noch nichts anderes getan, als im Keller des Haupthauses hinter mir dumpf vor sich hin zu brüten. Ist wohl auch besser so. Sie war eine Ablenkung.\n\nDennoch, ich kann und werde keine Befehlsverweigerung dulden. Findet sie und bringt sie zu mir.", sourceObjective = "Meldet Euch in den Westlichen Pestländern in Andorhal bei Lindsay Rabensonn.", completion = "Ihr werdet mich nirgendwohin mitnehmen, {name}.\n\nWährend Koltira und sein Kumpan Thassarian herumstolzieren, habe ich vor, diese Schlacht zu gewinnen. Koltira wird für seine Schwäche bezahlen.\n\nGlaubt Ihr nicht? Na gut, dann weihe ich Euch in mein kleines Geheimnis ein...", sourceObjectiveStatus = "unverified-source-field" }
quests[27088] = { id = 27088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist nur giftig, wenn man es einnimmt", description = "Nehmt diesen Käfig, {class}. Darin befindet sich eins meiner mutierten Buschhühner, mit einigen leichten Veränderungen. In dem Hintern des Buschhuhns befindet sich eine Dynamitstange, die mit Schleim von den verseuchten Organen, die Ihr mir gebracht habt, versetzt ist.\n\nBringt den Käfig in den Wald und findet den Waldettin, der dort herumläuft. Lasst das Huhn frei und lehnt Euch zurück, während dieses Meisterstück seine Arbeit tut. Die folgende Explosion dürfte ausreichen, um den Ettin zu töten oder ihn so sehr zu schwächen, dass Ihr die Möglichkeit bekommt, ihn zu erlegen.", sourceObjective = "Benutzt das mutierte Buschhuhn, um den Waldettin zu töten.", completion = "<Apotheker Wurmschmutz lacht wie irre.>\n\nGab es daran jemals Zweifel? Ein Ettin kann der Wissenschaft nicht das Wasser reichen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27089] = { id = 27089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versteckter Trumpf", description = "Ihr habt ja keine Ahnung, wie schwer es war, die Tarnung aufrecht zu halten, während ich zusah, wie Koltira diesen Krieg entgleiten ließ. Es ist so weit gekommen, dass diese lästigen Bauern uns zu überwältigen drohen. Und all das nur, weil er sich geweigert hat, einen Freund zu töten.\n\nNehmt noch einmal meine Val'kyr, {name}. Tötet die Bauern mit ihr an Eurer Seite, macht sie zu Verlassenen und lasst sie ausrücken. Dann geht mit einer Gruppe von ihnen in den von der Allianz gehaltenen Westteil von Andorhal und bringt diesen Todesritter Thassarian zur Strecke.\n\nWir werden diesen Krieg doch noch gewinnen.", sourceObjective = "Tötet 5 verängstigte Provinzmilizangehörige mit der bezauberten Val'kyr an Eurer Seite. Dann benutzt Eure Fähigkeit 'Ruf zu den Waffen' und macht aus ihnen Gardisten der Verlassenen. Dann findet Thassarian im Westteil von Andorhal.", completion = "Dies ist die Leiche von Lurid, Thassarians getreuem Ritter. Da Thassarian nirgendwo zu finden ist, scheint es, als ob die Streitkräfte der Allianz sich zurückgezogen haben.\n\nDie Verlassenen haben die Schlacht für Andorhal gewonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27090] = { id = 27090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andorhal, für Immer und Ewig", description = "Sylvanas wird alles über die Abreise von Thassarian aus Andorhal wissen wollen. Ihr beschließt, zu der Seite der Stadt, die von den Verlassenen gehalten wird, zurückzukehren.", sourceObjective = "Meldet Euch in den Westlichen Pestländern in Andorhal bei Fürstin Sylvanas Windläufer.", completion = "Seht Ihr? Ich brauchte nur ein wenig Hilfe von den Val'kyr. Diese Wesen sind weitaus hilfreicher, als ich ursprünglich dachte.\n\nAber nun zu anderen Dingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27091] = { id = 27091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmangriff!", description = "Gut. Das war ein vielversprechender Anfang. Vor Euch liegt noch ein langer Weg. Aber je weiter ihr voranschreitet, desto mehr Dinge lernt Ihr, von denen Ihr zuvor nicht einmal zu träumen gewagt hättet.\n\nSammelt noch etwas mehr Erfahrung und erlernt eine neue Technik. Sucht Euch dann eine Trainingsattrappe und demonstriert Eure neue Fähigkeit.", sourceObjective = "Erreicht Stufe 3 und erlernt Sturmangriff. Findet eine Trainingsattrappe außerhalb des Sonnenturms und übt diese Fähigkeit.", completion = "Ich glaube, Ihr habt die Grundzüge des Sturmangriffs verstanden, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27092] = { id = 27092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kataklysmus in den Katakomben", description = "Sorgt Euch nicht um mich, {class}. Ich habe den Plan des Schattenhammers aufgedeckt. Sie haben im Hafen von Sturmwind eintreffenden Sprengstoff gesammelt und aufgeschichtet. Irgendwie haben sie sich Zutritt zu den Katakomben unter der Kathedrale des Lichts verschafft. Ich hörte von jemandem namens \"Der Schwarze Bischof\".\n\nWir haben nicht genug Zeit, um die Wache zu warnen. Es bleiben Euch nur noch Minuten, um in die Katakomben vorzudringen und die Bombe zu entschärfen! Geht! Schnell! Oder TAUSENDE MENSCHEN werden STERBEN!", sourceObjective = "Betretet die Kathedrale des Lichts und steigt hinab in die Katakomben darunter. Tötet den Schwarzen Bischof und entschärft den Sprengstoffhaufen in der Nähe.", progress = "<Dunkle magische Runen bedecken die Oberfläche des Sprengstoffs und pulsieren mit zunehmender Intensität...>\n\nIhr müsst den Schwarzen Bischof finden!", completion = "<3... 2 ... 1 ...>\n\n<Ihr feuchtet Eure Finger an und erstickt die Lunte. Die Kathedrale ist gerettet!>\n\n<Unter den Sprengstofffässern findet Ihr einen Stapel Notizen und Papiere. Offenbar haben die Kultisten versucht, die zurückgelassenen Beweise zu zerstören.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27093] = { id = 27093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Dunkelheit verlaufen", description = "Einige würden sagen, dass wir Glück haben, am Leben zu sein. Diese Leute wären Idioten. Wenn wir gestorben wären, müssten wir uns nicht dem Zorn des Kriegshäuptlings stellen. Aber nun, was geschehen ist, ist geschehen. Jetzt müssen wir versuchen, unsere verlorene Ehre wiederherzustellen.\n\nDas dritte Schiff in unserer Flotte ist direkt vor der Huschdunkelküste nordwestlich von hier gesunken. Diejenigen, die es an Land geschafft haben, wurden von riesigen Spinnen der Gegend umzingelt und in Spinnweben gehüllt.\n\nWenn es dort Überlebende gibt, müssen wir sie befreien! Geht, {name}. Auf ins Huschdunkel!", sourceObjective = "Rettet 6 orcische Seebären aus dem Huschdunkel.", completion = "Lok'tar, {name}. Sobald die Wirkung des Biers nachlässt, werden meine Orcs bereit sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[27094] = { id = 27094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefer in die Dunkelheit", description = "Die Netzhuschermatriarchin ist in der Nähe! Ihr könnt der Bedrohung durch die Netzhuscher ein Ende bereiten, indem Ihr sie erlegt!\n\nFindet sie am Ende der Höhle im Huschdunkel und vernichtet sie!", sourceObjective = "Tötet die Netzhuschermatriarchin.", completion = "Ihr habt unsere Orcs gerettet und die Netzhuschermatriarchin getötet? Wir schulden Euch großen Dank. Ihr habt uns alle vor der sicheren Hinrichtung bewahrt, {name}. Ich bin sicher, dass wir diese betrunkenen Idioten jetzt wecken können.", sourceObjectiveStatus = "unverified-source-field" }
quests[27095] = { id = 27095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Netzhuscherbedrohung", description = "Rache ist allumfassend, {name}! Unser drittes Schiff ist direkt vor der Huschdunkelküste nordwestlich von hier gesunken. Die Männer, die es von dem Schiff herunter geschafft haben, wurden entweder gefangen genommen, oder von den Netzhuscherspinnen der Region getötet. Dafür müssen die Spinnen sterben! ALLE!\n\nBegebt Euch zum Huschdunkel und zermalmt diese Spinnen!\n\nHaltet Ausschau nach ihrer Matriarchin. Wenn wir sie finden, können wir diese Bedrohung vielleicht beenden!", sourceObjective = "Tötet 12 Netzhuscherspinnen.", completion = "Die Wurzel dieses Übels muss gefunden und zerstört werden! Die Netzhuschermatriarchin muss in der Nähe sein. Zweifellos verbirgt sie sich in der nahegelegenen Höhle!", sourceObjectiveStatus = "unverified-source-field" }
quests[27096] = { id = 27096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles klar bei den Orcs", description = "<Admiralin Hatchet übergibt Euch einen Umschlag, der mit dem Zeichen der Horde versiegelt ist.>\n\nDies ist Euer Empfehlungsschreiben. Das ist das Mindeste, was ich unter diesen Umständen für Euch tun kann.\n\nKehrt zu Fürstin Sylvanas Windläufer mit diesem Brief zurück und informiert sie über unseren Status. Lasst sie wissen, dass wir nur auf ihren Befehl warten, um loszumarschieren.\n\nLebt wohl, {name}. Ihr seid <ein ausgezeichneter Soldat/eine ausgezeichnete Soldatin>.\n\nNordosten, <mein Junge/Ma'am>. Auf zur Kommandozentrale der Verlassenen!", sourceObjective = "Liefert das Empfehlungsschreiben des Admirals bei Fürstin Sylvanas Windläufer bei der Kommandozentrale der Verlassenen im Silberwald ab.", progress = "Und die Orcs?", completion = "<Sylvanas zieht eine Augenbraue hoch.>\n\nAlso ist bei den Orcs alles in Ordnung?\n\n<Sylvanas liest das Empfehlungsschreiben.>\n\nIhre Vorräte zurückgeholt? Ein Dutzend Worgen getötet? Einen Ettin zur Strecke gebracht? Ihre Soldaten befreit und die Netzhuschermatriarchin vernichtet?\n\nIch sage das ja selten, aber ich bin beeindruckt. Vielleicht entsprechen Eure Fähigkeiten tatsächlich Euren Ambitionen. Wir werden sehen, ich werde Euch auf die Probe stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27097] = { id = 27097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhebt Euch, Verlassene", description = "Die Insel Fenris ragt trotzig im Herzen des Lordameresees auf - eine grausame Erinnerung an eine längst vergangene Zeit.\n\nObwohl sie nicht länger von Gnollgezücht befallen ist, hat sich eine neue Bedrohung aufgetan. Menschenflüchtlinge, die aus ihren Behausungen im Hügelland vertrieben wurden, sind in der Hoffnung auf die Insel Fenris geflohen, einer Niederlage durch uns zu entgehen. Da irren sie sich gewaltig.\n\nNehmt Agatha mit Euch zur Insel Fenris und tötet alle Menschen. Sie wird die Gefallenen als Verlassene wiedererwecken und so unsere Streitkräfte verstärken.\n\nEnttäuscht mich nicht, {name}.", sourceObjective = "Erweckt 15 Verlassene, indem Ihr Menschen auf der Insel Fenris tötet.", completion = "Ich sehe alles, {name}. Durch Agatha entgeht mir nichts.", sourceObjectiveStatus = "unverified-source-field" }
quests[27098] = { id = 27098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lordaeron", description = "Kommt mit mir zum Grabmal, {name}. Ich möchte vieles mit Euch besprechen. Es ist unabdingbar, dass Ihr die Geschichte von Lordaeron und die Zwangslage der Verlassenen versteht.", sourceObjective = "Begleitet Fürstin Sylvanas Windläufer zum Grabmal im Silberwald.", completion = "Versteht Ihr jetzt die Wichtigkeit unserer Mission hier? Crowley und seine Hunde der Allianz müssen aufgehalten werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[27099] = { id = 27099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Entkommen", description = "Ihr müsst gegen ihre Anführer losschlagen, {name}. Ihr werdet sie in der alten Burg versteckt finden. Kämpft Euch in die Burg durch und findet die Starrköpfe! Verwandelt sie für Eure Königin!\n\nNiemand entzieht sich dem mächtigen Griff der Verlassenen!", sourceObjective = "Findet die Anführer der Flüchtlinge in Burg Fenris.", completion = "Anscheinend muss man Crowley ernster nehmen, als ich gedacht habe. Dennoch, er ist ein Mensch - Fleisch und Blut - voller Geheimnisse. Geheimnisse, die ich alle kenne...\n\nIhr habt mir gute Dienste erwiesen, {name}. Ich könnte jemand mit Euren Fähigkeiten am Grabmal gebrauchen. Ich habe einen Plan, um mit Crowley und seinen Aufrührern endgültig fertigzuwerden. Werdet Ihr mir auch weiterhin zur Seite stehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[27100] = { id = 27100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtige Forschungen", description = "Das Buch, das Ihr gefunden habt, scheint irgendeine Forschung zu beschreiben, die ein Mitglied des Schattenhammers durchgeführt hat.\n\nEs hat irgendwas mit Schlamm zu tun, aber es fehlen mehrere Seiten.\n\nVielleicht könntet Ihr zusätzliche Notizen finden, damit das Ganze einen Sinn ergibt.", sourceObjective = "Findet in den Oberen Silbermarschen 4 Zwielichtforschungsnotizen über Quecksilberschlamm.", sourceObjectiveStatus = "unverified-source-field" }
quests[27101] = { id = 27101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maziels Enthüllung", description = "Die Notizen führen Maziels Forschungsgeschwafel über die Zusammensetzung von Quecksilber und Quecksilberschlamm fort.\n\nOffenbar hat er eine wichtige Entdeckung gemacht. Er erwähnt, dass er sein Tagebuch in den Unteren Silbermarschen gen Südwesten versteckt hat.", sourceObjective = "Geht zu den Unteren Silbermarschen in Tiefenheim und findet Maziels Tagebuch.", completion = "Maziels Tagebuch scheint vom Quecksilber nicht beschädigt worden zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[27102] = { id = 27102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maziels Aufstieg", description = "Maziels Tagebuch enthält Aufzeichnungen über ein Aufstiegsritual, das seinen Körper in pures Quecksilber verwandeln würde.\n\nDas Ritual soll in einer Höhle in der Nähe der Unteren Silbermarschen stattfinden, wo Maziel sich von Quecksilberschlamm ernähren will, bis er die volle Stärke erreicht hat.\n\nVielleicht ist es noch nicht zu spät, seinem Wahnsinn Einhalt zu gebieten.", sourceObjective = "Tötet Maziel in der Silberlichthöhle in Tiefenheim.", sourceObjectiveStatus = "unverified-source-field" }
quests[27103] = { id = 27103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Splitter der Teufelsranke", description = "Der Satyr Alzzin der Wildformer übt seine verdorbene Herrschaft über diesen Teil von Eldre'Thalas aus. Die korrumpierte Frucht des Gedeihens - die Teufelsranke - sollte sich in Alzzins Nähe befinden. Sie könnte der Schlüssel sein, um diesen uralten Ort zu reinigen.\n\nWenn der große Satyr fällt, versucht so viel wie möglich von der Essenz der Teufelsranke zu erlangen. Versiegelt sie dann in diesem Reliquiar der Reinheit und bringt es zu mir.\n\nViel Glück und Cenarius' Kraft sei mit Euch!", sourceObjective = "Benutzt das Reliquiar der Reinheit, um einen Teufelsrankensplitter einzufangen.", progress = "Mit dem Versiegelten Reliquiar der Reinheit in unserem Besitz wird es nicht nur möglich sein, die Bedrohung der Verderbnis von der Welt zu entfernen, sondern sie auch unter unseren umsichtigen Augen zu studieren. Vielleicht können wir sogar neue Möglichkeiten finden, um das Makel der Verderbnis, das Azeroth bedroht, zu bekämpfen.", completion = "Ihr habt Eure Sache gut gemacht, {class}, und deshalb stehe ich für immer in Eurer Schuld. Obwohl der Krieg noch lange nicht vorüber ist, wurde eine große Schlacht gegen die, die unseren Untergang herbeiführen wollen, gewonnen.\n\nBitte nehmt dies als Zeichen meiner endlosen Dankbarkeit. Wenn wir jemals Düsterbruch reinigen, wisset, das Ihr als Held hier immer willkommen sein werdet. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[27104] = { id = 27104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alzzin der Wildformer", description = "Das Monster, das für die Zerstörung, die Ihr vor Euch seht, verantwortlich ist, heißt Alzzin der Wildformer. Um an ihn heranzukommen, müsst Ihr allerdings Zevrim Dornhuf töten, den Satyr, der den immer noch edlen alten Eisenborke der Große in seinen Klauen hält.\n\nSobald Eisenborke frei ist, wird er Euch helfen, Alzzins Herrschaftsgebiet zu betreten. Geht hinein und tötet ihn, ohne Gnade zu zeigen, denn es gibt keine andere Möglichkeit.", sourceObjective = "Tötet Zevrim Dornhuf und Alzzin den Wildformer.", completion = "Ah, sehr gut gemacht. Ihr habt heute einen alten Geist sehr glücklich gemacht. Ihr verdient angemessenen Dank für die Risiken, die Ihr auf Euch genommen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27105] = { id = 27105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ungebetener Gast", description = "Ihr werdet sehen, dass Düsterbruch voller Natur- und Arkanelementaren ist. Irgendwie hat ein Wasserelementar seinen Weg in diese Gegend gefunden. Bitte beschafft Euch seine Essenz und bringt sie zu mir. Ich bin neugierig, wie es hierhergekommen ist und welche Pläne es in Bezug auf die natürlich vorkommenden Elementare von Eldre'Thalas hat.", sourceObjective = "Findet die Hydrobrutessenz.", progress = "Habt Ihr die Essenz bei Euch oder war die Aufgabe zu schwierig?", completion = "Es ist äußerst besorgniserregend, dass ein Wasserelementar hier war - insbesondere so ein mächtiger. Nehmt dies als Dank für Eure Bemühungen. Ich muss diese Essenz untersuchen, ob sie etwas Wissenswertes verbirgt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27106] = { id = 27106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entlarvung eines Schurken", description = "<Ihr findet eine vollständige Liste aller Kultisten des Schattenhammers in Sturmwind.>\n\n<Was noch wichtiger ist, Ihr entdeckt einen Brief von Major Samuelson an seine Komplizen, der den ganzen Plan darlegt. Der Prinz hatte Recht: Samuelson ist der wahre Verbrecher hier, der seine Verbindungen als Kommandant der Stadtwache dazu nutzt, die Aktivitäten des Kults zu verschleiern.>\n\n<Es wird Zeit, nach Burg Sturmwind zurückzukehren und Samuelson zur Rechenschaft zu ziehen!>", sourceObjective = "Enttarnt und tötet Major Samuelson im Thronraum von Burg Sturmwind.", progress = "Ihr habt Beweise, die Samuelson belasten? Schauen wir mal, was er dazu zu sagen hat!", completion = "Samuelson - vom Schattenhammer bestochen? Das muss schon seit Jahren so gehen. Genau hier in meiner Burg!\n\nIch bin sehr dankbar, dass Ihr und mein Sohn dieser Sache auf den Grund gegangen seid, bevor meine Stadt Schaden nehmen konnte. Ich habe wohl unterschätzt, wie erwachsen Anduin bereits geworden ist - seine Beherrschung des heiligen Lichts hat mir gerade das Leben gerettet...wenn nicht sogar das ganze Königreich.\n\nWas Euch angeht - Worte vermögen Euer Heldentum am heutigen Tag nicht zu beschreiben. Ich danke Euch, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27107] = { id = 27107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pusillin der Dieb", description = "Ich nur kurz Nickerchen vorhin gemacht und blöder schneller Wichtel hat gestohlen Buch! Dagg'thol braucht Buch, um Befehle zu befolgen und Meister braucht Buch zum Erobern! Bah!\n\nIhr {race} helft mir, Buch von Wichtel zurückzuholen und ich gebe etwas Glänzendes. Geht, Wichtel ist da links! TÖTEN!!!", sourceObjective = "Überredet Pusillin, das Buch der Zauberformeln herauszugeben.", progress = "{race} hat Buch?", completion = "Jetzt sehen, wie Meister Buch benutzt und Bäume töten und dumme Ziegenmänner! JA!", sourceObjectiveStatus = "unverified-source-field" }
quests[27108] = { id = 27108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lethtendris' Netz", description = "Blutelf Lethtendris hat Netz zum Fangen von Magie hier. Sie benutzt selbst, aber Meister will benutzen um der ganzen Welt gut zu tun. Helft, Netz von dummer Elfe zu holen und Dagg'thol wird Euch belohnen. Dann Ihr seht, wie Meister es viel besser benutzt!", sourceObjective = "Beschafft Lethtendris' Netz.", progress = "{name}, habt Ihr Netz von dummer Elfe?", completion = "Das Netz hat viel Magie! Meister wird jetzt sehr zufrieden sein!\n\nUnd Ihr macht Dagg'thol zufrieden, {race}. Nehmt dies, damit Ihr wisst, wie glücklich Ihr macht Dagg'thol.", sourceObjectiveStatus = "unverified-source-field" }
quests[27109] = { id = 27109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windschiefe Verteidiger", description = "Eisenborke und Wucherborke waren einst die mächtigen Beschützer von Eldre'Thalas. Schaut, was aus ihnen geworden ist! Ihr Schicksal liegt letztendlich in meinen Händen und denen der anderen Hochgeborenen. Wir sind mit unserer Macht unachtsam umgegangen, {race}.\n\nAber Ihr, Ihr könnt das Unrecht wieder ungeschehen machen! Geht hinaus und bettet Tendris Wucherborke zur Ruhe. Er war der mächtigste und letzte Verteidiger dieses Gebiets und er verdient es, dass sein Geist freigelassen wird. Seid vorsichtig, denn wenn Ihr Euch nicht der Beschützer von Eisenborke entledigt, bevor Ihr Tendris angreift, wird er sie zu Hilfe rufen.", sourceObjective = "Tötet Tendris Wucherborke.", completion = "Eure Arbeit hier war ehrenwert. Grämt Euch nicht, denn Tendris Seele hat danach geweint, sich zur Ruhe begeben zu können. Er ist dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[27110] = { id = 27110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der innere Wahnsinn", description = "Dieser Wahnsinn muss ein Ende haben. Das Zeitalter der Unsterblichen ist lange vergangen. Vernichtet die Wächter rings um die Pylonen herum, um das Kraftfeld zu senken. Wenn das erledigt ist, vernichtet Immol'thar. Die Macht des Prinzen wird durch das Dahinscheiden des Dämons stark geschwächt sein. Greift ihn an und beendet seine Existenz. Gewährt den Geistern dieser Stadt ihre letzte Ruhe, Abenteurer, und lasst den Prinzen für seine Schandtaten bezahlen.", sourceObjective = "Zerstört alle Wächter, die um die 5 Pylonen herumstehen, welche Immol'thars Gefängnis mit Energie versorgen Sobald die Pylone deaktiviert wurden, wird sich das Kraftfeld, das Immol'thar umgibt, auflösen.\n\nBetretet Immol'thars Gefängnis und vernichtet den verdorbenen Dämonen. Zum Schluss müsst Ihr Prinz Tortheldrin im Athenaeum entgegentreten.\n\nKehrt nach Abschluss der Aufgabe zur uralten Shen'dralar im Hof zurück.", completion = "Wir sind Euch zu Dank verpflichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27111] = { id = 27111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatz der Shen'dralar", description = "In der Bücherei, dem Athenaeum, werdet Ihr unter dem Treppenaufgang eine uralte Truhe finden. Nehmt Euch aus der Truhe, was Ihr wollt.", sourceObjective = "Kehrt in das Athenaeum zurück und sucht den Schatz der Shen'dralar. Nehmt Euch Eure Belohnung!", completion = "Ihr öffnet die Truhe und findet...", sourceObjectiveStatus = "unverified-source-field" }
quests[27112] = { id = 27112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfluchte Überreste", description = "Es gibt immer noch einige Wesen, die eine Gefahr darstellen, sollten wir diese heilige Stadt zurückerobern wollen. Magister Kalendris und Illyanna Rabeneiche sind beide äußerst gefährlich und wir müssen uns ihrer so schnell wie möglich entledigen.\n\nSeid vorsichtig, denn jetzt, da nur noch so wenige sich von Immol'thars Energien nähren, sind sie wahrscheinlich stärker, als es auf den ersten Blick scheint.", sourceObjective = "Tötet Magister Kalendris und Illyanna Rabeneiche.", completion = "Euer Engagement wird all dies so viel einfacher machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27113] = { id = 27113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Uralte Shen'dralar", description = "Einige Wesen haben es auf wundersame Weise geschafft, der Dunkelheit zu entgehen, die hier ihr Unwesen treibt. Auf der zweiten Etage am Hof der Hochgeborenen ruht ein Uralter Shen'dralar. Sucht ihn auf, er ist möglicherweise ein unerschöpflicher Quell der Weisheit und kennt vielleicht sogar das Geheimnis, wie man Eldre'Thalas befreit.", sourceObjective = "Sprecht mit dem Uralten Shen'dralar.", completion = "Unser Treffen ist kein Zufall, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27114] = { id = 27114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gordokgeschmackstest", sourceObjective = "Ihr seid nun großer Boss, also kriegt ihr kostenlose Probe meiner guten Gebräue! Diese Getränke stärken Euch UND geben eine gute Dröhnung! Das ist gutes Zeug, Chef... probiert sie und erzählt Kreeg davon!", sourceObjectiveStatus = "unverified-source-field" }
quests[27115] = { id = 27115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andos Ruf", description = "Ihr habt hier großartige Arbeit geleistet, {name}. Als Ihr fort wart, hat dieser junge Bursche Ando nach Euch gesucht. Sagte was von einem Metallvogel.\n\nVielleicht solltet Ihr zu den Ufern des Loch zurückkehren und nachsehen, was er wollte.", sourceObjective = "Sprecht mit Ando Blastenheimer.", completion = "Es funktioniert! Mein Vater hat es geschafft!", sourceObjectiveStatus = "unverified-source-field" }
quests[27116] = { id = 27116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Winde von Loch Modan", description = "Vater hat den Himmelsschreiter fertiggestellt. Er ist großartig! Wenn wir erst einmal die Kinderkrankheiten ausgemerzt haben, werde ich ihn benutzen, um für die Gerechtigkeit zu kämpfen - genau, wie Ihr.\n\nIch weiß, Ihr müsst weiterziehen und anderen Menschen helfen. Schließlich seid Ihr ein Held und so, aber wie wäre es mit einem Probeflug? Ich will den Himmelsschreiter gerade zu seinem Jungfernflug hinausbringen und es wäre mir eine Ehre, wenn Ihr Euch mir anschließen würdet. Ich setze Euch bei der Station Algaz ab.\n\nWas meint Ihr?", sourceObjective = "Fliegt mit dem Himmelsschreiter zur Station Algaz und sprecht dann mit Gebirgsjäger Sturmlanze.", completion = "Was zum Henker WAR das? Ein fliegender Mechanoschreiter?\n\nWisst Ihr was, ich will es gar nicht wissen. Ich tue einfach so, als wäre das nicht passiert und wir unterhalten uns nett wie Geschäftsleute.", sourceObjectiveStatus = "unverified-source-field" }
quests[27117] = { id = 27117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rohe Gewalt", description = "Gandling hat seinen Leutnant, den Ravenier, zur Unterstützung mitgebracht. Dieser trampelnde Rohling ist viel gefährlicher als jede andere Geißel und Monstrosität, die Euch auf dem Schlachtfeld begegnen wird.\n\nDer Ravenier befindet sich in einem Turm am südlichen Ende des Orts. Ich empfehle Umsicht, bevor Ihr mit ihm kämpft, {name}. Er ist kein leichter Gegner.", sourceObjective = "Tötet den Ravenier in Andorhal.", completion = "Ausgezeichnet gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27118] = { id = 27118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine beschädigte Falle", sourceObjective = "Eine große, beschädigte Falle liegt vor Euch. Es sieht so aus, als hätten die Oger erfolglos versucht, sie zu reparieren.\n\nNeben der Falle liegt eine hastig geschriebene Notiz, die seltsamerweise genau beschreibt, wie sie zu reparieren ist. Ein paar Handgriffe reichen. In einer reparierten Falle würde sich ein Oger, der nahe an ihr vorbeigeht, vielleicht verfangen und könnte vermieden werden.\n\nEs ist wirklich gut, dass so wenige Oger lesen können.\n\nWirklich.", sourceObjectiveStatus = "unverified-source-field" }
quests[27119] = { id = 27119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ogeranzug der Gordok", description = "Wenn Ihr vorhabt, gegen den König der Gordok zu kämpfen, dann werden Ihr es erstmal an Hauptmann Krombruch vorbei schaffen müssen. Sicher könnt Ihr ihn einfach töten. Doch vielleicht wollt Ihr diesen Oger ja am Leben lassen. \n\nEs stellt sich nur die Frage, wie? Ich glaube ich weiß, wie! Ein Ogeranzug! Ich kann Euch einen herstellen, der ausreicht, um diese Kerle zu täuschen, wenn Ihr mir Ogergerbemittel von oben herbringt. So wie die Dinge stehen, gehe ich nirgendwohin.", sourceObjective = "Bringt etwas Ogergerbemittel zu Knot Zwingschraub.", progress = "Bringt mir einfach dieses Ogergerbemittel und ich stelle Euch einen Anzug her, der Hauptmann Krombruch glauben lassen wird, dass Ihr einer seiner Männer seid.", completion = "Das sollte gehen. Ein Schnitt hier, ein Stich da... - das wird ein richtiges Meisterwerk! <Ein breites Grinsen zeichnet sich im Gesicht des Goblins ab.>\n\nHier, damit seid Ihr vorbereitet. Denkt daran - der Ogeranzug ist alles andere als haltbar. Nachdem Ihr ihn angezogen habt, bleiben Euch zehn Minuten bevor er auseinanderfällt und dann ist's aus mit der Täuschung! Benutzt ihn erst kurz bevor Ihr Krombruch begegnet, damit er so lange hält, wie Ihr ihn braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27120] = { id = 27120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ogeranzug der Gordok", progress = "Braucht wohl einen neuen Anzug, oder? Na, ich werde wohl eh noch eine Weile hier sein - bringt mir noch ein Ogergerbemittel, dann mache ich Euch einen neuen Ogeranzug.", completion = "Bitte schön, {name} - leg das Ding an, dann habt Ihr zehn Minuten Zeit, irgendwas zu tun. Viel Glück!\n\nOh, und solltet Ihr zufällig einen Schlüssel finden, mit dem ich hier raus komme, LASST MICH DAS RUHIG WISSEN!!!" }
quests[27123] = { id = 27123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefenheim, Reich der Erde", description = "Ich wusste, Ihr würdet unserem Ruf Folge leisten, {name}. Als Todesschwinge das erste Mal von den anderen Drachenaspekten besiegt wurde, zog er sich nach Tiefenheim, im Reich der Erde, zurück.\n\nTodesschwinges Rückkehr in unsere Welt hinterließ einen Riss zwischen Azeroth und Tiefenheim.\n\nWenn wir die Lücke nicht schließen, wird dieses Land auseinandergerissen werden. Wir tun unser Bestes, um den Schaden, der diesseits des Risses entsteht, in Grenzen zu halten. Aggra wird Euch durch den Riss mitnehmen, damit Ihr helfen könnt, den Schaden von der anderen Seite aus zu reparieren.\n\nSchwingt Euch auf ihren Wyvern, wenn Ihr bereit seid.", sourceObjective = "Springt auf Aggras Wyvern und fliegt in die Bresche am Mahlstrom. Wenn Ihr auf der anderen Seite ankommt, sprecht mit Maruut Steinbinder.", completion = "Ihr seid genau rechtzeitig eingetroffen, {name}. All unsere Helfer sind damit beschäftigt, den Riss zu stabilisieren.\n\nWir brauchen jemanden, der uns dabei hilft, die Fragmente der Weltensäule zu finden.", sourceObjectiveStatus = "unverified-source-field" }
